window.H=window.H||{};H[35]={"35회-1차-008":{"한줄":"수요와 공급이 함께 감소하면 폭의 크기와 관계없이 균형거래량은 감소한다.","근거":[{"이론":"수요·공급 동시 변화의 균형 분석","내용":"수요와 공급이 같은 방향으로 움직이면 거래량의 방향은 확정되고 가격 방향은 폭 비교로 정해진다. 반대 방향으로 움직이면 가격 방향이 확정되고 거래량 방향이 폭 비교로 정해진다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수요·공급이 모두 증가하면 균형거래량은 증가한다. 폭이 같으면 가격은 변하지 않는다."},{"번호":2,"판정":"틀림","설명":"수요 증가·공급 감소는 모두 가격을 올리는 방향이어서 폭과 관계없이 균형가격은 상승한다."},{"번호":3,"판정":"틀림","설명":"수요 감소·공급 증가는 모두 가격을 내리는 방향이어서 균형가격은 하락한다."},{"번호":4,"판정":"옳음","설명":"수요·공급이 모두 감소하면 균형거래량은 감소한다. 공급 감소폭이 더 크므로 가격은 상승한다."},{"번호":5,"판정":"틀림","설명":"수요 증가·공급 감소는 균형가격을 상승시킨다. 폭이 같으면 거래량이 변하지 않는다."}],"개념":[{"종류":"표","제목":"수요·공급 동시 변화 결과","머리":["수요","공급","균형가격","균형거래량"],"행":[["증가","증가","폭 비교(수요폭이 크면 상승, 공급폭이 크면 하락, 같으면 불변)","증가"],["감소","감소","폭 비교(수요폭이 크면 하락, 공급폭이 크면 상승, 같으면 불변)","감소"],["증가","감소","상승","폭 비교(수요폭이 크면 증가, 공급폭이 크면 감소, 같으면 불변)"],["감소","증가","하락","폭 비교(수요폭이 크면 감소, 공급폭이 크면 증가, 같으면 불변)"]]}],"함정":"수요 증가와 공급 감소가 겹칠 때 폭 비교로 가격이 갈린다고 착각한다. 둘 다 가격을 올리는 방향이라 가격은 확정이고, 폭 비교는 거래량에만 필요하다."},"35회-1차-027":{"한줄":"자본환원율은 시장금리와 같은 방향으로 움직이므로 금리가 오르면 자본환원율도 오른다.","근거":[{"이론":"자본환원율","내용":"자본환원율 = 순영업소득 ÷ 부동산 가격. 무위험률(금리) + 위험할증률 − 예상 소득성장률로 구성되며 자본의 기회비용을 반영한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"순영업소득을 가격으로 나눈 값이 자본환원율(종합환원율)이다."},{"번호":2,"판정":"옳음","설명":"시장이 균형이어도 유형·위치마다 위험과 성장률이 달라 자본환원율이 서로 다를 수 있다."},{"번호":3,"판정":"틀림","설명":"금리가 오르면 자본의 기회비용이 커져 자본환원율이 높아진다. 환원율을 낮추는 요인은 금리 하락, 위험 감소, 소득 성장률 상승이다."},{"번호":4,"판정":"옳음","설명":"투자위험이 커지면 위험할증률이 올라 자본환원율이 높아진다."},{"번호":5,"판정":"옳음","설명":"유형·지역이 다른 시장의 기대수익 수준을 환원율로 비교할 수 있다."}],"개념":[{"종류":"표","제목":"자본환원율을 움직이는 요인","머리":["요인","변화","자본환원율","부동산 가치"],"행":[["시장금리(무위험률)","상승","상승","하락"],["투자위험(위험할증률)","증가","상승","하락"],["소득 성장률","상승","하락","상승"],["유동성(환금성)","높음","하락","상승"],["경기 호황·시장 활황","지속","하락","상승"]]},{"종류":"표","제목":"환원율의 종류","머리":["종류","식","비고"],"행":[["종합환원율(자본환원율)","순영업소득 ÷ 부동산 가격","가장 기본"],["지분환원율","세전현금수지 ÷ 지분투자액","자기자본 기준"],["저당환원율(저당상수)","연간 부채서비스액 ÷ 대출금","융자 기준"],["종합환원율의 결합","지분비율 × 지분환원율 + 저당비율 × 저당환원율","금융적 결합법"]]}],"함정":"금리와 환원율의 방향을 반대로 외우면 3번을 맞는 문장으로 읽는다. 환원율이 오르면 같은 순영업소득에서 가격이 내려간다는 관계까지 같이 잡아야 한다."},"35회-1차-034":{"한줄":"MBB는 발행기관이 모기지 풀을 담보로 발행하는 채권이어서 원리금 상환과 위험을 발행기관이 지고, 투자자는 채무불이행·조기상환위험을 지지 않는다.","근거":[{"이론":"주택저당담보부채권(MBB)","내용":"채권형 증권이다. 모기지 소유권과 위험은 발행기관에 남고, 초과담보를 제공한다. 투자자는 발행기관 지급 능력에 따라 원리금을 받는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"MBB는 지분이 아니라 채권 성격의 증권이다. 지분형은 MPTS다."},{"번호":2,"판정":"틀림","설명":"차입자가 낸 원리금이 투자자에게 직접 전달되는 증권은 MPTS(이체증권)다. MBB 투자자는 발행기관이 지급하는 이자와 원금을 받는다."},{"번호":3,"판정":"틀림","설명":"MBB 발행자는 채권 안전성을 위해 모기지 풀 가치보다 많은 담보(초과담보)를 제공한다."},{"번호":4,"판정":"틀림","설명":"MBB는 현금흐름이 확정된 채권형이라 MPTS보다 안정적이다."},{"번호":5,"판정":"옳음","설명":"채무불이행위험과 조기상환위험은 모기지를 보유한 발행기관이 부담한다."}],"개념":[{"종류":"표","제목":"주택저당증권(MBS) 종류 비교","머리":["구분","증권 성격","원리금 수취·지급","조기상환·채무불이행 위험"],"행":[["MPTS(이체증권)","지분형","차입자 원리금이 투자자에게 직접 이체","투자자 부담"],["MBB(저당담보부채권)","채권형(초과담보)","발행기관이 약정 이자·원금 지급","발행기관 부담"],["MPTB(이체채권)","채권형·혼합","발행기관이 수취 후 투자자에게 지급","채무불이행: 발행기관 / 조기상환: 투자자"],["CMO(다계층채권)","채권형","트랜치(만기·상환순위)별로 배분","트랜치별로 다르게 배분"]]},{"종류":"흐름","제목":"주택저당증권 발행 구조","단계":[{"이름":"1차 시장","설명":"금융기관이 차입자에게 주택저당대출 실행"},{"이름":"풀 구성","설명":"비슷한 조건의 대출채권을 묶어 모기지 풀 형성"},{"이름":"유동화","설명":"유동화기관이 모기지 풀을 양도·담보로 받음"},{"이름":"증권 발행","설명":"MPTS·MPTB·MBB·CMO 등 형태로 투자자에게 발행"},{"이름":"자금 순환","설명":"발행대금이 대출기관에 돌아가 새 대출 재원이 됨"}]}],"함정":"MBB는 이름에 '담보부채권'이 있어 채권형이라는 점부터 확인해야 한다. 1번(지분형)·2번(직접 전달)은 MPTS 설명이다."},"35회-1차-005":{"한줄":"환지방식은 개발계획 수립과 조합 설립 인가에서 토지소유자 동의를 받아야 해서 동의 절차가 수용방식보다 많고 복잡하다.","근거":[{"법령":"도시개발법","조문":"제4조제4항","원문":"지정권자는 환지(換地) 방식의 도시개발사업에 대한 개발계획을 수립하려면 환지 방식이 적용되는 지역의 토지면적의 3분의 2 이상에 해당하는 토지 소유자와 그 지역의 토지 소유자 총수의 2분의 1 이상의 동의를 받아야 한다."},{"법령":"도시개발법","조문":"제13조제3항","원문":"제1항에 따라 조합 설립의 인가를 신청하려면 해당 도시개발구역의 토지면적의 3분의 2 이상에 해당하는 토지 소유자와 그 구역의 토지 소유자 총수의 2분의 1 이상의 동의를 받아야 한다."},{"법령":"도시개발법","조문":"제22조제1항","원문":"시행자는 도시개발사업에 필요한 토지등을 수용하거나 사용할 수 있다. 다만, 제11조제1항제5호 및 제7호부터 제11호까지의 규정(…)에 해당하는 시행자는 사업대상 토지면적의 3분의 2 이상에 해당하는 토지를 소유하고 토지 소유자 총수의 2분의 1 이상에 해당하는 자의 동의를 받아야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수용 보상금으로 대토를 구하는 수요가 구역 밖 토지로 몰려 구역 밖 지가가 오를 수 있다."},{"번호":2,"판정":"옳음","설명":"수용방식은 토지를 사들여 조성한 뒤 팔아 사업비를 회수하므로 조성토지 매각부담이 크다. 환지방식은 체비지 매각만 한다."},{"번호":3,"판정":"옳음","설명":"환지방식은 토지를 사들이지 않고 환지로 돌려주므로 보상비 부담이 없어 사업비 부담이 작다."},{"번호":4,"판정":"옳음","설명":"환지방식은 종전 토지소유자가 환지된 토지를 그대로 가지므로 개발이익이 소유자에게 귀속될 가능성이 크다."},{"번호":5,"판정":"틀림","설명":"지방공사 등(제11조제1항제1호~4호)이 시행하는 수용방식은 소유자 동의가 필요 없다(제22조제1항). 환지방식은 개발계획 수립 때와 조합 설립 인가 때 동의가 필요하다(제4조제4항, 제13조제3항)."}],"개념":[{"종류":"표","제목":"수용·사용방식과 환지방식","머리":["구분","수용·사용방식","환지방식"],"행":[["토지 취득","매수·수용 후 보상","소유자에게 환지로 돌려줌"],["사업비 부담","보상비 때문에 큼","작음(보상비 없음)"],["조성토지 매각","전체 매각해 사업비 회수(부담 큼)","체비지 매각으로 사업비 충당"],["개발이익","시행자(공공)에 귀속","종전 소유자에 귀속 가능성 큼"],["지가 파급","대토 수요로 구역 밖 지가 상승 가능","구역 안 재정착, 상승 요인 작음"],["소유자 동의","공공시행자는 불필요","개발계획 수립·조합 설립 때 필요"]]},{"종류":"표","제목":"도시개발법상 동의 요건","머리":["단계","토지면적","소유자 총수","조문"],"행":[["환지방식 개발계획 수립","3분의 2 이상","2분의 1 이상","제4조제4항"],["조합 설립 인가 신청","3분의 2 이상","2분의 1 이상","제13조제3항"],["수용·사용(민간 등 일부 시행자)","3분의 2 이상 소유","2분의 1 이상 동의","제22조제1항 단서"]]}],"함정":"환지방식이 보상 없이 소유자에게 돌려주는 방식이라는 인상 때문에 '절차가 간단하다'고 읽기 쉽다. 동의 단계 수는 환지방식이 더 많다."},"35회-1차-049":{"한줄":"혼동은 제145조가 정한 법정추인 사유 여섯 가지에 들지 않으므로 1번이 정답이다.","근거":[{"법령":"민법","조문":"제145조","원문":"제145조(법정추인) 취소할 수 있는 법률행위에 관하여 전조의 규정에 의하여 추인할 수 있는 후에 다음 각호의 사유가 있으면 추인한 것으로 본다. 그러나 이의를 보류한 때에는 그러하지 아니하다. 1. 전부나 일부의 이행 2. 이행의 청구 3. 경개 4. 담보의 제공 5. 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도 6. 강제집행"},{"법령":"민법","조문":"제144조","원문":"제144조(추인의 요건) ① 추인은 취소의 원인이 소멸된 후에 하여야만 효력이 있다. ② 제1항은 법정대리인 또는 후견인이 추인하는 경우에는 적용하지 아니한다."}],"선지":[{"번호":1,"판정":"-","설명":"혼동은 법정추인 사유가 아니다. 제145조 각호에 없다."},{"번호":2,"판정":"-","설명":"경개는 법정추인 사유다(제145조 제3호)."},{"번호":3,"판정":"-","설명":"취소권자의 이행청구는 법정추인 사유다(제145조 제2호)."},{"번호":4,"판정":"-","설명":"강제집행은 법정추인 사유다(제145조 제6호)."},{"번호":5,"판정":"-","설명":"취소권자인 채무자가 담보를 제공하면 법정추인 사유다(제145조 제4호)."}],"개념":[{"종류":"표","제목":"법정추인 사유 6가지와 비사유","머리":["구분","내용"],"행":[["사유 1","전부나 일부의 이행"],["사유 2","이행의 청구"],["사유 3","경개"],["사유 4","담보의 제공"],["사유 5","취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도"],["사유 6","강제집행"],["비사유","혼동, 상계, 해제 등 제145조에 없는 행위"]]},{"종류":"흐름","제목":"법정추인이 인정되는 과정","단계":[{"이름":"취소원인 소멸","설명":"추인은 취소원인이 소멸한 후에 해야 효력이 있음(제144조 제1항). 법정대리인·후견인은 예외(제144조 제2항)"},{"이름":"법정추인 사유 발생","설명":"추인할 수 있는 시기 이후에 제145조 각호 사유가 있어야 함"},{"이름":"이의 보류 없음","설명":"이의를 보류하면 추인으로 보지 않음(제145조 단서)"},{"이름":"추인 간주","설명":"추인한 것으로 보아 이후 취소 불가(제143조 제1항)"}]}],"함정":"정답률이 33%다. 혼동과 상계 같은 소멸 원인을 법정추인 사유로 착각한 오답이 나온다. 사유는 이행·이행청구·경개·담보·양도·강제집행 여섯 가지뿐이다."},"35회-1차-055":{"한줄":"공유자는 자기 지분에 관한 권리를 단독으로 행사할 수 있으므로 자기 지분에 대한 취득시효를 단독으로 중단시킬 수 있고, 4번이 틀리다.","근거":[{"법령":"민법","조문":"제263조","원문":"제263조(공유지분의 처분과 공유물의 사용, 수익) 공유자는 그 지분을 처분할 수 있고 공유물 전부를 지분의 비율로 사용, 수익할 수 있다."},{"법령":"민법","조문":"제264조","원문":"제264조(공유물의 처분, 변경) 공유자는 다른 공유자의 동의없이 공유물을 처분하거나 변경하지 못한다."},{"법령":"민법","조문":"제265조","원문":"제265조(공유물의 관리, 보존) 공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다. 그러나 보존행위는 각자가 할 수 있다."},{"법령":"민법","조문":"제408조","원문":"제408조(분할채권관계) 채권자나 채무자가 수인인 경우에 특별한 의사표시가 없으면 각 채권자 또는 각 채무자는 균등한 비율로 권리가 있고 의무를 부담한다. 제2관 불가분채권과 불가분채무"},{"판례":"대법원 1979. 6. 26. 선고 79다639 판결","요지":"공유자 한 사람이 공유물 보존행위로 제소한 경우 시효중단의 효력은 제소한 공유자에게만 생기고 다른 공유자의 지분에는 미치지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"보존행위는 각 공유자가 단독으로 할 수 있다(제265조 단서)."},{"번호":2,"판정":"옳음","설명":"공유자는 공유물 전부를 지분의 비율로 사용·수익할 수 있다(제263조)."},{"번호":3,"판정":"옳음","설명":"공유물의 처분·변경에는 다른 공유자의 동의가 필요하다(제264조)."},{"번호":4,"판정":"틀림","설명":"공유자는 자기 지분을 자유롭게 처분하고 지분에 관한 권리를 단독으로 행사한다(제263조). 자기 지분에 대한 취득시효 중단도 단독으로 할 수 있고, 그 효력은 자기 지분에 한한다(79다639)."},{"번호":5,"판정":"옳음","설명":"차임 상당 부당이득반환채권은 금전채권으로 분할채권이어서 각 공유자에게 지분 비율로 귀속한다(제408조)."}],"개념":[{"종류":"표","제목":"공유·합유·총유 비교","머리":["구분","공유","합유","총유"],"행":[["성립","지분에 의한 수인의 소유(제262조)","조합체로서 소유(제271조)","법인 아닌 사단의 사원이 집합체로서 소유(제275조)"],["지분 처분","자유(제263조)","전원 동의(제273조 제1항)","지분 개념 없음"],["분할청구","가능(제268조)","조합 존속 중 불가(제273조 제2항)","사원 지위와 분리 불가"],["처분·변경","전원 동의(제264조)","전원 동의(제272조)","사원총회 결의(제276조 제1항)"],["보존행위","각자(제265조 단서)","각자(제272조 단서)","사원총회 결의"]]},{"종류":"표","제목":"공유물에 관한 행위의 요건","머리":["행위","요건","근거"],"행":[["처분·변경","공유자 전원 동의","제264조"],["관리","지분의 과반수","제265조 본문"],["보존","각자 단독","제265조 단서"],["지분 처분","단독으로 자유","제263조"],["지분 포기","다른 공유자에게 지분 비율로 귀속","제267조"],["분할 금지 약정","5년 내의 기간으로 가능","제268조 제1항"]]}],"함정":"보존행위를 단독으로 할 수 있다는 것과 자기 지분의 권리 행사가 단독이라는 것을 구분해야 한다. 4번은 자기 지분의 시효중단까지 막는 문장이다. 시효중단의 효력이 다른 공유자 지분에 미친다고 보면 오답이다."},"35회-1차-061":{"한줄":"유치권은 유치하는 효력만 있고 우선변제권이 없어서, 소멸주의로 경매가 되어도 유치권자는 일반채권자보다 먼저 배당받지 못한다.","근거":[{"법령":"민법","조문":"제320조제1항","원문":"제320조(유치권의 내용) ①타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우에는 변제를 받을 때까지 그 물건 또는 유가증권을 유치할 권리가 있다."},{"법령":"민법","조문":"제322조제1항","원문":"제322조(경매, 간이변제충당) ①유치권자는 채권의 변제를 받기 위하여 유치물을 경매할 수 있다."},{"법령":"민법","조문":"제324조제2항·제3항","원문":"제324조(유치권자의 선관의무) ②유치권자는 채무자의 승낙없이 유치물의 사용, 대여 또는 담보제공을 하지 못한다. 그러나 유치물의 보존에 필요한 사용은 그러하지 아니하다. ③유치권자가 전2항의 규정에 위반한 때에는 채무자는 유치권의 소멸을 청구할 수 있다."},{"법령":"민법","조문":"제326조","원문":"제326조(피담보채권의 소멸시효) 유치권의 행사는 채권의 소멸시효의 진행에 영향을 미치지 아니한다."},{"판례":"대법원 1994. 10. 14. 선고 93다62119 판결","요지":"건물 임차인의 권리금반환청구권은 건물에 관하여 생긴 채권이 아니어서 이를 근거로 건물에 유치권을 행사할 수 없다."},{"판례":"대법원 2009. 9. 24. 선고 2009다40684 판결","요지":"공사대금채권으로 유치권을 행사하는 자가 유치물인 주택에 거주하며 사용하는 것은 특별한 사정이 없는 한 보존에 필요한 사용이다."},{"판례":"대법원 2008. 5. 30.자 2007마98 결정","요지":"독립한 건물이 되지 못한 정착물은 토지의 부합물이어서 공사대금채권으로 그 정착물이나 토지에 유치권을 행사할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"권리금반환청구권은 건물 자체에서 생긴 채권이 아니다(93다62119)."},{"번호":2,"판정":"옳음","설명":"유치권을 행사해도 피담보채권의 소멸시효는 그대로 진행한다(제326조)."},{"번호":3,"판정":"옳음","설명":"주택 거주는 훼손 방지에 도움이 되는 보존 사용이라 채무자가 소멸청구를 못 한다(2009다40684, 제324조 제2항 단서)."},{"번호":4,"판정":"틀림","설명":"민법은 유치권자에게 우선변제권을 주지 않는다(제320조·제322조). 경매권(제322조 제1항)은 환가 수단일 뿐 배당 순위는 일반채권자와 같다."},{"번호":5,"판정":"옳음","설명":"독립한 건물에 이르지 못한 정착물은 토지에 부합하므로 수급인 소유가 아니고 유치권 대상도 아니다(2007마98)."}],"개념":[{"종류":"표","제목":"유치권 견련성 판단 사례","머리":["피담보채권","견련성","이유"],"행":[["임차인의 필요비·유익비상환청구권","인정","임차물 자체에 지출한 비용(제626조)"],["임차보증금반환청구권","부정","목적물에 관해 생긴 채권이 아님(판례)"],["권리금반환청구권","부정","영업재산 이전에서 생긴 별개 법률관계(93다62119)"],["건축자재 공급대금(매매대금)채권","부정","건물에 관해 생긴 채권이 아님(판례)"],["건물 신축 수급인의 공사대금","인정","수급인이 점유하는 그 건물에 관한 채권. 독립 건물이 못 된 정착물·토지는 제외(2007마98)"]]},{"종류":"비교","제목":"유치권자의 사용과 소멸청구","왼쪽":{"이름":"채무자 승낙 없이 가능","항목":["보존에 필요한 사용","주택에 거주하며 사용(2009다40684)"]},"오른쪽":{"이름":"채무자 승낙 필요","항목":["유치물의 일반 사용","대여","담보제공","위반 시 채무자의 소멸청구(제324조 제3항)"]}}],"함정":"4번을 맞다고 보기 쉽다. 경매를 신청할 수 있다는 점과 우선변제를 받는다는 점은 별개다. 유치권은 점유를 근거로 변제를 압박하는 권리라 배당에서는 일반채권자다. 1번은 보증금·권리금을 한꺼번에 유치권 불가로 외우면 풀린다."},"35회-1차-071":{"한줄":"제548조 제1항 단서의 제3자는 해제된 계약에서 생긴 법률효과를 기초로 등기·인도 등으로 권리를 취득한 자인데, 등기청구권을 압류한 자는 아직 그 권리를 취득하지 않았다.","근거":[{"법령":"민법","조문":"제548조제1항","원문":"제548조(해제의 효과, 원상회복의무) ①당사자 일방이 계약을 해제한 때에는 각 당사자는 그 상대방에 대하여 원상회복의 의무가 있다. 그러나 제삼자의 권리를 해하지 못한다."},{"판례":"대법원 2013다14569 판결","요지":"제3자는 해제된 계약으로부터 생긴 법률효과를 기초로 해제 전에 새로운 이해관계를 갖고 등기·인도 등으로 권리를 취득한 자다. 매수인과 매매예약을 하고 소유권이전청구권 보전 가등기를 마친 자도 포함된다."},{"판례":"대법원 2005. 1. 14. 선고 2003다33004 판결","요지":"해제 전 가압류채권자도 제548조 제1항 단서의 제3자에 해당한다."},{"판례":"대법원 판례(등기청구권 압류)","요지":"매수인의 소유권이전등기청구권을 압류·가압류한 채권자는 목적 부동산에 관한 권리를 취득하지 않았으므로 제3자에 해당하지 않는다."}],"선지":[{"번호":1,"판정":"-","설명":"제3자에 해당하지 않는다. 채권(등기청구권)을 압류했을 뿐 부동산에 대한 권리를 등기·인도로 취득하지 않았다."},{"번호":2,"판정":"-","설명":"제3자에 해당한다. 해제 전 부동산을 가압류한 채권자는 보호된다(2003다33004)."},{"번호":3,"판정":"-","설명":"제3자에 해당한다. 등기된 소유권을 기초로 저당권을 취득했다."},{"번호":4,"판정":"-","설명":"제3자에 해당한다. 가등기를 마친 자도 포함된다(2013다14569)."},{"번호":5,"판정":"-","설명":"제3자에 해당한다. 대항요건을 갖춘 주택임차인은 인도와 전입신고로 권리를 취득한 자다(판례)."}],"개념":[{"종류":"표","제목":"제548조 제1항 단서의 제3자","머리":["권리자","제3자 해당","이유"],"행":[["해제 전 소유권 취득자(등기)","해당","완전한 권리 취득"],["저당권자(등기)","해당","등기로 권리 취득"],["부동산 가압류채권자","해당","2003다33004"],["소유권이전청구권 보전 가등기권자","해당","2013다14569"],["대항요건을 갖춘 주택임차인","해당","인도·전입신고로 권리 취득"],["매수인의 소유권이전등기청구권 압류·가압류채권자","비해당","목적물에 관한 권리를 아직 취득하지 않음"],["등기·인도 없는 매수인의 일반채권자","비해당","권리 취득 없음"]]},{"종류":"흐름","제목":"계약 해제의 효과","단계":[{"이름":"해제 의사표시","설명":"상대방에 대한 의사표시, 철회 불가(제543조)"},{"이름":"소급 소멸","설명":"계약이 처음부터 없던 것으로 됨"},{"이름":"원상회복","설명":"각 당사자의 원상회복의무, 반환 금전에 받은 날부터 이자 가산(제548조)"},{"이름":"동시이행","설명":"원상회복의무는 동시이행(제549조)"},{"이름":"손해배상","설명":"해제는 손해배상 청구에 영향 없음(제551조)"}]}],"함정":"정답률이 14%였던 문항이다. 압류와 가압류를 같은 취급으로 외우면 2번과 1번을 맞바꾼다. 부동산을 가압류한 자(2번)는 제3자이고, 등기청구권을 압류한 자(1번)는 제3자가 아니다. 목적물에 대한 권리 취득 여부가 기준이다."},"35회-2차-001":{"한줄":"국토교통부장관이 직접 시험문제를 출제하거나 시행하려면 정책심의위원회의 의결을 미리 거쳐야 한다(영 제3조).","근거":[{"법령":"공인중개사법 시행령","조문":"제3조","원문":"제3조(국토교통부장관이 시행하는 자격시험) 국토교통부장관이 법 제4조제2항에 따라 직접 시험문제를 출제하거나 시험을 시행하려는 경우에는 심의위원회의 의결을 미리 거쳐야 한다."},{"법령":"공인중개사법","조문":"제2조의2제1항·제3항","원문":"① 공인중개사의 업무에 관한 다음 각 호의 사항을 심의하기 위하여 국토교통부에 공인중개사 정책심의위원회를 둘 수 있다.\n1. 공인중개사의 시험 등 공인중개사의 자격취득에 관한 사항\n2. 부동산 중개업의 육성에 관한 사항\n3. 중개보수 변경에 관한 사항\n4. 손해배상책임의 보장 등에 관한 사항\n③ 제1항에 따라 공인중개사 정책심의위원회에서 심의한 사항 중 제1호의 경우에는 특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다)는 이에 따라야 한다."},{"법령":"공인중개사법 시행령","조문":"제1조의3제4항","원문":"④ 국토교통부장관은 위원이 제1항 각 호의 어느 하나에 해당하는 데에도 불구하고 회피하지 아니한 경우에는 해당 위원을 해촉(解囑)할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"위원회는 국무총리 소속이 아니라 국토교통부에 둔다(법 제2조의2제1항)."},{"번호":2,"판정":"틀림","설명":"손해배상책임의 보장 등에 관한 사항은 제4호 심의사항이다(법 제2조의2제1항제4호)."},{"번호":3,"판정":"틀림","설명":"회피하지 않은 위원을 해촉할 수 있는 사람은 위원장이 아니라 국토교통부장관이다(영 제1조의3제4항)."},{"번호":4,"판정":"틀림","설명":"시·도지사가 따라야 하는 것은 제1호 자격취득 사항뿐이다. 중개보수 변경은 제3호 사항이라 따를 의무가 없다(법 제2조의2제3항)."},{"번호":5,"판정":"옳음","설명":"장관이 직접 출제·시행하는 경우 위원회 의결을 미리 거친다(영 제3조)."}],"개념":[{"종류":"표","제목":"정책심의위원회 심의사항과 시·도지사의 구속","머리":["심의사항","근거","시·도지사가 따를 의무"],"행":[["공인중개사 시험 등 자격취득","법 제2조의2제1항제1호","있음(제3항)"],["부동산 중개업의 육성","제1항제2호","없음"],["중개보수 변경","제1항제3호","없음"],["손해배상책임의 보장 등","제1항제4호","없음"]]},{"종류":"표","제목":"정책심의위원회 구성·운영","머리":["사항","내용","근거"],"행":[["설치","국토교통부에 둘 수 있음(임의 설치)","법 제2조의2제1항"],["구성","위원장 1명을 포함한 7명 이상 11명 이내","영 제1조의2제1항"],["위원장","국토교통부 제1차관","영 제1조의2제2항"],["위원 임명·위촉","국토교통부장관","영 제1조의2제2항"],["위원장 직무대행","위원장이 미리 지명한 위원","영 제1조의4제2항"],["개의·의결","재적위원 과반수 출석, 출석위원 과반수 찬성","영 제1조의5제2항"],["기피 신청 결정","심의위원회 의결(대상 위원은 의결 참여 불가)","영 제1조의3제2항"],["회피하지 않은 위원 해촉","국토교통부장관","영 제1조의3제4항"]]}],"함정":"3번이 가장 고르기 쉽다. 회의를 이끄는 사람이 위원장이라 해촉도 위원장이 한다고 짐작하지만 해촉권자는 국토교통부장관이다. 4번은 중개보수 변경까지 시·도지사가 따라야 한다고 범위를 넓힌 문장이다."},"35회-2차-018":{"한줄":"법 제42조의4의 개선명령 여섯 가지에 공제사업의 양도는 들어 있지 않다.","근거":[{"법령":"공인중개사법","조문":"제42조의4","원문":"국토교통부장관은 협회의 공제사업 운영이 적정하지 아니하거나 자산상황이 불량하여 중개사고 피해자 및 공제 가입자 등의 권익을 해칠 우려가 있다고 인정하면 다음 각 호의 조치를 명할 수 있다. 1. 업무집행방법의 변경 2. 자산예탁기관의 변경 3. 자산의 장부가격의 변경 4. 불건전한 자산에 대한 적립금의 보유 5. 가치가 없다고 인정되는 자산의 손실 처리 6. 그 밖에 이 법 및 공제규정을 준수하지 아니하여 공제사업의 건전성을 해할 우려가 있는 경우 이에 대한 개선명령"}],"선지":[{"번호":1,"판정":"옳음","설명":"손실 처리 명령은 제5호에 해당한다."},{"번호":2,"판정":"틀림","설명":"개선명령 항목에 양도가 없다. 제1호~제6호는 업무집행방법, 자산예탁기관, 장부가격, 적립금, 손실 처리, 준수 명령뿐이다(법 제42조의4)."},{"번호":3,"판정":"옳음","설명":"적립금 보유 명령은 제4호에 해당한다."},{"번호":4,"판정":"옳음","설명":"업무집행방법의 변경은 제1호에 해당한다."},{"번호":5,"판정":"옳음","설명":"장부가격의 변경은 제3호에 해당한다."}],"개념":[{"종류":"표","제목":"공제사업 개선명령 (법 제42조의4)","머리":["호","개선조치"],"행":[["1","업무집행방법의 변경"],["2","자산예탁기관의 변경"],["3","자산의 장부가격의 변경"],["4","불건전한 자산에 대한 적립금의 보유"],["5","가치가 없다고 인정되는 자산의 손실 처리"],["6","그 밖에 법 및 공제규정을 준수하지 아니하여 공제사업의 건전성을 해할 우려가 있는 경우의 개선명령"]]},{"종류":"표","제목":"협회 공제사업에 대한 감독 수단","머리":["수단","내용","근거"],"행":[["운영위원회","공제사업 심의, 업무집행 감독. 위원은 19명 이내","법 제42조의2"],["조사ㆍ검사","국토교통부장관 요청이 있으면 금융감독원장이 공제사업을 조사ㆍ검사","법 제42조의3"],["개선명령","국토교통부장관이 6가지 조치를 명함","법 제42조의4"],["임원 제재","공제규정 위반, 개선명령 불이행, 재무건전성 기준 위반 시 징계ㆍ해임 요구 또는 시정명령","법 제42조의5"],["재무건전성","자본ㆍ자산ㆍ유동성 기준 준수. 지급여력비율 100분의 100 이상","법 제42조의6, 영 제35조의3"]]}],"함정":"개선명령은 업무와 자산 관리에 관한 조치다. 공제사업을 넘기는 양도는 이 범위에 없다. 임원 징계ㆍ해임 요구(제42조의5)와 섞어 떠올리지 않도록 한다.","개정":"2026.2.27 개정으로 법 제41조제1항에 협회의 이름이 「한국공인중개사협회」로 정해졌다. 개선명령 목록은 그대로다."},"35회-2차-016":{"한줄":"정보를 거짓으로 공개한 경우만 업무정지 6개월이고, 나머지 네 선지는 3개월이다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"별표 4 제2호 라목","원문":"라. 법 제24조제7항을 위반하여 중개대상물에 관한 정보를 거짓으로 공개한 경우 / 법 제39조제1항제4호 / 업무정지 6개월"},{"법령":"공인중개사법 시행규칙","조문":"별표 4 제2호 나목ㆍ다목ㆍ마목ㆍ바목","원문":"나. 법 제16조를 위반하여 인장등록을 하지 않거나 등록하지 않은 인장을 사용한 경우 … 업무정지 3개월 / 마. 법 제24조제7항을 위반하여 거래정보사업자에게 공개를 의뢰한 중개대상물의 거래가 완성된 사실을 그 거래정보사업자에게 통보하지 않은 경우 … 업무정지 3개월 / 바. 법 제25조제3항을 위반하여 중개대상물 확인ㆍ설명서를 교부하지 않거나 보존하지 않은 경우 … 업무정지 3개월 / 다. 법 제23조제2항을 위반하여 별지 제15호 서식의 전속중개계약서에 따르지 않고 전속중개계약을 체결하거나 계약서를 보존하지 않은 경우 … 업무정지 3개월"}],"선지":[{"번호":1,"판정":"-","설명":"업무정지 3개월이다(별표 4 제2호 나목)."},{"번호":2,"판정":"-","설명":"업무정지 3개월이다(별표 4 제2호 마목). 같은 제24조제7항 위반이어도 통보 의무 위반은 거짓 공개보다 가볍다."},{"번호":3,"판정":"-","설명":"업무정지 6개월이다(별표 4 제2호 라목)."},{"번호":4,"판정":"-","설명":"업무정지 3개월이다(별표 4 제2호 바목)."},{"번호":5,"판정":"-","설명":"업무정지 3개월이다(별표 4 제2호 다목)."}],"개념":[{"종류":"표","제목":"개업공인중개사 업무정지 개별기준 (시행규칙 별표 4)","머리":["위반행위","근거","업무정지"],"행":[["결격사유에 해당하는 자를 소속공인중개사ㆍ중개보조원으로 둠(2개월 내 해소하지 않은 경우)","법 제39조제1항제1호","6개월"],["인장등록 위반","제2호","3개월"],["전속중개계약서 서식 위반, 계약서 미보존","제3호","3개월"],["정보를 거짓으로 공개","제4호","6개월"],["거래 완성 사실 미통보","제4호","3개월"],["확인ㆍ설명서 미교부, 미보존","제6호","3개월"],["확인ㆍ설명서 서명ㆍ날인 누락","제7호","3개월"],["거래계약서 미작성ㆍ미교부ㆍ미보존","제8호","3개월"],["거래계약서 서명ㆍ날인 누락","제9호","3개월"],["보고ㆍ조사ㆍ검사 거부 등","제10호","3개월"],["제38조제2항 각 호 위반을 최근 1년 이내 1회 한 경우","제11호","6개월"],["최근 1년 이내 업무정지 또는 과태료 처분 2회 이상 후 다시 과태료 처분 대상 행위","제12호","6개월"]]},{"종류":"표","제목":"업무정지 일반기준 (별표 4 제1호)","머리":["구분","내용"],"행":[["위반행위가 둘 이상","각 업무정지기간을 합산한 기간을 넘지 않는 범위에서 가장 무거운 처분기준의 2분의 1 범위에서 가중. 총 업무정지기간은 6개월 한도"],["줄이는 경우","사소한 부주의나 오류, 시정 노력 등이 있으면 개별기준의 2분의 1 범위에서 감경"],["늘리는 경우","피해가 크거나 늘릴 필요가 있으면 2분의 1 범위에서 가중. 법 제39조제1항에 따라 6개월 초과 불가"],["기간 계산","가중ㆍ감경 시 1개월은 30일"]]}],"함정":"같은 제24조제7항 위반이라도 거짓 공개는 6개월, 통보 누락은 3개월이다. 정보망과 관련되면 모두 무겁다고 보고 2번을 고르기 쉽다."},"35회-2차-022":{"한줄":"통지를 받은 시장ㆍ군수 또는 구청장은 지체 없이 공고 내용을 관할 등기소의 장에게 통지한다(법 제10조제4항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제10조제1항","원문":"국토교통부장관 또는 시ㆍ도지사는 … 다음 각 호의 구분에 따라 5년 이내의 기간을 정하여 제11조제1항에 따른 토지거래계약에 관한 허가구역(이하 \"허가구역\"이라 한다)으로 지정할 수 있다. … 1. 허가구역이 둘 이상의 시ㆍ도의 관할 구역에 걸쳐 있는 경우: 국토교통부장관이 지정 2. 허가구역이 동일한 시ㆍ도 안의 일부지역인 경우: 시ㆍ도지사가 지정."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제10조제4항ㆍ제5항","원문":"④ 제3항에 따라 통지를 받은 시장ㆍ군수 또는 구청장은 지체 없이 그 공고 내용을 그 허가구역을 관할하는 등기소의 장에게 통지하여야 하며, 지체 없이 그 사실을 7일 이상 공고하고, 그 공고 내용을 15일간 일반이 열람할 수 있도록 하여야 한다. ⑤ 허가구역의 지정은 제3항에 따라 허가구역의 지정을 공고한 날부터 5일 후에 그 효력이 발생한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"둘 이상의 시ㆍ도에 걸치면 국토교통부장관이 지정한다(법 제10조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"지정 기간은 5년 이내다(법 제10조제1항)."},{"번호":3,"판정":"틀림","설명":"효력 발생 시점은 지정을 공고한 날부터 5일 후다. 시장ㆍ군수ㆍ구청장이 통지를 받은 날이 기준이 아니다(법 제10조제5항)."},{"번호":4,"판정":"옳음","설명":"등기소의 장에게 지체 없이 통지한다(법 제10조제4항)."},{"번호":5,"판정":"틀림","설명":"7일 이상 공고는 맞지만 열람 기간은 15일간이다(법 제10조제4항)."}],"개념":[{"종류":"흐름","제목":"허가구역 지정 절차","단계":[{"이름":"지정","설명":"국토교통부장관 또는 시ㆍ도지사가 5년 이내 기간으로 지정. 둘 이상의 시ㆍ도에 걸치면 국토교통부장관, 동일 시ㆍ도 일부면 시ㆍ도지사"},{"이름":"심의","설명":"중앙도시계획위원회 또는 시ㆍ도도시계획위원회의 심의(법 제10조제2항)"},{"이름":"공고ㆍ통지","설명":"지체 없이 허가대상자, 용도, 지목 등을 공고하고, 국토교통부장관은 시ㆍ도지사를 거쳐 시장ㆍ군수ㆍ구청장에게 통지. 시ㆍ도지사는 국토교통부장관과 시장ㆍ군수ㆍ구청장에게 통지"},{"이름":"후속 조치","설명":"시장ㆍ군수ㆍ구청장이 등기소의 장에게 지체 없이 통지, 7일 이상 공고, 15일간 열람"},{"이름":"효력 발생","설명":"지정을 공고한 날부터 5일 후"}]},{"종류":"표","제목":"허가구역 지정ㆍ해제 요점","머리":["항목","내용","근거"],"행":[["지정권자","둘 이상의 시ㆍ도에 걸치면 국토교통부장관, 동일 시ㆍ도 안이면 시ㆍ도지사(국가 시행 개발사업 등은 국토교통부장관도 가능)","법 제10조제1항"],["지정 기간","5년 이내","법 제10조제1항"],["공고 후 효력","공고한 날부터 5일 후","법 제10조제5항"],["등기소 통지","시장ㆍ군수ㆍ구청장이 지체 없이","법 제10조제4항"],["공고ㆍ열람","7일 이상 공고, 15일간 열람","법 제10조제4항"],["해제","지정 사유가 없어졌다고 인정되면 지체 없이 해제 또는 축소","법 제10조제6항"]]}],"함정":"기간 숫자가 여럿 나오는 문항이다. 지정 기간 5년, 효력 공고일부터 5일 후, 공고 7일 이상, 열람 15일을 구분해 둔다. 2번(7년), 5번(30일)은 숫자를 바꾼 선지다."},"35회-2차-029":{"한줄":"甲의 저당권이 먼저 설정되어 있으므로 丙의 임차권은 저당권에 대항하지 못하고, 소액임차인이어도 저당권 실행 시 임차권이 소멸한다.","근거":[{"법령":"민사집행법","조문":"제91조제2항","원문":"②매각부동산 위의 모든 저당권은 매각으로 소멸된다."},{"법령":"주택임대차보호법","조문":"제3조의5","원문":"임차권은 임차주택에 대하여 「민사집행법」에 따른 경매가 행하여진 경우에는 그 임차주택의 경락(競落)에 따라 소멸한다. 다만, 보증금이 모두 변제되지 아니한, 대항력이 있는 임차권은 그러하지 아니하다."},{"법령":"민법","조문":"제621조제2항","원문":"②부동산임대차를 등기한 때에는 그때부터 제삼자에 대하여 효력이 생긴다."},{"법령":"주택임대차보호법","조문":"제3조제1항","원문":"① 임대차는 그 등기(登記)가 없는 경우에도 임차인(賃借人)이 주택의 인도(引渡)와 주민등록을 마친 때에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다. 이 경우 전입신고를 한 때에 주민등록이 된 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"판례는 임차인 본인뿐 아니라 동거하는 가족의 주민등록 이전도 대항요건인 주민등록으로 본다. 자녀의 전입으로 대항력이 인정된다."},{"번호":2,"판정":"틀림","설명":"임대차를 등기하면 그때부터 제삼자에 대해 효력이 생긴다. 주민등록이 없어도 대항력이 있다(민법 제621조제2항)."},{"번호":3,"판정":"틀림","설명":"판례는 보증금반환채권 담보 목적의 전세권을 양수한 선의의 제3자에게 전세권설정자가 연체차임 공제를 주장할 수 없다고 본다."},{"번호":4,"판정":"옳음","설명":"甲의 저당권은 丙보다 앞서므로 저당권 실행 시 매각으로 저당권이 소멸하고 丙의 임차권도 함께 소멸한다. 소액임차인은 최우선변제로 보증금 일부를 배당받을 수 있을 뿐이다(주택임대차보호법 제3조의5, 민사집행법 제91조제2항)."},{"번호":5,"판정":"틀림","설명":"후순위 저당권자 丁의 경매에서도 선순위 저당권인 甲의 저당권은 소멸한다(민사집행법 제91조제2항). 甲의 저당권보다 늦은 丙의 임차권도 소멸한다."}],"개념":[{"종류":"표","제목":"경매와 임차권의 관계","머리":["상황","결과","근거"],"행":[["말소기준이 되는 저당권보다 먼저 대항요건을 갖춘 임차인","대항력 있음. 보증금이 모두 변제되지 않으면 매수인이 임차권을 인수","주택임대차보호법 제3조의5 단서"],["저당권 설정 후에 대항요건을 갖춘 임차인","저당권 실행 시 임차권도 소멸","민사집행법 제91조제2항, 주택임대차보호법 제3조의5"],["대항력 없는 임차권","경락으로 소멸","주택임대차보호법 제3조의5 본문"],["후순위 저당권자의 경매","선순위 저당권도 소멸","민사집행법 제91조제2항"],["등기된 임차권","저당권ㆍ압류ㆍ가압류에 대항할 수 없으면 소멸, 대항할 수 있으면 매수인이 인수","민사집행법 제91조제3항ㆍ제4항"]]},{"종류":"비교","제목":"대항력 취득 방법","왼쪽":{"이름":"주택임대차보호법 (제3조제1항)","항목":["주택의 인도 + 주민등록(전입신고)","다음 날부터 제삼자에 대하여 효력","가족의 주민등록도 인정되는 것이 판례"]},"오른쪽":{"이름":"민법 (제621조)","항목":["임대차등기","임차인은 당사자 간 반대약정이 없으면 임대인에게 등기절차 협력을 청구 가능","등기한 때부터 제삼자에 대하여 효력"]}}],"함정":"「최우선변제권이 있는 소액임차인」이라는 말에 임차권 자체가 보호된다고 읽기 쉽다. 최우선변제는 배당에서 보증금 일부를 먼저 받는 권리이고, 선순위 저당권 앞에서 임차권의 대항력을 만들지 않는다."},"35회-2차-043":{"한줄":"공공청사는 기반시설이어서, 주민이 도시ㆍ군관리계획의 입안을 제안할 수 있는 ‘기반시설의 설치ㆍ정비 또는 개량’에 들어간다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제26조제1항제1호","원문":"주민(이해관계자를 포함한다. 이하 같다)은 다음 각 호의 사항에 대하여 제24조에 따라 도시ㆍ군관리계획을 입안할 수 있는 자에게 도시ㆍ군관리계획의 입안을 제안할 수 있다. 이 경우 제안서에는 도시ㆍ군관리계획도서와 계획설명서를 첨부하여야 한다. 1. 기반시설의 설치ㆍ정비 또는 개량에 관한 사항"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제6호라목","원문":"학교ㆍ공공청사ㆍ문화시설 및 공공필요성이 인정되는 체육시설 등 공공ㆍ문화체육시설"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제4조제3항","원문":"광역도시계획이 수립되어 있는 지역에 대하여 수립하는 도시ㆍ군기본계획은 그 광역도시계획에 부합되어야 하며, 도시ㆍ군기본계획의 내용이 광역도시계획의 내용과 다를 때에는 광역도시계획의 내용이 우선한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제19조의2제3항","원문":"제1항에 따른 생활권계획이 수립 또는 승인된 때에는 해당 계획이 수립된 생활권에 대해서는 도시ㆍ군기본계획이 수립 또는 변경된 것으로 본다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제22조의2제2항","원문":"도지사는 제1항에 따라 도시ㆍ군기본계획을 승인하려면 관계 행정기관의 장과 협의한 후 지방도시계획위원회의 심의를 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제35조제1항","원문":"국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 도시ㆍ군관리계획을 조속히 입안하여야 할 필요가 있다고 인정되면 광역도시계획이나 도시ㆍ군기본계획을 수립할 때에 도시ㆍ군관리계획을 함께 입안할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"광역도시계획과 내용이 다르면 광역도시계획이 우선한다. 기본계획은 광역도시계획에 부합해야 한다(법 제4조제3항)."},{"번호":2,"판정":"틀림","설명":"생활권계획이 수립 또는 승인되면 그 생활권은 도시ㆍ군기본계획이 수립 또는 변경된 것으로 본다. 도시ㆍ군관리계획이 수립된 것으로 보는 규정은 없다(법 제19조의2제3항)."},{"번호":3,"판정":"틀림","설명":"시ㆍ군 기본계획은 도지사가 승인하며, 승인할 때 관계 행정기관 협의 후 지방도시계획위원회 심의를 반드시 거친다(법 제22조의2제2항). 지방의회 의견 청취(법 제21조제1항)는 별개의 절차라 심의를 대신하지 못한다."},{"번호":4,"판정":"옳음","설명":"공공청사는 기반시설(법 제2조제6호라목)이므로 입안 제안 대상이다(법 제26조제1항제1호)."},{"번호":5,"판정":"틀림","설명":"조속히 입안할 필요가 있으면 광역도시계획이나 도시ㆍ군기본계획을 수립할 때 도시ㆍ군관리계획을 함께 입안할 수 있다(법 제35조제1항)."}],"개념":[{"종류":"표","제목":"도시ㆍ군기본계획의 수립ㆍ확정","머리":["구분","특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도","시ㆍ군"],"행":[["수립권자","특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사","시장 또는 군수"],["지방의회 의견","미리 의회 의견 청취, 의회는 30일 이내 제시(법 제21조)","같음"],["확정","관계 행정기관 협의 후 지방도시계획위원회 심의(법 제22조)","도지사 승인: 관계 행정기관 협의 후 지방도시계획위원회 심의(법 제22조의2)"],["공고ㆍ열람","관계 행정기관에 서류 송부, 공고 후 일반 열람","도지사가 서류 송부, 시장ㆍ군수가 공고 후 일반 열람"],["정비","5년마다 타당성 전반 재검토(법 제23조제1항)","같음"],["상위계획과의 관계","국가계획 > 광역도시계획 > 도시ㆍ군기본계획(법 제4조제2항ㆍ제3항)","같음"]]},{"종류":"표","제목":"도시ㆍ군관리계획 입안 제안 대상(법 제26조제1항)","머리":["호","제안 가능 사항","비고"],"행":[["1호","기반시설의 설치ㆍ정비 또는 개량","공공청사 포함"],["2호","지구단위계획구역의 지정ㆍ변경, 지구단위계획의 수립ㆍ변경",""],["3호 가목","개발진흥지구 중 공업기능 또는 유통물류기능 등을 집중 개발ㆍ정비하는 지구(대통령령 지정)","산업ㆍ유통개발진흥지구 등"],["3호 나목","지구단위계획으로 대체하기 위한 용도지구의 지정ㆍ변경","용도지구 제한을 지구단위계획으로 대체"],["5호","도시ㆍ군계획시설입체복합구역의 지정ㆍ변경과 건축제한ㆍ건폐율ㆍ용적률ㆍ높이","4호는 삭제"],["처리","제안일부터 45일 이내 반영 여부 통보, 부득이하면 1회 30일 연장","영 제20조제1항"]]}],"함정":"선지 3은 지방의회 의견 청취를 마쳤다는 점을 내세워 지방도시계획위원회 심의 생략을 끌어낸 것이다. 두 절차는 따로 있다. 선지 2는 ‘생활권계획 → 도시ㆍ군기본계획이 수립된 것으로 본다’를 ‘도시ㆍ군관리계획’으로 바꿔 놓았다."},"35회-2차-046":{"한줄":"택지개발지구가 200만제곱미터를 초과하면 사업시행자는 공동구를 설치해야 한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제44조제1항","원문":"다음 각 호에 해당하는 지역ㆍ지구ㆍ구역 등(이하 이 항에서 \"지역등\"이라 한다)이 대통령령으로 정하는 규모를 초과하는 경우에는 해당 지역등에서 개발사업을 시행하는 자(이하 이 조에서 \"사업시행자\"라 한다)는 공동구를 설치하여야 한다. 2. 「택지개발촉진법」 제2조제3호에 따른 택지개발지구"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제35조의2제1항","원문":"법 제44조제1항 각 호 외의 부분에서 \"대통령령으로 정하는 규모\"란 200만제곱미터를 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제35조의3","원문":"공동구가 설치된 경우에는 법 제44조제3항에 따라 제1호부터 제6호까지의 시설을 공동구에 수용하여야 하며, 제7호 및 제8호의 시설은 법 제44조의2제4항에 따른 공동구협의회(이하 \"공동구협의회\"라 한다)의 심의를 거쳐 수용할 수 있다. 1. 전선로 2. 통신선로 3. 수도관 4. 열수송관 5. 중수도관 6. 쓰레기수송관 7. 가스관 8. 하수도관, 그 밖의 시설"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제47조제1항","원문":"도시ㆍ군계획시설결정의 고시일부터 10년 이내에 그 도시ㆍ군계획시설의 설치에 관한 도시ㆍ군계획시설사업이 시행되지 아니하는 경우(제88조에 따른 실시계획의 인가나 그에 상당하는 절차가 진행된 경우는 제외한다. 이하 같다) 그 도시ㆍ군계획시설의 부지로 되어 있는 토지 중 지목(地目)이 대(垈)인 토지(그 토지에 있는 건축물 및 정착물을 포함한다. 이하 이 조에서 같다)의 소유자는 대통령령으로 정하는 바에 따라 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수에게 그 토지의 매수를 청구할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제48조제1항","원문":"도시ㆍ군계획시설결정이 고시된 도시ㆍ군계획시설에 대하여 그 고시일부터 20년이 지날 때까지 그 시설의 설치에 관한 도시ㆍ군계획시설사업이 시행되지 아니하는 경우 그 도시ㆍ군계획시설결정은 그 고시일부터 20년이 되는 날의 다음날에 그 효력을 잃는다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제48조의2제1항","원문":"도시ㆍ군계획시설결정의 고시일부터 10년 이내에 그 도시ㆍ군계획시설의 설치에 관한 도시ㆍ군계획시설사업이 시행되지 아니한 경우로서 제85조제1항에 따른 단계별 집행계획상 해당 도시ㆍ군계획시설의 실효 시까지 집행계획이 없는 경우에는 그 도시ㆍ군계획시설 부지로 되어 있는 토지의 소유자는 대통령령으로 정하는 바에 따라 해당 도시ㆍ군계획시설에 대한 도시ㆍ군관리계획 입안권자에게 그 토지의 도시ㆍ군계획시설결정 해제를 위한 도시ㆍ군관리계획 입안을 신청할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"실시계획의 인가나 그에 상당하는 절차가 진행된 경우는 매수청구 대상에서 제외된다(법 제47조제1항 괄호). 청구할 수 있는 토지도 지목이 대(垈)인 토지에 한한다."},{"번호":2,"판정":"틀림","설명":"쓰레기수송관은 전선로ㆍ통신선로ㆍ수도관ㆍ열수송관ㆍ중수도관과 함께 반드시 공동구에 수용해야 하는 시설이다. 협의회 심의 대상은 가스관, 하수도관, 그 밖의 시설이다(영 제35조의3)."},{"번호":3,"판정":"옳음","설명":"택지개발지구가 대통령령으로 정하는 규모(200만제곱미터)를 초과하면 사업시행자가 공동구를 설치한다(법 제44조제1항제2호, 영 제35조의2제1항)."},{"번호":4,"판정":"틀림","설명":"고시일부터 20년이 지날 때까지 사업이 시행되지 않으면 ‘20년이 되는 날의 다음날’에 효력을 잃는다(법 제48조제1항)."},{"번호":5,"판정":"틀림","설명":"해제 입안 신청은 부지의 ‘토지 소유자’가 한다. 건물만 소유한 자는 신청권자가 아니다(법 제48조의2제1항)."}],"개념":[{"종류":"표","제목":"시설결정 고시 후 경과 기간별 제도","머리":["시점","제도","핵심 내용"],"행":[["10년 이내 미시행","매수청구(법 제47조)","지목이 대(垈)인 토지 소유자가 청구. 실시계획 인가 등이 진행된 경우 제외. 6개월 내 매수 여부 결정, 알린 날부터 2년 내 매수"],["10년 경과","지방의회 보고(법 제48조제3항)","시장ㆍ군수 등이 현황과 단계별 집행계획을 지방의회에 보고, 의회는 해제 권고 가능"],["10년 경과 + 집행계획 없음","해제 입안 신청(법 제48조의2)","토지 소유자가 입안권자에게 신청, 3개월 내 입안 여부 통지. 미입안 시 결정권자에게 해제 신청(2개월 내 결정), 국토교통부장관에게 심사 신청 가능"],["20년 경과","실효(법 제48조제1항)","고시일부터 20년이 되는 날의 다음날 효력 상실"]]},{"종류":"표","제목":"공동구(법 제44조, 영 제35조의2ㆍ제35조의3)","머리":["항목","내용"],"행":[["설치 의무","도시개발구역, 택지개발지구, 경제자유구역, 정비구역, 공공주택지구, 도청이전신도시가 200만제곱미터 초과 시 사업시행자가 설치"],["반드시 수용","전선로, 통신선로, 수도관, 열수송관, 중수도관, 쓰레기수송관"],["협의회 심의 후 수용","가스관, 하수도관, 그 밖의 시설"],["비용 부담","공동구 점용예정자와 사업시행자가 부담(법 제44조제5항)"]]}],"함정":"선지 1은 ‘실시계획 인가가 있으면’ 매수청구 대상이 아닌데 반대로 적었다. 선지 4는 ‘20년이 되는 날’과 ‘다음날’ 차이, 선지 5는 신청권자(토지 소유자)를 노린다. 쓰레기수송관은 필수 수용 시설이다."},"35회-2차-076":{"한줄":"건축허가나 착공의 제한기간은 2년 이내이며, 1회에 한하여 1년 이내의 범위에서 연장할 수 있다.","근거":[{"법령":"건축법","조문":"제18조제4항","원문":"④ 제1항이나 제2항에 따라 건축허가나 건축물의 착공을 제한하는 경우 제한기간은 2년 이내로 한다. 다만, 1회에 한하여 1년 이내의 범위에서 제한기간을 연장할 수 있다."},{"법령":"건축법","조문":"제18조제2항","원문":"② 특별시장ㆍ광역시장ㆍ도지사는 지역계획이나 도시ㆍ군계획에 특히 필요하다고 인정하면 시장ㆍ군수ㆍ구청장의 건축허가나 허가를 받은 건축물의 착공을 제한할 수 있다."},{"법령":"건축법","조문":"제18조제3항","원문":"③ 국토교통부장관이나 시ㆍ도지사는 제1항이나 제2항에 따라 건축허가나 건축허가를 받은 건축물의 착공을 제한하려는 경우에는 「토지이용규제 기본법」 제8조에 따라 주민의견을 청취한 후 건축위원회의 심의를 거쳐야 한다."},{"법령":"건축법","조문":"제18조제5항","원문":"⑤ 국토교통부장관이나 특별시장ㆍ광역시장ㆍ도지사는 제1항이나 제2항에 따라 건축허가나 건축물의 착공을 제한하는 경우 제한 목적ㆍ기간, 대상 건축물의 용도와 대상 구역의 위치ㆍ면적ㆍ경계 등을 상세하게 정하여 허가권자에게 통보하여야 하며, 통보를 받은 허가권자는 지체 없이 이를 공고하여야 한다."},{"법령":"건축법","조문":"제18조제6항","원문":"⑥ 특별시장ㆍ광역시장ㆍ도지사는 제2항에 따라 시장ㆍ군수ㆍ구청장의 건축허가나 건축물의 착공을 제한한 경우 즉시 국토교통부장관에게 보고하여야 하며, 보고를 받은 국토교통부장관은 제한 내용이 지나치다고 인정하면 해제를 명할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"특별시장ㆍ광역시장ㆍ도지사는 지역계획이나 도시ㆍ군계획에 특히 필요하면 시장ㆍ군수ㆍ구청장의 건축허가나 허가받은 건축물의 착공을 제한할 수 있다(법 제18조제2항)."},{"번호":2,"판정":"틀림","설명":"허가 제한은 국토교통부장관이나 시ㆍ도지사가 한다. 시장ㆍ군수ㆍ구청장은 제한 주체가 아니다. 주민의견 청취 후 거치는 심의도 건축위원회 심의다(법 제18조제1항~제3항)."},{"번호":3,"판정":"옳음","설명":"제한기간은 2년 이내이고 1회에 한하여 1년 이내 연장할 수 있다(법 제18조제4항)."},{"번호":4,"판정":"틀림","설명":"국토교통부장관이나 시ㆍ도지사가 제한 목적ㆍ기간 등을 정해 허가권자에게 통보하고, 통보를 받은 허가권자가 지체 없이 공고한다(법 제18조제5항)."},{"번호":5,"판정":"틀림","설명":"보고는 시장ㆍ군수ㆍ구청장의 허가를 제한한 특별시장ㆍ광역시장ㆍ도지사가 한다. 보고받은 국토교통부장관은 제한 내용이 지나치다고 인정하면 해제를 명할 수 있다(법 제18조제6항)."}],"개념":[{"종류":"비교","제목":"건축허가ㆍ착공 제한 주체별 비교","왼쪽":{"이름":"국토교통부장관(제1항)","항목":["요건: 국토관리를 위해 특히 필요하다고 인정하거나, 주무부장관이 국방, 국가유산 보존, 환경보전 또는 국민경제를 위해 특히 필요하다고 인정해 요청","대상: 허가권자의 건축허가, 허가받은 건축물의 착공","절차: 주민의견 청취 후 건축위원회 심의","기간: 2년 이내, 1회 1년 이내 연장","허가권자에게 제한 목적ㆍ기간, 대상 건축물의 용도와 구역의 위치ㆍ면적ㆍ경계를 정해 통보"]},"오른쪽":{"이름":"특별시장ㆍ광역시장ㆍ도지사(제2항)","항목":["요건: 지역계획이나 도시ㆍ군계획에 특히 필요하다고 인정","대상: 시장ㆍ군수ㆍ구청장의 건축허가, 허가받은 건축물의 착공","절차: 주민의견 청취 후 건축위원회 심의","기간: 2년 이내, 1회 1년 이내 연장","통보 후 즉시 국토교통부장관에게 보고, 국토교통부장관은 지나치면 해제 명령"]}},{"종류":"흐름","제목":"허가 제한의 절차","단계":[{"이름":"제한 필요 인정","설명":"국토교통부장관 또는 특별시장ㆍ광역시장ㆍ도지사가 요건에 해당한다고 판단한다(법 제18조제1항ㆍ제2항)."},{"이름":"주민의견 청취","설명":"「토지이용규제 기본법」 제8조에 따라 청취한다(법 제18조제3항)."},{"이름":"건축위원회 심의","설명":"주민의견 청취 후 건축위원회의 심의를 거친다(법 제18조제3항)."},{"이름":"제한 결정","설명":"제한기간 2년 이내, 1회에 한하여 1년 이내 연장(법 제18조제4항)."},{"이름":"통보ㆍ공고","설명":"제한 내용을 허가권자에게 통보하고, 허가권자가 지체 없이 공고한다(법 제18조제5항)."},{"이름":"보고ㆍ해제","설명":"시ㆍ도지사의 제한은 즉시 국토교통부장관에게 보고하며, 국토교통부장관은 지나치다고 인정하면 해제를 명할 수 있다(법 제18조제6항)."}]}],"함정":"선지 4는 공고 주체가 틀렸다. 제한하는 쪽은 통보까지만 하고 공고는 통보받은 허가권자가 한다. 선지 5는 보고 주체와 해제 방식(해제를 명할 수 있다)을 바꿨다. 선지 1ㆍ2는 도지사의 착공 제한권과 심의기관(건축위원회)을 흐려 놓았다."},"35회-2차-065":{"한줄":"어린이놀이터는 복리시설이고, 기간시설은 도로ㆍ상하수도ㆍ전기시설ㆍ가스시설ㆍ통신시설ㆍ지역난방시설 등이다.","근거":[{"법령":"주택법","조문":"제2조제16호","원문":"이 법에서 사용하는 용어의 뜻은 다음과 같다. 16. \"기간시설\"(基幹施設)이란 도로ㆍ상하수도ㆍ전기시설ㆍ가스시설ㆍ통신시설ㆍ지역난방시설 등을 말한다."},{"법령":"주택법","조문":"제2조제14호","원문":"이 법에서 사용하는 용어의 뜻은 다음과 같다. 14. \"복리시설\"이란 주택단지의 입주자 등의 생활복리를 위한 다음 각 목의 공동시설을 말한다. 가. 어린이놀이터, 근린생활시설, 유치원, 주민운동시설 및 경로당 나. 그 밖에 입주자 등의 생활복리를 위하여 대통령령으로 정하는 공동시설"},{"법령":"주택법","조문":"제2조제17호","원문":"이 법에서 사용하는 용어의 뜻은 다음과 같다. 17. \"간선시설\"(幹線施設)이란 도로ㆍ상하수도ㆍ전기시설ㆍ가스시설ㆍ통신시설 및 지역난방시설 등 주택단지(둘 이상의 주택단지를 동시에 개발하는 경우에는 각각의 주택단지를 말한다) 안의 기간시설을 그 주택단지 밖에 있는 같은 종류의 기간시설에 연결시키는 시설을 말한다. 다만, 가스시설ㆍ통신시설 및 지역난방시설의 경우에는 주택단지 안의 기간시설을 포함한다."}],"선지":[{"번호":1,"판정":"-","설명":"전기시설은 기간시설이다(법 제2조제16호)."},{"번호":2,"판정":"-","설명":"통신시설은 기간시설이다(법 제2조제16호)."},{"번호":3,"판정":"-","설명":"상하수도는 기간시설이다(법 제2조제16호)."},{"번호":4,"판정":"-","설명":"어린이놀이터는 주택단지 입주자 등의 생활복리를 위한 공동시설인 복리시설이다(법 제2조제14호가목)."},{"번호":5,"판정":"-","설명":"지역난방시설은 기간시설이다(법 제2조제16호)."}],"개념":[{"종류":"표","제목":"주택법상 시설 용어 구분","머리":["용어","범위","근거"],"행":[["부대시설","주차장, 관리사무소, 담장 및 주택단지 안의 도로, 건축설비. 영: 보안등ㆍ대문ㆍ경비실ㆍ자전거보관소, 조경시설ㆍ옹벽ㆍ축대, 안내표지판ㆍ공중화장실, 저수시설ㆍ지하양수시설ㆍ대피시설, 쓰레기 처리시설ㆍ정화조, 소방시설 등","법 제2조제13호, 영 제6조"],["복리시설","어린이놀이터, 근린생활시설, 유치원, 주민운동시설, 경로당. 영: 종교시설, 소매시장ㆍ상점, 교육연구시설, 노유자시설, 금융업소, 지식산업센터, 사회복지관, 공동작업장, 주민공동시설 등","법 제2조제14호, 영 제7조"],["기반시설","국토의 계획 및 이용에 관한 법률 제2조제6호의 기반시설","법 제2조제15호"],["기간시설","도로, 상하수도, 전기시설, 가스시설, 통신시설, 지역난방시설 등","법 제2조제16호"],["간선시설","주택단지 안의 기간시설을 주택단지 밖의 같은 종류의 기간시설에 연결시키는 시설. 가스ㆍ통신ㆍ지역난방시설은 주택단지 안의 기간시설을 포함","법 제2조제17호"]]}],"함정":"어린이놀이터는 주택단지 안에서 흔히 보는 시설이라 ‘기반 시설’ 느낌으로 읽기 쉽다. 주택법은 어린이놀이터를 복리시설(가목)로 둔다. 지역난방시설은 기간시설이고, 부대시설 중 냉난방공급시설에서는 지역난방공급시설이 제외된다(영 제6조제6호)."},"35회-2차-066":{"한줄":"공공시설 설치계획의 변경이 필요한 경우는 경미한 변경에서 빠지므로 사업계획승인권자의 변경승인을 받아야 한다.","근거":[{"법령":"주택법","조문":"제15조제4항","원문":"④ 제1항 또는 제3항에 따라 승인받은 사업계획을 변경하려면 사업계획승인권자로부터 변경승인을 받아야 한다. 다만, 국토교통부령으로 정하는 경미한 사항을 변경하는 경우에는 그러하지 아니하다."},{"법령":"주택법 시행규칙","조문":"제13조제5항제6호","원문":"⑤ 법 제15조제4항 단서에서 \"국토교통부령으로 정하는 경미한 사항을 변경하는 경우\"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. 다만, 제1호ㆍ제3호 및 제7호는 사업주체가 국가, 지방자치단체, 한국토지주택공사 또는 지방공사인 경우로 한정한다. 6. 사업계획승인의 조건으로 부과된 사항을 이행함에 따라 발생되는 변경. 다만, 공공시설 설치계획의 변경이 필요한 경우는 제외한다."},{"법령":"주택법","조문":"제15조제5항","원문":"⑤ 제1항 또는 제3항의 사업계획은 쾌적하고 문화적인 주거생활을 하는 데에 적합하도록 수립되어야 하며, 그 사업계획에는 부대시설 및 복리시설의 설치에 관한 계획 등이 포함되어야 한다."},{"법령":"주택법 시행령","조문":"제28조제1항","원문":"① 법 제15조제3항 각 호 외의 부분 전단에서 \"대통령령으로 정하는 호수 이상의 주택단지\"란 전체 세대수가 600세대 이상인 주택단지를 말한다."},{"법령":"주택법","조문":"제21조제1항제3호","원문":"① 제15조제1항 또는 제3항에 따라 주택건설사업계획의 승인을 받으려는 자는 해당 주택건설대지의 소유권을 확보하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다. 3. 국가ㆍ지방자치단체ㆍ한국토지주택공사 또는 지방공사가 주택건설사업을 하는 경우"},{"법령":"주택법 시행규칙","조문":"제13조제4항","원문":"④ 사업주체는 입주자 모집공고를 한 후 제2항에 따른 사업계획변경승인을 받은 경우에는 14일 이내에 문서로 입주예정자에게 그 내용을 통보하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"사업계획승인 조건 이행에 따른 변경은 경미한 변경이지만 공공시설 설치계획의 변경이 필요한 경우는 제외된다. 그래서 변경승인이 필요하다(법 제15조제4항, 규칙 제13조제5항제6호 단서)."},{"번호":2,"판정":"옳음","설명":"주택건설사업계획에는 부대시설 및 복리시설의 설치에 관한 계획 등이 포함되어야 한다(법 제15조제5항)."},{"번호":3,"판정":"옳음","설명":"전체 세대수 600세대 이상인 주택단지는 공구별로 분할해 건설ㆍ공급할 수 있다(법 제15조제3항, 영 제28조제1항)."},{"번호":4,"판정":"옳음","설명":"국가ㆍ지방자치단체ㆍ한국토지주택공사ㆍ지방공사가 주택건설사업을 하는 경우에는 대지 소유권 확보 요건이 적용되지 않는다(법 제21조제1항제3호)."},{"번호":5,"판정":"옳음","설명":"입주자 모집공고 후 사업계획변경승인을 받으면 14일 이내에 문서로 입주예정자에게 통보한다(규칙 제13조제4항)."}],"개념":[{"종류":"표","제목":"사업계획승인 대상ㆍ승인권자(법 제15조, 영 제27조)","머리":["구분","내용"],"행":[["주택건설 규모(단독주택)","30호 이상(공공사업으로 조성된 용지를 일단의 토지로 공급받아 건설하는 단독주택, 한옥은 50호)"],["주택건설 규모(공동주택)","30세대 이상(리모델링은 증가 세대수 기준). 단지형 연립ㆍ다세대 등 일부는 50세대"],["대지조성사업","1만 제곱미터 이상"],["승인권자","대지면적 10만 제곱미터 이상: 시ㆍ도지사 또는 인구 50만 이상 대도시 시장. 10만 제곱미터 미만: 특별시장ㆍ통합특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수"],["국토교통부장관 승인","국가 및 한국토지주택공사가 시행하는 경우 등"],["공구별 분할","전체 세대수 600세대 이상(영 제28조제1항). 공구 간 6미터 이상 너비로 경계 설정, 공구별 300세대 이상(영 제8조)"]]},{"종류":"표","제목":"경미한 사항의 변경(규칙 제13조제5항, 변경승인 불필요)","머리":["호","내용","비고"],"행":[["1호","총사업비 20퍼센트 범위의 사업비 증감","국가ㆍ지방자치단체ㆍ한국토지주택공사ㆍ지방공사 한정"],["2호","건축물이 아닌 부대시설ㆍ복리시설 설치기준 이상으로의 변경(위치변경 없음)",""],["3호","대지면적 20퍼센트 범위의 면적 증감(지구경계 변경ㆍ수용 필요 시 제외)","국가ㆍ지방자치단체ㆍ한국토지주택공사ㆍ지방공사 한정"],["4호","세대수ㆍ세대당 공급면적 변경 없는 내부구조 위치ㆍ면적 변경(승인 면적의 10퍼센트 범위)",""],["5호","내장ㆍ외장 재료의 변경(품질이 같거나 그 이상)",""],["6호","사업계획승인 조건 이행에 따른 변경","공공시설 설치계획 변경이 필요하면 제외"],["7호","건축물 설계ㆍ용도별 위치를 바꾸지 않는 배치조정, 단지 내 도로 선형변경","국가ㆍ지방자치단체ㆍ한국토지주택공사ㆍ지방공사 한정"],["8호","건축법 시행령 제12조제3항 각 호의 사항 변경",""]]}],"함정":"선지 1은 ‘조건 이행에 따른 변경은 경미하다’까지만 읽으면 맞게 보인다. 단서의 공공시설 설치계획 변경 예외가 정답 포인트다. 선지 3의 600세대와 선지 5의 14일은 사실 그대로 옳다. 선지 4의 소유권 확보 예외(법 제21조제1항제3호)는 국가ㆍ지방자치단체ㆍ한국토지주택공사ㆍ지방공사만 쓸 수 있다."},"35회-2차-103":{"한줄":"관공서는 체납처분 압류등기를 촉탁할 때 상속인을 갈음해 상속으로 인한 권리이전등기를 함께 촉탁할 수 있다.","근거":[{"법령":"부동산등기법","조문":"제96조","원문":"관공서가 체납처분(滯納處分)으로 인한 압류등기(押留登記)를 촉탁하는 경우에는 등기명의인 또는 상속인, 그 밖의 포괄승계인을 갈음하여 부동산의 표시, 등기명의인의 표시의 변경, 경정 또는 상속, 그 밖의 포괄승계로 인한 권리이전(權利移轉)의 등기를 함께 촉탁할 수 있다."},{"법령":"부동산등기규칙","조문":"제52조제8호","원문":"8. 관공서 또는 법원의 촉탁으로 실행되어야 할 등기를 신청한 경우"},{"법령":"부동산등기법","조문":"제85조제1항","원문":"① 법원은 다음 각 호의 어느 하나에 해당하는 재판을 한 경우 지체 없이 신탁원부 기록의 변경등기를 등기소에 촉탁하여야 한다.\n  1. 수탁자 해임의 재판"},{"법령":"부동산등기규칙","조문":"제155조제1항","원문":"① 관공서가 촉탁정보 및 첨부정보를 적은 서면을 제출하는 방법으로 등기촉탁을 하는 경우에는 우편으로 그 촉탁서를 제출할 수 있다."},{"법령":"부동산등기법","조문":"제22조제2항","원문":"② 촉탁에 따른 등기절차는 법률에 다른 규정이 없는 경우에는 신청에 따른 등기에 관한 규정을 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"체납처분 압류등기를 촉탁하는 관공서는 상속인을 갈음하여 상속으로 인한 권리이전등기를 함께 촉탁할 수 있다(법 제96조)."},{"번호":2,"판정":"옳음","설명":"관공서 또는 법원의 촉탁으로 해야 할 등기를 당사자가 신청하면 사건이 등기할 것이 아닌 경우에 해당해 각하한다(법 제29조제2호, 규칙 제52조제8호)."},{"번호":3,"판정":"옳음","설명":"수탁자 해임의 재판을 한 법원은 지체 없이 신탁원부 변경등기를 촉탁한다(법 제85조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"서면으로 촉탁하는 관공서는 촉탁서를 우편으로 제출할 수 있다(규칙 제155조제1항)."},{"번호":5,"판정":"옳음","설명":"촉탁등기의 절차는 별도 규정이 없으면 신청에 따른 등기 규정을 준용한다(법 제22조제2항)."}],"개념":[{"종류":"표","제목":"관공서·법원 촉탁등기 모음","머리":["촉탁 사유","촉탁하는 자","내용","근거"],"행":[["수탁자 해임·신탁관리인 선임 해임·신탁 변경 재판","법원","신탁원부 기록의 변경등기, 지체 없이","법 제85조제1항"],["수탁자를 직권으로 해임한 경우 등","법무부장관","신탁원부 기록의 변경등기, 지체 없이","법 제85조제2항"],["체납처분 압류등기","관공서","상속인·포괄승계인을 갈음한 표시변경·경정·상속등기를 함께 촉탁 가능","법 제96조"],["공매처분","관공서(등기권리자 청구 시)","권리이전등기, 소멸 권리 말소, 압류·공매공고등기 말소","법 제97조"],["국가·지방자치단체가 등기권리자","국가·지방자치단체","등기의무자의 승낙을 받아 지체 없이 촉탁","법 제98조제1항"],["국가·지방자치단체가 등기의무자","국가·지방자치단체","등기권리자의 청구에 따라 지체 없이 촉탁","법 제98조제2항"]]},{"종류":"비교","제목":"국가·지방자치단체의 촉탁 방향","왼쪽":{"이름":"권리자인 경우","항목":["등기의무자의 승낙을 받아 촉탁","촉탁은 지체 없이","근거: 법 제98조제1항"]},"오른쪽":{"이름":"의무자인 경우","항목":["등기권리자의 청구에 따라 촉탁","촉탁은 지체 없이","근거: 법 제98조제2항"]}}],"함정":"체납처분 압류등기는 상속등기가 안 되어 있는 부동산에도 필요하므로 법이 대위 촉탁을 허용한다. 선지 1은 이 허용 범위를 부정해 틀리다. 선지 2는 촉탁 대상 등기를 당사자가 신청한 경우로 수리될 것 같지만 각하 사유다."},"35회-2차-099":{"한줄":"환매권은 매도인이 매매계약과 동시에 보류하는 권리이므로 매도인이 아닌 제3자를 환매권리자로 하는 환매등기는 할 수 없다.","근거":[{"법령":"민법","조문":"제590조제1항","원문":"①매도인이 매매계약과 동시에 환매할 권리를 보류한 때에는 그 영수한 대금 및 매수인이 부담한 매매비용을 반환하고 그 목적물을 환매할 수 있다."},{"법령":"민법","조문":"제592조","원문":"매매의 목적물이 부동산인 경우에 매매등기와 동시에 환매권의 보류를 등기한 때에는 제삼자에 대하여 그 효력이 있다."},{"법령":"부동산등기법","조문":"제53조","원문":"등기관이 환매특약의 등기를 할 때에는 다음 각 호의 사항을 기록하여야 한다. 다만, 제3호는 등기원인에 그 사항이 정하여져 있는 경우에만 기록한다.\n  1. 매수인이 지급한 대금\n  2. 매매비용\n  3. 환매기간"},{"법령":"부동산등기법","조문":"제52조제6호","원문":"6. 제53조의 환매특약등기"}],"선지":[{"번호":1,"판정":"옳음","설명":"환매권 보류는 매매등기와 동시에 등기해야 제3자에게 효력이 있다(민법 제592조). 소유권이전등기와 환매특약등기는 동시에 신청하고, 환매특약은 부기등기로 한다(법 제52조제6호)."},{"번호":2,"판정":"틀림","설명":"환매권을 보류하는 자는 매도인이다(민법 제590조제1항). 제3자를 환매권리자로 하는 환매특약등기는 할 수 없다."},{"번호":3,"판정":"옳음","설명":"환매특약등기는 환매권 보류를 제3자에게 공시해 대항력을 주는 등기다(민법 제592조). 매수인의 처분을 막는 효력은 없다."},{"번호":4,"판정":"옳음","설명":"환매는 매도인이 매매목적물을 되사는 제도다(민법 제590조제1항). 매매목적물 소유권 전체를 이전하면서 그 중 일부 지분에 대해서만 환매권을 보류하는 약정은 환매특약등기로 할 수 없다."},{"번호":5,"판정":"옳음","설명":"환매기간은 등기원인에 정해져 있는 경우에만 기록한다(법 제53조 단서). 매수인이 지급한 대금과 매매비용은 반드시 기록한다."}],"개념":[{"종류":"표","제목":"환매특약등기의 기록사항과 기간","머리":["구분","내용","근거"],"행":[["매수인이 지급한 대금","반드시 기록","법 제53조제1호"],["매매비용","반드시 기록","법 제53조제2호"],["환매기간","등기원인에 정해진 경우에만 기록","법 제53조 단서"],["환매기간 한도","부동산 5년, 동산 3년. 넘는 약정은 5년으로 단축, 연장 불가","민법 제591조제1항·제2항"],["기간을 정하지 않은 경우","부동산 5년","민법 제591조제3항"],["등기 형식","부기등기","법 제52조제6호"]]},{"종류":"흐름","제목":"환매특약등기 절차","단계":[{"이름":"매매계약과 환매권 보류","설명":"매도인이 매매계약과 동시에 환매권을 보류한다(민법 제590조제1항)."},{"이름":"동시 신청","설명":"소유권이전등기와 환매특약등기를 함께 신청한다. 신청정보에는 법 제53조의 사항을 낸다(규칙 제113조)."},{"이름":"부기등기","설명":"등기관이 환매특약을 소유권이전등기에 부기로 기록한다(법 제52조제6호)."},{"이름":"환매권 행사","설명":"매도인이 받은 대금과 매매비용을 반환하고 목적물을 되산다(민법 제590조제1항). 기간은 부동산 5년 이내다."},{"이름":"환매에 따른 이전등기와 직권말소","설명":"환매로 권리취득의 등기를 하면 등기관이 환매특약등기를 말소한다(규칙 제114조제1항)."}]}],"함정":"환매권리자를 제3자로 정할 수 있다는 선지는 당사자 자유처럼 보여 옳아 보인다. 환매권은 민법상 매도인만 갖는다. 환매기간은 필요적 기록사항이 아니고, 대금과 매매비용이 필요적 기록사항이므로 선지 5를 반대로 읽지 않는다."},"35회-2차-115":{"한줄":"수탁자 명의로 등기ㆍ등록된 신탁재산의 수탁자는 과세기준일부터 15일 이내에 증거자료를 갖추어 신고해야 하므로 ②가 옳다.","근거":[{"법령":"지방세법","조문":"제120조제1항","원문":"다음 각 호의 어느 하나에 해당하는 자는 과세기준일부터 15일 이내에 그 소재지를 관할하는 지방자치단체의 장에게 그 사실을 알 수 있는 증거자료를 갖추어 신고하여야 한다."},{"법령":"지방세법","조문":"제111조제1항제2호나목","원문":"과세표준의 1천분의 5"},{"법령":"지방세법","조문":"제113조제3항","원문":"주택을 2명 이상이 공동으로 소유하거나 토지와 건물의 소유자가 다를 경우 해당 주택에 대한 세율을 적용할 때 해당 주택의 토지와 건물의 가액을 합산한 과세표준에"},{"법령":"지방세법","조문":"제115조제1항제3호","원문":"다만, 해당 연도에 부과할 세액이 20만원 이하인 경우에는 조례로 정하는 바에 따라 납기를 7월 16일부터 7월 31일까지로 하여 한꺼번에 부과ㆍ징수할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"주거지역의 공장용 건축물은 과세표준의 1천분의 5 비례세율이다. 초과누진세율은 토지(종합합산ㆍ별도합산)와 주택에 적용한다(법 제111조제1항)."},{"번호":2,"판정":"옳음","설명":"수탁자 명의로 등기ㆍ등록된 신탁재산의 수탁자는 과세기준일부터 15일 이내에 신고한다(법 제120조제1항제4호)."},{"번호":3,"판정":"틀림","설명":"주택의 토지와 건물 소유자가 다르면 토지와 건물의 가액을 합산한 과세표준에 세율을 적용한다. 세액은 시가표준액 비율로 안분해 각 소유자에게 부과한다(법 제113조제3항, 제107조제1항제2호)."},{"번호":4,"판정":"틀림","설명":"주택분 세액이 20만원 이하이면 조례로 납기를 7월 16일부터 7월 31일까지로 하여 한꺼번에 부과할 수 있다(법 제115조제1항제3호 단서)."},{"번호":5,"판정":"틀림","설명":"과세대상 누락, 위법 또는 착오 등으로 이미 부과한 세액을 변경하거나 수시부과할 사유가 생기면 수시로 부과ㆍ징수할 수 있다(법 제115조제2항)."}],"개념":[{"종류":"표","제목":"재산세 표준세율(지방세법 제111조제1항)","머리":["과세대상","과세표준","세율"],"행":[["종합합산 토지","5천만원 이하 / 5천만원~1억원 / 1억원 초과","1천분의 2 / 10만원+초과분 1천분의 3 / 25만원+초과분 1천분의 5"],["별도합산 토지","2억원 이하 / 2억원~10억원 / 10억원 초과","1천분의 2 / 40만원+초과분 1천분의 3 / 280만원+초과분 1천분의 4"],["분리과세 토지","전ㆍ답ㆍ과수원ㆍ목장용지ㆍ임야","1천분의 0.7"],["분리과세 토지","골프장용 토지ㆍ고급오락장용 토지","1천분의 40"],["분리과세 토지","그 밖의 토지","1천분의 2"],["건축물","골프장ㆍ고급오락장용","1천분의 40"],["건축물","주거지역 등의 공장용 건축물","1천분의 5"],["건축물","그 밖의 건축물","1천분의 2.5"],["주택","6천만원 이하","1천분의 1"],["주택","6천만원~1억5천만원","6만원+초과분 1천분의 1.5"],["주택","1억5천만원~3억원","19만5천원+초과분 1천분의 2.5"],["주택","3억원 초과","57만원+초과분 1천분의 4"],["선박ㆍ항공기","고급선박 / 그 밖의 선박ㆍ항공기","1천분의 50 / 1천분의 3"]]},{"종류":"표","제목":"재산세 납기와 부과(지방세법 제115조ㆍ제116조)","머리":["과세대상","납기"],"행":[["토지","매년 9월 16일부터 9월 30일까지"],["건축물","매년 7월 16일부터 7월 31일까지"],["주택","세액의 1/2은 7월 16일~7월 31일, 나머지 1/2은 9월 16일~9월 30일"],["주택(세액 20만원 이하)","조례로 7월 16일~7월 31일에 한꺼번에 부과ㆍ징수 가능"],["선박ㆍ항공기","매년 7월 16일부터 7월 31일까지"],["과세대상 누락ㆍ위법ㆍ착오 등","이미 부과한 세액 변경이나 수시부과 사유가 생기면 수시로 부과ㆍ징수"],["납세고지서","토지ㆍ건축물ㆍ주택ㆍ선박ㆍ항공기로 구분해 늦어도 납기개시 5일 전까지 발급"]]}],"함정":"20만원 이하 주택을 한꺼번에 부과하는 납기는 7월이다. 9월은 주택 나머지 절반과 토지의 납기라서 날짜를 섞어 쓴 선지가 나온다. 세율은 토지ㆍ주택이 초과누진이고 건축물은 모두 비례세율이다."},"35회-1차-026":{"한줄":"헨리 조지는 토지 지대를 조세로 환수하는 토지단일세를 주장했다.","근거":[{"이론":"헨리 조지의 지대조세론","내용":"지대는 토지 소유자의 노력 없이 생기는 불로소득이므로 토지세 하나로 재정을 충당하고 다른 조세는 폐지하자고 주장했다."}],"선지":[{"번호":1,"판정":"-","설명":"뢰쉬는 수요 원추를 이용한 최대수요이론(공업·시장지역)을 제시했다."},{"번호":2,"판정":"-","설명":"레일리는 소매인력법칙을 제시했다."},{"번호":3,"판정":"-","설명":"알론소는 입찰지대곡선을 제시했다."},{"번호":4,"판정":"-","설명":"토지단일세를 주장한 학자는 헨리 조지다."},{"번호":5,"판정":"-","설명":"버제스는 동심원 도시공간구조이론을 제시했다."}],"개념":[{"종류":"표","제목":"학자별 핵심 이론","머리":["학자","이론","영역"],"행":[["헨리 조지","토지단일세(지대조세론)","지대·조세"],["버제스","동심원이론","도시공간구조"],["호이트","선형이론","도시공간구조"],["해리스·울만","다핵심이론","도시공간구조"],["레일리","소매인력법칙","상업입지"],["알론소","입찰지대","지대·토지이용"],["뢰쉬","최대수요이론","공업입지"]]}],"함정":"토지세와 관련된 학자를 알론소(입찰지대)와 혼동한다. 단일세는 헨리 조지다."},"35회-1차-015":{"한줄":"크리스탈러의 이론은 중심지이론이다. 동심원이론은 버제스의 도시공간구조이론이다.","근거":[{"이론":"도시공간구조이론과 중심지이론","내용":"동심원(버제스), 선형(호이트), 다핵심(해리스·울만)은 도시 내부 구조를, 중심지이론(크리스탈러)은 중심지의 계층과 배후지를 설명한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"선형이론은 동심원 구조에 방사형 교통축의 영향을 더해 발전시켰다."},{"번호":2,"판정":"틀림","설명":"크리스탈러는 중심지이론이다. 동심원이론은 버제스."},{"번호":3,"판정":"옳음","설명":"다핵심이론의 내용이다."},{"번호":4,"판정":"옳음","설명":"원료지수로 원료지향·시장지향을 판단한다."},{"번호":5,"판정":"옳음","설명":"허프모형에서 거리마찰계수는 사전에 정해야 하는 값이다."}],"개념":[{"종류":"표","제목":"도시공간구조 세 이론","머리":["이론","학자","핵심"],"행":[["동심원이론","버제스","중심업무지구 → 점이지대 → 저소득층 주거 → 중산층 주거 → 통근자 주거"],["선형이론","호이트","교통축을 따라 부채꼴로 확장, 소득계층별 주거 분화"],["다핵심이론","해리스·울만","여러 핵심 주위로 토지이용 분화"]]},{"종류":"비교","제목":"중심지이론과 동심원이론","왼쪽":{"이름":"중심지이론(크리스탈러)","항목":["중심지의 계층(고차·저차)과 배후지","육각형 상권, 최소요구치와 도달범위"]},"오른쪽":{"이름":"동심원이론(버제스)","항목":["도시 내부 토지이용이 동심원 띠로 분화","중심업무지구에서 바깥으로 띠 구조"]}}],"함정":"크리스탈러와 버제스의 이론을 섞어 놓은 보기에서 걸린다."},"35회-1차-025":{"한줄":"내부수익률법은 현금흐름의 재투자율을 내부수익률로 가정하고, 순현재가치법은 요구수익률로 가정한다.","근거":[{"이론":"NPV법과 IRR법의 재투자율 가정","내용":"NPV법: 중간 현금흐름을 요구수익률로 재투자한다고 가정한다. IRR법: 내부수익률로 재투자한다고 가정한다."},{"이론":"IRR의 한계","내용":"현금흐름의 부호가 여러 번 바뀌면 내부수익률이 여럿이거나 없을 수 있다. 투자규모·현금흐름 시점이 다른 상호배타적 투자안은 NPV법과 IRR법의 결론이 다를 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"두 방법 모두 현금흐름을 할인해 시간가치를 반영한다."},{"번호":2,"판정":"옳음","설명":"투자금액 차이가 크면 NPV가 큰 안과 IRR이 높은 안이 달라질 수 있다."},{"번호":3,"판정":"옳음","설명":"PI > 1이면 유입 현가가 유출 현가보다 크므로 NPV > 0이다."},{"번호":4,"판정":"옳음","설명":"부호가 여러 번 바뀌는 현금흐름에서는 내부수익률이 복수로 존재할 수 있다."},{"번호":5,"판정":"틀림","설명":"내부수익률법의 재투자율 가정은 내부수익률이다. 요구수익률을 재투자율로 보는 쪽은 순현재가치법이다."}],"개념":[{"종류":"비교","제목":"순현재가치법과 내부수익률법","왼쪽":{"이름":"순현재가치법","항목":["할인율은 요구수익률","재투자율은 요구수익률","가치가산의 원리 성립","결과는 금액"]},"오른쪽":{"이름":"내부수익률법","항목":["구하려는 값이 할인율","재투자율은 내부수익률","가치가산의 원리 불성립","복수의 IRR이 있거나 없을 수 있다"]}},{"종류":"표","제목":"두 방법의 결론이 갈리는 경우","머리":["상황","NPV법","IRR법","우선하는 기준"],"행":[["투자 규모 차이가 큰 상호배타 안","NPV가 큰 안","IRR이 높은 안","NPV법(부의 극대화)"],["현금흐름 시점이 다른 안","요구수익률로 재투자 가정","내부수익률로 재투자 가정","NPV법"],["부호가 여러 번 바뀌는 안","하나의 값","복수 또는 없음","NPV법"],["재투자율 가정","요구수익률","내부수익률","—"]]}],"함정":"⑤처럼 재투자율을 서로 바꿔 놓는 선지에 걸린다. 요구수익률 = NPV법, 내부수익률 = IRR법으로 묶어 둔다."},"35회-1차-006":{"한줄":"사업위탁방식은 토지소유권을 넘기지 않고 사업만 맡기고, 신탁개발방식은 토지소유권을 수탁자에게 이전한다.","근거":[{"이론":"개발사업의 방식","내용":"사업위탁방식: 토지소유자가 개발업자에게 사업 수행을 위탁하고 수수료를 지급하며 소유권은 소유자가 보유한다. 신탁개발방식: 토지를 신탁회사에 신탁(소유권 이전)하고 신탁회사가 개발·관리·처분한다."},{"이론":"민간투자사업 방식","내용":"BOT는 민간이 건설(Build)하고 소유·운영(Operate)한 뒤 소유권을 이전(Transfer)한다. BTO는 건설 후 소유권을 먼저 이전하고 운영한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"타당성분석의 시장분석은 시장지역(영향권)을 설정하는 것에서 시작한다."},{"번호":2,"판정":"옳음","설명":"개발업법상 부동산개발에는 건축물의 건축·대수선·리모델링·용도변경과 공작물 설치가 포함되며, 시공을 담당하는 행위는 제외된다."},{"번호":3,"판정":"옳음","설명":"BOT는 건설 → 소유·운영 → 이전 순서다."},{"번호":4,"판정":"옳음","설명":"신개발방식과 재개발방식으로 나눌 때 재건축·재개발 등 정비사업은 재개발방식에 속한다."},{"번호":5,"판정":"틀림","설명":"사업위탁방식에서는 토지소유권이 이전되지 않는다. 소유권을 이전하는 방식은 신탁개발방식이다."}],"개념":[{"종류":"표","제목":"개발사업 방식 비교","머리":["방식","토지 소유권","사업 주체","대가·수익"],"행":[["자체개발","소유자 보유","소유자","개발이익 전부 소유자"],["사업위탁(수탁)","소유자 보유","개발업자가 위탁받아 수행","소유자가 수수료 지급"],["신탁개발","수탁자에게 이전","신탁회사","수익자에게 신탁수익 배분"],["토지소유자·개발업자 공동","각자 보유 후 개발","공동 (지분 또는 분양수익 배분)","합의한 비율로 배분"]]},{"종류":"표","제목":"민간투자사업 방식","머리":["방식","순서","소유권 이전 시점"],"행":[["BTO","건설 → 이전 → 운영","준공 직후"],["BOT","건설 → 소유·운영 → 이전","운영기간 종료 후"],["BTL","건설 → 이전 → 임대(정부가 임차료 지급)","준공 직후"],["BOO","건설 → 소유·운영","이전 없음"]]}],"함정":"⑤는 사업위탁과 신탁을 같은 것으로 묶은 선지다. 소유권 이전 여부가 둘을 가른다. ④는 재건축이 신규 택지 조성이 아니라 기존 지역을 다시 정비하는 사업이라는 점에서 재개발방식으로 분류한다."},"35회-1차-038":{"한줄":"재조달원가에는 제세공과금이 포함된다. 제외한다는 선지가 틀렸다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제5호","원문":"  5. \"원가법\"이란 대상물건의 재조달원가에 감가수정(減價修正)을 하여 대상물건의 가액을 산정하는 감정평가방법을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제15조제1항","원문":"① 감정평가법인등은 건물을 감정평가할 때에 원가법을 적용해야 한다."},{"이론":"재조달원가","내용":"기준시점에 대상물건을 재생산하거나 재취득하는 데 필요한 적정원가의 총액이다. 표준적 건설비, 통상 부대비용, 수급인의 적정이윤, 제세공과금 등을 포함한다. 산정은 직접법(총량조사법·구성단위법)과 간접법(비용지수법)을 쓰며 병용할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"재조달원가의 정의 그대로다."},{"번호":2,"판정":"옳음","설명":"총량조사법·구성단위법·비용지수법은 재조달원가 산정방법이다."},{"번호":3,"판정":"틀림","설명":"재조달원가는 일반적인 방법으로 생산하거나 취득하는 데 드는 비용에 제세공과금 등을 포함한다."},{"번호":4,"판정":"옳음","설명":"표준적 건설비에는 수급인의 적정이윤이 포함된다."},{"번호":5,"판정":"옳음","설명":"재조달원가를 구할 때 직접법과 간접법을 병용할 수 있다."}],"개념":[{"종류":"표","제목":"재조달원가의 산정방법","머리":["구분","방법","내용"],"행":[["직접법","총량조사법","대상물건 전체에 소요되는 자재량·노무량을 조사해 단가를 곱한다"],["직접법","구성단위법","건물을 구성단위(지붕·벽 등)로 나눠 단위별 단가를 곱한다"],["간접법","비용지수법","건축 당시의 공사비에 기준시점까지의 건축비지수를 반영한다"],["병용","직접법 + 간접법","두 방법을 함께 써서 검증한다"]]},{"종류":"비교","제목":"재생산비용과 대체비용","왼쪽":{"이름":"재생산비용(복제원가)","항목":["물리적으로 동일한 물건을 재생산하는 비용","재조달원가 산정의 원칙"]},"오른쪽":{"이름":"대체비용(대치원가)","항목":["효용이 동일한 물건으로 대체하는 비용","구식 건물처럼 효용이 같은 현대식 물건으로 대체할 때 쓰며, 기능적 감가를 따로 반영할 필요가 없다"]}}],"함정":"‘제세공과금 제외’ 문장 하나에서 걸린다. 재조달원가에는 건설비 외에 수급인의 이윤, 제세공과금 등 부대비용이 들어간다."},"35회-1차-047":{"한줄":"본인이 무권대리행위를 알고 이의 없이 오래 방치한 사실만으로는 추인으로 인정되지 않는다.","근거":[{"법령":"민법","조문":"제131조","원문":"대리권없는 자가 타인의 대리인으로 계약을 한 경우에 상대방은 상당한 기간을 정하여 본인에게 그 추인여부의 확답을 최고할 수 있다. 본인이 그 기간내에 확답을 발하지 아니한 때에는 추인을 거절한 것으로 본다."},{"법령":"민법","조문":"제134조","원문":"대리권없는 자가 한 계약은 본인의 추인이 있을 때까지 상대방은 본인이나 그 대리인에 대하여 이를 철회할 수 있다. 그러나 계약당시에 상대방이 대리권 없음을 안 때에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"추인은 계약 시로 소급한다(제133조)."},{"번호":2,"판정":"틀림","설명":"추인은 무권대리행위로 인한 권리의 승계인에게도 할 수 있다."},{"번호":3,"판정":"틀림","설명":"계약 당시 대리권 없음을 안 상대방은 철회할 수 없다(제134조 단서)."},{"번호":4,"판정":"틀림","설명":"확답이 없으면 추인을 거절한 것으로 본다(제131조)."},{"번호":5,"판정":"옳음","설명":"방치만으로는 묵시적 추인이 아니다."}],"개념":[{"종류":"표","제목":"무권대리 상대방의 권리","머리":["권리","요건","효과","조문"],"행":[["최고권","선의·악의 불문","확답 없으면 거절 간주","제131조"],["철회권","선의일 것, 추인 전","계약 철회","제134조"],["무권대리인 책임 추궁","선의·무과실","이행 또는 손해배상","제135조"],["추인 거절의 확정","본인의 거절","이후 추인 불가","제130조"]]}],"함정":"4번에서 최고에 응하지 않으면 추인으로 본다고 오해하기 쉽다. 침묵은 거절이다."},"35회-1차-050":{"한줄":"기한이익 상실특약은 특별한 사정이 없는 한 채권자의 청구가 있어야 상실되는 형성권적 상실특약으로 추정한다.","근거":[{"법령":"민법","조문":"제153조","원문":"①기한은 채무자의 이익을 위한 것으로 추정한다.\n②기한의 이익은 이를 포기할 수 있다. 그러나 상대방의 이익을 해하지 못한다."},{"판례":"대법원 판례(기한이익 상실특약)","요지":"기한이익 상실특약은 특별한 사정이 없는 한 형성권적 기한이익 상실특약으로 추정한다. 정지조건부 특약으로 보려면 그런 취지가 인정되어야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"표시되지 않은 조건의사는 조건이 아니다."},{"번호":2,"판정":"틀림","설명":"정지조건부가 아니라 형성권적 특약으로 추정한다."},{"번호":3,"판정":"옳음","설명":"조건을 붙일 수 없는 행위(혼인, 상계 등)에 조건을 붙이면 전부 무효다."},{"번호":4,"판정":"옳음","설명":"정지조건 사실은 효력 발생을 다투는 자가 증명한다."},{"번호":5,"판정":"옳음","설명":"불확정기한은 사실이 발생하거나 발생하지 않기로 확정된 때 도래한다."}],"개념":[{"종류":"표","제목":"조건과 기한","머리":["구분","조건","기한"],"행":[["내용","발생 여부가 불확실","도래가 확실"],["효력","정지조건: 성취 시 발생 / 해제조건: 성취 시 소멸(제147조)","시기: 도래 시 발생 / 종기: 도래 시 소멸(제152조)"],["소급","당사자 의사로 소급 가능(제147조 제3항)","-"],["이익","-","채무자의 이익으로 추정, 포기 가능(제153조)"],["붙일 수 없는 행위","혼인, 입양, 상계, 취소, 추인 등","-"]]},{"종류":"표","제목":"조건 관련 특수 문제","머리":["유형","효과","조문"],"행":[["불법조건","법률행위 전부 무효","제151조 제1항"],["기성조건","정지조건이면 조건 없는 행위, 해제조건이면 무효","제151조 제2항"],["불능조건","해제조건이면 조건 없는 행위, 정지조건이면 무효","제151조 제3항"],["반신의행위","방해로 조건성취 주장 가능","제150조"]]}],"함정":"2번을 정지조건부로 외우기 쉽다. 판례는 청구가 있어야 상실되는 형성권적 특약으로 추정한다."},"35회-1차-070":{"한줄":"제3자의 권리가 생긴 뒤에는 당사자가 이를 변경·소멸시키지 못하지만, 계약에서 변경 권한을 유보했다면 변경할 수 있다.","근거":[{"법령":"민법","조문":"제539조","원문":"①계약에 의하여 당사자 일방이 제삼자에게 이행할 것을 약정한 때에는 그 제삼자는 채무자에게 직접 그 이행을 청구할 수 있다. ②전항의 경우에 제삼자의 권리는 그 제삼자가 채무자에 대하여 계약의 이익을 받을 의사를 표시한 때에 생긴다."},{"법령":"민법","조문":"제541조","원문":"제541조(제삼자의 권리의 확정) 제539조의 규정에 의하여 제삼자의 권리가 생긴 후에는 당사자는 이를 변경 또는 소멸시키지 못한다."},{"판례":"대법원 판례(제3자를 위한 계약)","요지":"요약자는 수익자의 동의 없이 낙약자의 채무불이행을 이유로 계약을 해제할 수 있다. 수익자는 계약당사자가 아니어서 취소권·해제권을 갖지 않는다. 요약자와 수익자 사이의 대가관계가 무효이더라도 낙약자는 이를 이유로 급부를 거절하지 못하고, 낙약자가 수익자에게 급부한 뒤 기본계약이 취소되면 낙약자는 요약자에게 부당이득반환을 청구한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"해제권은 계약당사자인 요약자에게 있고 수익자의 동의가 필요 없다(판례)."},{"번호":2,"판정":"틀림","설명":"수익자는 계약당사자가 아니므로 계약을 취소하지 못한다. 취소권은 당사자인 甲에게 있다."},{"번호":3,"판정":"틀림","설명":"요약자와 수익자 사이의 대가관계 흠결은 낙약자가 주장할 항변사유가 아니다. 乙은 대금지급을 거절하지 못한다(판례)."},{"번호":4,"판정":"틀림","설명":"급부한 낙약자는 계약 상대방인 요약자(甲)에게 부당이득반환을 청구한다. 수익자에게는 청구하지 못한다(판례)."},{"번호":5,"판정":"옳음","설명":"변경·소멸의 권한을 유보했다면 제541조의 제한이 적용되지 않고 당사자가 丙의 권리를 변경할 수 있다."}],"개념":[{"종류":"흐름","제목":"제3자를 위한 계약의 권리 발생","단계":[{"이름":"계약 체결","설명":"요약자와 낙약자가 제3자에게 이행하기로 약정(제539조 제1항)"},{"이름":"수익의 의사표시","설명":"수익자가 낙약자에게 계약의 이익을 받겠다고 표시, 이때 권리 발생(제539조 제2항)"},{"이름":"권리 확정","설명":"권리 발생 후 당사자는 변경·소멸 불가(제541조)"},{"이름":"최고","설명":"낙약자는 상당한 기간을 정해 확답을 최고, 확답 없으면 거절로 간주(제540조)"}]},{"종류":"표","제목":"제3자를 위한 계약의 3면 관계","머리":["관계","당사자","내용"],"행":[["기본관계(원인관계)","요약자-낙약자","계약의 효력, 하자가 있으면 낙약자가 수익자에게 대항 가능"],["대가관계(보상관계)","요약자-수익자","흠결이 있어도 낙약자의 급부의무에 영향 없음"],["급부관계","낙약자-수익자","수익자가 낙약자에게 직접 이행 청구"],["해제·취소","요약자","수익자는 당사자가 아니라 해제권·취소권이 없음"]]}],"함정":"3번을 맞다고 보기 쉽다. 요약자와 수익자 사이의 관계가 무효이면 급부를 받을 이유가 없다는 직관 때문이다. 대가관계는 요약자와 수익자 사이의 사정이라 낙약자의 항변사유가 아니다. 4번은 부당이득 반환의 상대방을 수익자로 잘못 잡은 선지다."},"35회-1차-075":{"한줄":"갱신된 임대차의 해지는 임대인이 통지를 받은 날부터 3개월이 지나면 효력이 생기므로 2024. 1. 30.부터 3개월이 지난 2024. 4. 30.에 끝난다.","근거":[{"법령":"주택임대차보호법","조문":"제6조의3제1항·제2항·제4항","원문":"① 제6조에도 불구하고 임대인은 임차인이 제6조제1항 전단의 기간 이내에 계약갱신을 요구할 경우 정당한 사유 없이 거절하지 못한다. … ② 임차인은 제1항에 따른 계약갱신요구권을 1회에 한하여 행사할 수 있다. 이 경우 갱신되는 임대차의 존속기간은 2년으로 본다. … ④ 제1항에 따라 갱신되는 임대차의 해지에 관하여는 제6조의2를 준용한다."},{"법령":"주택임대차보호법","조문":"제6조의2","원문":"① 제6조제1항에 따라 계약이 갱신된 경우 같은 조 제2항에도 불구하고 임차인은 언제든지 임대인에게 계약해지(契約解止)를 통지할 수 있다. ② 제1항에 따른 해지는 임대인이 그 통지를 받은 날부터 3개월이 지나면 그 효력이 발생한다."},{"법령":"주택임대차보호법","조문":"제6조제1항","원문":"① 임대인이 임대차기간이 끝나기 6개월 전부터 2개월 전까지의 기간에 임차인에게 갱신거절(更新拒絶)의 통지를 하지 아니하거나 … 그 기간이 끝난 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다."}],"선지":[{"번호":1,"판정":"-","설명":"해지 통지가 도달한 날이다. 해지는 도달일부터 3개월이 지나야 효력이 생긴다."},{"번호":2,"판정":"-","설명":"종전 임대차의 만료일이다. 갱신된 임대차가 시작되기 전에도 해지 통지를 할 수 있고 효력은 도달일 기준 3개월 뒤다."},{"번호":3,"판정":"-","설명":"통지 도달일 2024. 1. 30.부터 3개월이 지난 날이다. 정답."},{"번호":4,"판정":"-","설명":"만료일 2024. 3. 10.부터 3개월을 센 날로 기산점이 틀렸다."},{"번호":5,"판정":"-","설명":"갱신된 2년 기간의 만료일이다. 임차인이 중도 해지를 통지했으므로 이 날까지 가지 않는다."}],"개념":[{"종류":"흐름","제목":"갱신요구권 행사 후 종료","단계":[{"이름":"갱신요구","설명":"만료 6개월 전부터 2개월 전까지, 이 사례는 2024. 1. 5. 도달(2024. 1. 10.까지 가능)"},{"이름":"갱신","설명":"임대인이 거절 사유 없이 거절하지 않으면 전 임대차와 같은 조건, 존속기간 2년(제6조의3 제2항·제3항)"},{"이름":"임차인의 해지 통지","설명":"언제든 가능(제6조의2 제1항), 2024. 1. 30. 도달"},{"이름":"해지 효력","설명":"임대인이 통지를 받은 날부터 3개월이 지나면 효력(제6조의2 제2항), 2024. 4. 30."}]},{"종류":"표","제목":"임대인이 갱신요구를 거절할 수 있는 사유","머리":["사유","근거"],"행":[["2기의 차임액에 이르도록 연체","제6조의3 제1항 제1호"],["거짓·부정한 방법으로 임차","제2호"],["합의로 상당한 보상 제공","제3호"],["동의 없는 전대","제4호"],["고의·중과실로 주택 파손","제5호"],["철거·재건축","제7호"],["임대인(직계존비속 포함) 실거주","제8호"]]}],"함정":"2번이나 5번을 고르는 경우가 많다. 갱신 효과 때문에 3월 10일이나 갱신 만료일에 끝난다고 보기 때문이다. 갱신된 임대차에서 임차인은 언제든 해지를 통지할 수 있고 효력은 임대인이 통지를 받은 날부터 3개월 뒤다. 임차인의 해지 통지일(1월 29일)이 아니라 도달일(1월 30일)이 기준이다."},"35회-2차-020":{"한줄":"비주거용 확인·설명서[Ⅱ]의 기본 확인사항에는 관리비 항목이 없다. 관리비는 주택 임대차의 확인사항이고 주거용[Ⅰ] 서식에 있다.","근거":[{"법령":"공인중개사법 시행령","조문":"제21조 제1항 제1호 제2호 제3호 3의2. 제8호","원문":"①법 제25조제1항에 따라 개업공인중개사가 확인ㆍ설명해야 하는 사항은 다음 각 호와 같다. 다만, 제3호의2 및 제10호부터 제12호까지의 사항은 주택 임대차 중개의 경우에만 적용한다.\n1. 중개대상물의 종류ㆍ소재지ㆍ지번ㆍ지목ㆍ면적ㆍ용도ㆍ구조 및 건축연도 등 중개대상물에 관한 기본적인 사항\n2. 소유권ㆍ전세권ㆍ저당권ㆍ지상권 및 임차권 등 중개대상물의 권리관계에 관한 사항\n3. 거래예정금액ㆍ중개보수 및 실비의 금액과 그 산출내역\n3의2. 관리비 금액과 그 산출내역\n4. 토지이용계획, 공법상의 거래규제 및 이용제한에 관한 사항\n5. 수도ㆍ전기ㆍ가스ㆍ소방ㆍ열공급ㆍ승강기 및 배수 등 시설물의 상태\n6. 벽면ㆍ바닥면 및 도배의 상태\n7. 일조ㆍ소음ㆍ진동 등 환경조건\n8. 도로 및 대중교통수단과의 연계성, 시장ㆍ학교와의 근접성 등 입지조건\n9. 중개대상물에 대한 권리를 취득함에 따라 부담하여야 할 조세의 종류 및 세율\n10. 「주택임대차보호법」 제3조의7에 따른 임대인의 정보 제시 의무 및 같은 법 제8조에 따른 보증금 중 일정액의 보호에 관한 사항\n11. 「주민등록법」 제29조의2에 따른 전입세대확인서의 열람 또는 교부에 관한 사항\n12. 「민간임대주택에 관한 특별법」 제49조에 따른 임대보증금에 대한 보증에 관한 사항(중개대상물인 주택이 같은 법에 따른 민간임대주택인 경우만 해당한다)\n1. 중개대상물의 종류ㆍ소재지ㆍ지번ㆍ지목ㆍ면적ㆍ용도ㆍ구조 및 건축연도 등 중개대상물에 관한 기본적인 사항\n2. 소유권ㆍ전세권ㆍ저당권ㆍ지상권 및 임차권 등 중개대상물의 권리관계에 관한 사항\n3. 거래예정금액ㆍ중개보수 및 실비의 금액과 그 산출내역\n3의2. 관리비 금액과 그 산출내역\n8. 도로 및 대중교통수단과의 연계성, 시장ㆍ학교와의 근접성 등 입지조건"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호의2서식(비주거용 건축물) Ⅰ. 개업공인중개사 기본 확인사항","원문":"① 대상물건의 표시\n② 권리관계(등기부 기재사항)\n③ 토지이용계획, 공법상 이용제한 및 거래규제에 관한 사항(토지)\n④ 입지조건\n⑤ 관리에 관한 사항(경비실, 관리주체)\n⑥ 거래예정금액 등\n⑦ 취득 시 부담할 조세의 종류 및 세율"}],"선지":[{"번호":1,"판정":"-","설명":"①번 항목이다. 기본 확인사항이다."},{"번호":2,"판정":"-","설명":"②번 권리관계 항목의 등기부 기재사항이다. 기본 확인사항이다."},{"번호":3,"판정":"-","설명":"[Ⅱ] 기본 확인사항에 관리비 금액·산출내역 항목은 없다. 관리에 관한 사항은 경비실과 관리주체만 적는다."},{"번호":4,"판정":"-","설명":"④번 항목이다. 기본 확인사항이다."},{"번호":5,"판정":"-","설명":"⑥번 거래예정금액 등 항목이다. 기본 확인사항이다."}],"개념":[{"종류":"표","제목":"확인·설명서[Ⅱ](비주거용) 구성","머리":["구분","항목"],"행":[["Ⅰ. 기본 확인사항","① 대상물건의 표시 ② 권리관계 ③ 토지이용계획·공법상 제한(토지) ④ 입지조건 ⑤ 관리에 관한 사항 ⑥ 거래예정금액 등 ⑦ 취득 시 조세"],["Ⅱ. 세부 확인사항","⑧ 실제 권리관계 또는 공시되지 않은 물건의 권리 사항 ⑨ 내부·외부 시설물의 상태 ⑩ 벽면 및 바닥면"],["Ⅲ. 중개보수 등","⑪ 중개보수 및 실비의 금액과 산출내역"]]},{"종류":"표","제목":"확인·설명서 서식 4종(칙 제16조)","머리":["서식","대상"],"행":[["[Ⅰ] 별지 제20호","주거용 건축물"],["[Ⅱ] 별지 제20호의2","비주거용 건축물"],["[Ⅲ] 별지 제20호의3","토지"],["[Ⅳ] 별지 제20호의4","입목·광업재단·공장재단"]]}],"함정":"관리비와 비선호시설은 주거용 [Ⅰ]에만 있는 항목이다. [Ⅱ]에서 이 두 가지가 정답이 된다."},"35회-2차-057":{"한줄":"토지 소유권 전부를 이전받은 조합원은 정관이 정하는 바에 따라 본래의 의결권과 별도로 이전한 조합원의 의결권을 승계할 수 있다.","근거":[{"법령":"도시개발법","조문":"제13조제1항","원문":"조합을 설립하려면 도시개발구역의 토지 소유자 7명 이상이 대통령령으로 정하는 사항을 포함한 정관을 작성하여 지정권자에게 조합 설립의 인가를 받아야 한다."},{"법령":"도시개발법","조문":"제13조제2항","원문":"조합이 제1항에 따라 인가를 받은 사항을 변경하려면 지정권자로부터 변경인가를 받아야 한다. 다만, 대통령령으로 정하는 경미한 사항을 변경하려는 경우에는 신고하여야 한다."},{"법령":"도시개발법 시행령","조문":"제30조","원문":"법 제13조제2항 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하려는 경우\"란 다음 각 호의 경우를 말한다. 1. 주된 사무소의 소재지를 변경하려는 경우 2. 공고방법을 변경하려는 경우"},{"법령":"도시개발법 시행령","조문":"제32조제2항제1호","원문":"조합원의 권리 및 의무는 다음 각 호와 같다. 1. 보유토지의 면적과 관계없는 평등한 의결권. 다만, 다른 조합원으로부터 해당 도시개발구역에 그가 가지고 있는 토지 소유권 전부를 이전 받은 조합원은 정관으로 정하는 바에 따라 본래의 의결권과는 별도로 그 토지 소유권을 이전한 조합원의 의결권을 승계할 수 있다."},{"법령":"도시개발법 시행령","조문":"제36조제1항","원문":"의결권을 가진 조합원의 수가 50인 이상인 조합은 총회의 권한을 대행하게 하기 위하여 대의원회를 둘 수 있다."},{"법령":"도시개발법","조문":"제14조제4항","원문":"조합의 임원으로 선임된 자가 제3항 각 호의 어느 하나에 해당하게 된 경우에는 그 다음 날부터 임원의 자격을 상실한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"조합 설립은 토지소유자 7명 이상이 정관을 작성해 인가를 받는다(법 제13조제1항). 10명이 아니다."},{"번호":2,"판정":"틀림","설명":"인가받은 사항의 변경은 변경인가가 원칙이다. 신고로 되는 경미한 사항은 주된 사무소 소재지와 공고방법 변경뿐이다(법 제13조제2항, 영 제30조). 청산에 관한 사항은 변경인가 대상이다."},{"번호":3,"판정":"옳음","설명":"조합원의 의결권은 보유 토지 면적과 관계없이 평등하지만, 다른 조합원의 토지 소유권 전부를 이전받은 조합원은 정관이 정하는 바에 따라 이전한 조합원의 의결권을 별도로 승계할 수 있다(영 제32조제2항제1호)."},{"번호":4,"판정":"틀림","설명":"의결권을 가진 조합원이 50인 이상인 조합이 대의원회를 ‘둘 수 있다’. 반드시 두어야 하는 것은 아니다(영 제36조제1항)."},{"번호":5,"판정":"틀림","설명":"임원 결격사유에 해당하게 되면 그 ‘다음 날부터’ 임원 자격을 상실한다(법 제14조제4항)."}],"개념":[{"종류":"흐름","제목":"도시개발조합의 설립","단계":[{"이름":"정관 작성","설명":"토지소유자 7명 이상이 정관 작성(법 제13조제1항), 정관 기재사항은 영 제29조"},{"이름":"동의","설명":"인가 신청 전에 구역 토지면적의 3분의 2 이상 소유자와 소유자 총수의 2분의 1 이상 동의(법 제13조제3항)"},{"이름":"설립 인가","설명":"지정권자의 인가, 변경도 변경인가(경미한 사항은 신고)"},{"이름":"설립 등기","설명":"인가받은 날부터 30일 이내 주된 사무소 소재지에서 등기(영 제32조제1항), 등기하면 법인으로 성립(법 제15조제2항)"},{"이름":"운영","설명":"조합장 1명, 이사, 감사 임원, 총회 의결, 50인 이상이면 대의원회를 둘 수 있음(영 제33조ㆍ제36조)"}]},{"종류":"표","제목":"조합의 임원과 총회","머리":["구분","내용","근거"],"행":[["임원 겸직","조합의 다른 임원이나 직원을 겸할 수 없음","법 제14조제2항"],["임원 결격","피성년후견인ㆍ피한정후견인ㆍ미성년자, 복권되지 않은 파산선고자, 금고 이상 형 집행 종료 후 2년이 지나지 않은 자 등","법 제14조제3항"],["자격 상실","결격사유에 해당하게 된 날의 다음 날부터","법 제14조제4항"],["대의원 수","의결권을 가진 조합원 총수의 100분의 10 이상","영 제36조제2항"],["대의원회가 대행 못하는 사항","정관 변경, 개발계획ㆍ실시계획 수립(경미한 변경 제외), 환지계획 작성, 임원 선임, 합병ㆍ해산 등","영 제36조제3항"],["총회 의결","정관 변경, 개발계획ㆍ실시계획, 자금 차입, 수지예산, 환지계획, 환지예정지 지정, 체비지 처분방법 등","영 제35조"]]}],"함정":"7명, 신고 대상 두 가지(주된 사무소 소재지, 공고방법), 50인, 다음 날부터가 한 문항에 모여 있다. 정답률은 27퍼센트였다."},"35회-2차-059":{"한줄":"재건축사업의 토지등소유자는 건축물 및 그 부속토지의 소유자뿐이고, 지상권자는 재개발사업과 주거환경개선사업에서만 토지등소유자가 된다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제2조제9호","원문":"이 법에서 사용하는 용어의 뜻은 다음과 같다. 9. \"토지등소유자\"란 다음 각 목의 어느 하나에 해당하는 자를 말한다. 다만, 제27조제1항에 따라 「자본시장과 금융투자업에 관한 법률」 제8조제7항에 따른 신탁업자(이하 \"신탁업자\"라 한다)가 사업시행자로 지정된 경우 토지등소유자가 정비사업을 목적으로 신탁업자에게 신탁한 토지 또는 건축물에 대하여는 위탁자를 토지등소유자로 본다. 가. 주거환경개선사업 및 재개발사업의 경우에는 정비구역에 위치한 토지 또는 건축물의 소유자 또는 그 지상권자 나. 재건축사업의 경우에는 정비구역에 위치한 건축물 및 그 부속토지의 소유자"}],"선지":[{"번호":1,"판정":"옳음","설명":"주거환경개선사업은 정비구역에 위치한 토지 또는 건축물의 소유자 또는 그 지상권자가 토지등소유자다(법 제2조제9호가목)."},{"번호":2,"판정":"옳음","설명":"재개발사업은 토지의 소유자뿐 아니라 그 지상권자도 토지등소유자다(법 제2조제9호가목)."},{"번호":3,"판정":"옳음","설명":"재개발사업의 건축물 소유자는 토지등소유자다(법 제2조제9호가목)."},{"번호":4,"판정":"옳음","설명":"재건축사업은 건축물 및 그 부속토지의 소유자가 토지등소유자다(법 제2조제9호나목)."},{"번호":5,"판정":"틀림","설명":"재건축사업은 건축물 및 부속토지의 ‘소유자’만 토지등소유자다. 부속토지의 지상권자는 해당하지 않는다(법 제2조제9호나목)."}],"개념":[{"종류":"표","제목":"정비사업별 토지등소유자(법 제2조제9호)","머리":["정비사업","토지등소유자"],"행":[["주거환경개선사업","정비구역에 위치한 토지 또는 건축물의 소유자 또는 그 지상권자"],["재개발사업","정비구역에 위치한 토지 또는 건축물의 소유자 또는 그 지상권자"],["재건축사업","정비구역에 위치한 건축물 및 그 부속토지의 소유자"],["신탁업자가 사업시행자로 지정된 경우","정비사업을 목적으로 신탁한 토지 또는 건축물에 대하여는 위탁자를 토지등소유자로 봄"]]},{"종류":"비교","제목":"재개발사업과 재건축사업(법 제2조제2호)","왼쪽":{"이름":"재개발사업","항목":["정비기반시설이 열악하고 노후ㆍ불량건축물이 밀집한 지역의 주거환경 개선","상업지역ㆍ공업지역 등에서 도시기능 회복 및 상권활성화 등을 위한 도시환경 개선","토지 또는 건축물의 소유자와 지상권자가 토지등소유자"]},"오른쪽":{"이름":"재건축사업","항목":["정비기반시설은 양호하나 노후ㆍ불량건축물에 해당하는 공동주택이 밀집한 지역의 주거환경 개선","건축물 및 그 부속토지의 소유자만 토지등소유자","토지만 가진 자나 지상권자는 토지등소유자가 아님"]}}],"함정":"재건축은 ‘건축물 및 부속토지’를 함께 가진 소유자만 토지등소유자다. 선지 2와 선지 5의 지상권자를 비교해야 한다. 재개발사업의 토지 지상권자는 포함되고 재건축사업의 부속토지 지상권자는 제외된다. 이 문항의 정답률은 28퍼센트였다."},"35회-2차-070":{"한줄":"정보를 제공한 취급기관은 제공 사실을 명의인에게 알리지 않을 수 있지만, 명의인이 요구하면 반드시 알려야 한다.","근거":[{"법령":"주택법","조문":"제56조제7항","원문":"제6항에 따라 입주자저축정보를 제공한 입주자저축취급기관의 장은 「금융실명거래 및 비밀보장에 관한 법률」 제4조의2제1항에도 불구하고 입주자저축정보의 제공사실을 명의인에게 통보하지 아니할 수 있다. 다만, 입주자저축정보를 제공하는 입주자저축취급기관의 장은 입주자저축정보의 명의인이 요구할 때에는 입주자저축정보의 제공사실을 통보하여야 한다."},{"법령":"주택법","조문":"제56조제2항·제4항·제6항","원문":"제1항에서 \"입주자저축\"이란 국민주택과 민영주택을 공급받기 위하여 가입하는 주택청약종합저축을 말한다. / 입주자저축은 한 사람이 한 계좌만 가입할 수 있다. / 제5항에 따라 입주자저축정보의 제공 요청을 받은 입주자저축취급기관의 장은 「금융실명거래 및 비밀보장에 관한 법률」 제4조에도 불구하고 입주자저축정보를 제공하여야 한다."},{"법령":"주택법 시행령","조문":"제58조의3","원문":"국토교통부장관은 법 제56조제9항에 따라 입주자저축에 관한 국토교통부령을 제정하거나 개정할 때에는 재정경제부장관과 미리 협의해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"명의인이 요구하면 제공 사실을 통보해야 한다. 요구에도 알리지 않아도 된다는 문장은 틀리다(법 제56조제7항 단서)."},{"번호":2,"판정":"옳음","설명":"요청을 받은 취급기관의 장은 금융실명법 제4조에도 불구하고 정보를 제공해야 한다(법 제56조제6항)."},{"번호":3,"판정":"옳음","설명":"입주자저축은 국민주택과 민영주택을 공급받기 위해 가입하는 주택청약종합저축이다(법 제56조제2항)."},{"번호":4,"판정":"옳음","설명":"입주자저축 국토교통부령을 제정·개정할 때의 협의 상대는 재정경제부장관이다(영 제58조의3)."},{"번호":5,"판정":"옳음","설명":"한 사람이 한 계좌만 가입한다(법 제56조제4항)."}],"개념":[{"종류":"표","제목":"입주자저축(법 제56조)","머리":["항목","내용","조문"],"행":[["정의","국민주택과 민영주택을 공급받기 위해 가입하는 주택청약종합저축","제2항"],["취급기관","은행법상 은행 중 국토교통부장관이 지정","제3항"],["가입 제한","한 사람이 한 계좌","제4항"],["정보 제공 요청 업무","입주자자격·재당첨 제한·공급 순위 확인, 기존 가입 여부 확인, 세금우대저축자료 중계, 정보 정확성 유지","제5항"],["제공 의무","요청을 받은 취급기관의 장은 금융실명법 제4조에도 불구하고 제공","제6항"],["명의인 통보","통보하지 않을 수 있으나, 명의인이 요구하면 통보","제7항"],["제공 방식","정보통신망 이용(불가피한 사유는 예외)","제8항"],["부령 제·개정","국토교통부령 제정·개정 시 재정경제부장관과 미리 협의","영 제58조의3"],["목적 외 사용","업무 종사자는 목적 외 사용·제공·누설 금지","제10항"]]},{"종류":"흐름","제목":"입주자저축정보 제공 절차","단계":[{"이름":"정보 제공 요청","설명":"국토교통부장관이 공급 자격 확인 등 법정 업무를 위해 취급기관의 장에게 요청(법 제56조제5항)"},{"이름":"정보 제공","설명":"취급기관의 장이 금융실명법 제4조에도 불구하고 제공. 정보통신망 이용(법 제56조제6항·제8항)"},{"이름":"제공 사실 통보","설명":"명의인에게는 알리지 않을 수 있으나 명의인이 요구하면 통보(법 제56조제7항)"},{"이름":"사용 제한","설명":"업무 목적 외 사용·제공·누설 금지(법 제56조제10항)"}]}],"함정":"제공 사실을 통보하지 않을 수 있다는 원칙에는 단서가 붙는다. 명의인이 요구하면 통보한다. 부령 제·개정 협의 상대는 기획재정부장관이 아니라 재정경제부장관이다.","개정":"입주자저축에 관한 국토교통부령을 제정·개정할 때의 협의 상대가 기획재정부장관에서 재정경제부장관으로 바뀌었다(영 제58조의3, 2025.12.30 개정). 정답은 달라지지 않는다."},"35회-2차-113":{"한줄":"사실상 종중재산이라도 종중 소유임을 신고하지 않으면 재산세 납세의무자는 종중이 아니라 공부상 소유자다.","근거":[{"법령":"지방세법","조문":"제107조제2항제3호","원문":"3. 공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중재산으로서 종중소유임을 신고하지 아니하였을 때에는 공부상 소유자"},{"법령":"지방세법","조문":"제107조제2항제2호","원문":"2. 상속이 개시된 재산으로서 상속등기가 이행되지 아니하고 사실상의 소유자를 신고하지 아니하였을 때에는 행정안전부령으로 정하는 주된 상속자"},{"법령":"지방세법","조문":"제107조제2항제6호","원문":"6. 「도시개발법」에 따라 시행하는 환지(換地) 방식에 의한 도시개발사업 및 「도시 및 주거환경정비법」에 따른 정비사업(재개발사업만 해당한다)의 시행에 따른 환지계획에서 일정한 토지를 환지로 정하지 아니하고 체비지 또는 보류지로 정한 경우에는 사업시행자"},{"법령":"지방세법","조문":"제107조제2항제8호","원문":"8. 「채무자 회생 및 파산에 관한 법률」에 따른 파산선고 이후 파산종결의 결정까지 파산재단에 속하는 재산의 경우 공부상 소유자"},{"법령":"지방세법","조문":"제107조제2항제4호","원문":"4. 국가, 지방자치단체, 지방자치단체조합과 재산세 과세대상 재산을 연부(年賦)로 매매계약을 체결하고 그 재산의 사용권을 무상으로 받은 경우에는 그 매수계약자"}],"선지":[{"번호":1,"판정":"틀림","설명":"종중 소유임을 신고하지 않은 사실상 종중재산은 공부상 소유자가 납세의무자다(지방세법 제107조제2항제3호)."},{"번호":2,"판정":"옳음","설명":"상속등기가 안 되고 사실상 소유자 신고도 없으면 행정안전부령으로 정하는 주된 상속자가 납부한다(지방세법 제107조제2항제2호)."},{"번호":3,"판정":"옳음","설명":"재개발사업 등의 환지계획에서 체비지·보류지로 정한 토지는 사업시행자가 납세의무자다(지방세법 제107조제2항제6호)."},{"번호":4,"판정":"옳음","설명":"파산선고 이후 파산종결 결정까지 파산재단 재산은 공부상 소유자가 납세의무자다(지방세법 제107조제2항제8호)."},{"번호":5,"판정":"옳음","설명":"국가·지방자치단체와 연부매매계약을 맺고 사용권을 무상으로 받았으면 그 매수계약자가 납세의무자다(지방세법 제107조제2항제4호)."}],"개념":[{"종류":"표","제목":"재산세 납세의무자 특례(과세기준일 현재)","머리":["상황","납세의무자"],"행":[["원칙","과세기준일 현재 재산을 사실상 소유하고 있는 자(공유재산은 지분권자)"],["소유권 변동 후 신고 없어 사실상 소유자를 알 수 없음","공부상 소유자"],["상속등기 안 되고 사실상 소유자 신고 없음","행정안전부령이 정하는 주된 상속자"],["사실상 종중재산을 개인 명의로 등재, 종중 소유 신고 없음","공부상 소유자"],["국가·지방자치단체·지방자치단체조합과 연부매매하고 사용권을 무상으로 받음","그 매수계약자"],["수탁자 명의 신탁재산","위탁자"],["도시개발 환지방식·재개발사업의 체비지·보류지","사업시행자"],["외국인 소유 항공기·선박을 임차하여 수입","수입하는 자"],["파산선고 이후 파산종결까지 파산재단 재산","공부상 소유자"]]},{"종류":"표","제목":"재산세 신고의무자(과세기준일부터 15일 이내)","머리":["신고 대상 사유","신고의무자"],"행":[["소유권 변동이 있었으나 과세기준일까지 등기·등록이 안 된 재산","공부상 소유자"],["상속이 개시되었으나 상속등기가 안 된 재산","주된 상속자"],["사실상 종중재산으로 공부상 개인 명의","공부상 소유자"],["수탁자 명의로 등기·등록된 신탁재산","수탁자"],["1세대가 2주택 이상 소유하면서 1세대 1주택 특례세율을 받으려는 경우","그 세대원"],["공부상 현황과 사실상 현황이 다르거나 변경된 경우","해당 재산의 사실상 소유자"]]}],"함정":"1번은 실제 주인이 종중이니 종중이 낸다고 보는 경우가 많다. 신고하지 않은 책임은 공부상 소유자가 진다. 3번은 체비지만 적혀 있지만 조문이 체비지 또는 보류지이므로 옳은 문장이다."},"35회-1차-001":{"한줄":"용도의 다양성 때문에 용도 전환이 가능해 물리적 공급이 고정이어도 특정 용도의 경제적 공급은 늘 수 있다.","근거":[{"이론":"토지의 특성","내용":"자연적 특성은 부동성·영속성·부증성·개별성이고, 인문적 특성은 용도의 다양성·합병분할의 가능성·위치의 가변성이다. 부증성은 물리적 공급을 비탄력으로, 영속성은 감가상각 배제와 가치보존을 낳는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"부동성 때문에 인접 토지에 영향이 미치는 외부효과가 발생한다."},{"번호":2,"판정":"틀림","설명":"개별성 때문에 같은 토지가 없어 거래사례 비교가 어렵고 지가 산정이 쉽지 않다."},{"번호":3,"판정":"틀림","설명":"부증성 때문에 토지의 물리적 공급은 단기적으로 비탄력적(고정)이다."},{"번호":4,"판정":"옳음","설명":"용도의 다양성으로 용도 전환이 가능해 경제적 공급은 증가할 수 있다."},{"번호":5,"판정":"틀림","설명":"영속성 때문에 토지는 소모되지 않아 감가상각을 하지 않는다. 감가상각은 건물에 적용한다."}],"개념":[{"종류":"표","제목":"토지의 특성과 파생현상","머리":["특성","구분","파생현상"],"행":[["부동성","자연적","지역분석, 외부효과, 임장활동, 지방세(재산세)"],["영속성","자연적","감가상각 배제, 가치보존, 장기투자, 재생산 이론"],["부증성","자연적","물리적 공급 비탄력, 지대·지가 발생, 집약적 이용"],["개별성","자연적","부동산 가격의 개별화, 비교 곤란, 일물일가 불성립"],["용도의 다양성","인문적","경제적 공급 가능, 최유효이용"],["합병·분할의 가능성","인문적","토지 이용 규모 조정"],["위치의 가변성","인문적","사회·경제·행정적 위치 변화"]]}],"함정":"부증성은 '물리적' 공급이 고정이라는 뜻이다. 경제적 공급과 구분하지 못하면 3번과 4번에서 갈린다."},"35회-1차-039":{"한줄":"공시기준일 이후 토지 분할·합병이나 건축물 신축 등이 생겨 공동주택가격을 따로 결정·공시하는 주체는 시장·군수·구청장이 아니라 국토교통부장관이다.","근거":[{"법령":"부동산 가격공시에 관한 법률","조문":"제18조제1항·제4항","원문":"① 국토교통부장관은 공동주택에 대하여 매년 공시기준일 현재의 적정가격(이하 \"공동주택가격\"이라 한다)을 조사ㆍ산정하여 제24조에 따른 중앙부동산가격공시위원회의 심의를 거쳐 공시하고, 이를 관계 행정기관 등에 제공하여야 한다. 다만, 대통령령으로 정하는 바에 따라 국세청장이 국토교통부장관과 협의하여 공동주택가격을 별도로 결정ㆍ고시하는 경우는 제외한다.\n④ 국토교통부장관은 공시기준일 이후에 토지의 분할ㆍ합병이나 건축물의 신축 등이 발생한 경우에는 대통령령으로 정하는 날을 기준으로 하여 공동주택가격을 결정ㆍ공시하여야 한다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제17조제2항","원문":"② 제1항에도 불구하고 표준주택으로 선정된 단독주택, 그 밖에 대통령령으로 정하는 단독주택에 대하여는 개별주택가격을 결정ㆍ공시하지 아니할 수 있다. 이 경우 표준주택으로 선정된 주택에 대하여는 해당 주택의 표준주택가격을 개별주택가격으로 본다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제19조","원문":"① 표준주택가격은 국가ㆍ지방자치단체 등이 그 업무와 관련하여 개별주택가격을 산정하는 경우에 그 기준이 된다.\n② 개별주택가격 및 공동주택가격은 주택시장의 가격정보를 제공하고, 국가ㆍ지방자치단체 등이 과세 등의 업무와 관련하여 주택의 가격을 산정하는 경우에 그 기준으로 활용될 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"표준주택으로 선정된 단독주택과 대통령령으로 정하는 단독주택은 개별주택가격을 결정·공시하지 않을 수 있다. 표준주택은 그 표준주택가격을 개별주택가격으로 본다(제17조제2항)."},{"번호":2,"판정":"옳음","설명":"표준주택가격은 국가·지방자치단체 등이 개별주택가격을 산정하는 경우의 기준이 된다(제19조제1항)."},{"번호":3,"판정":"옳음","설명":"개별주택가격과 공동주택가격은 주택시장의 가격정보를 제공하고, 과세 등 업무의 주택 가격 산정에 기준으로 활용될 수 있다(제19조제2항)."},{"번호":4,"판정":"옳음","설명":"개별주택가격에 이의가 있으면 결정·공시일부터 30일 이내에 서면(전자문서 포함)으로 시장·군수·구청장에게 신청한다(제17조제8항, 제11조제1항)."},{"번호":5,"판정":"틀림","설명":"공시기준일 이후 분할·합병·신축 등이 있는 공동주택의 가격은 국토교통부장관이 결정·공시한다(제18조제4항)."}],"개념":[{"종류":"표","제목":"부동산 가격공시의 주체·기준일·기한","머리":["구분","공시 주체","공시기준일","결정·공시 기한","이의신청"],"행":[["표준지공시지가","국토교통부장관","1월 1일","-","공시일부터 30일 이내, 국토교통부장관"],["개별공시지가","시장·군수·구청장","1월 1일","매년 5월 31일까지","결정·공시일부터 30일 이내, 시장·군수·구청장"],["표준주택가격","국토교통부장관","1월 1일","-","공시일부터 30일 이내, 국토교통부장관"],["개별주택가격","시장·군수·구청장","1월 1일","매년 4월 30일까지","결정·공시일부터 30일 이내, 시장·군수·구청장"],["공동주택가격","국토교통부장관","1월 1일","매년 4월 30일까지","공시일부터 30일 이내, 국토교통부장관"]]},{"종류":"비교","제목":"주택가격 공시의 효력과 예외","왼쪽":{"이름":"표준주택가격·개별주택가격","항목":["표준주택가격은 개별주택가격을 산정하는 기준이 된다","개별주택가격은 주택시장 가격정보를 제공하고 과세 등 가격 산정의 기준으로 활용될 수 있다","표준주택으로 선정된 단독주택은 개별주택가격을 공시하지 않을 수 있고 표준주택가격을 개별주택가격으로 본다"]},"오른쪽":{"이름":"공동주택가격","항목":["표준·개별 구분 없이 국토교통부장관이 바로 공시한다","주택시장 가격정보를 제공하고 과세 등 가격 산정의 기준으로 활용될 수 있다","공시기준일 이후 분할·합병·신축 등이 있으면 국토교통부장관이 대통령령으로 정하는 날을 기준으로 결정·공시한다"]}}],"함정":"개별주택가격은 시장·군수·구청장이 결정하지만 공동주택가격은 국토교통부장관이 공시한다. 개별주택가격의 사후 공시를 공동주택에 그대로 옮겨 쓴 보기가 정답이다."},"35회-1차-059":{"한줄":"지역권은 계속되고 표현된 것에 한하여 시효취득할 수 있다.","근거":[{"법령":"민법","조문":"제294조","원문":"지역권은 계속되고 표현된 것에 한하여 제245조의 규정을 준용한다."},{"법령":"민법","조문":"제292조","원문":"①지역권은 요역지소유권에 부종하여 이전하며 또는 요역지에 대한 소유권이외의 권리의 목적이 된다. 그러나 다른 약정이 있는 때에는 그 약정에 의한다.\n②지역권은 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다."},{"법령":"민법","조문":"제293조제1항","원문":"①토지공유자의 1인은 지분에 관하여 그 토지를 위한 지역권 또는 그 토지가 부담한 지역권을 소멸하게 하지 못한다."},{"법령":"민법","조문":"제295조제1항","원문":"①공유자의 1인이 지역권을 취득한 때에는 다른 공유자도 이를 취득한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지역권은 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다(제292조제2항)."},{"번호":2,"판정":"틀림","설명":"표현되지 않은 지역권은 시효취득할 수 없다. 계속되고 표현된 것에 한한다(제294조)."},{"번호":3,"판정":"옳음","설명":"지역권은 요역지소유권에 부종하여 이전한다(제292조제1항)."},{"번호":4,"판정":"옳음","설명":"공유자 1인은 지분에 관한 지역권을 소멸하게 하지 못한다(제293조제1항)."},{"번호":5,"판정":"옳음","설명":"공유자 1인이 취득하면 다른 공유자도 취득한다(제295조제1항)."}],"개념":[{"종류":"표","제목":"지역권의 성질","머리":["성질","내용","조문"],"행":[["부종성","요역지 소유권과 함께 이전, 요역지와 분리하여 양도 불가","제292조"],["불가분성(소멸)","공유자 1인이 지분에 관한 지역권을 소멸시키지 못함","제293조제1항"],["불가분성(취득)","공유자 1인이 취득하면 다른 공유자도 취득","제295조제1항"],["불가분성(시효)","시효 중단·정지는 다른 공유자를 위해서도 효력(소멸시효), 취득기간 중단은 모든 공유자에 대한 사유일 때만","제295조제2항, 제296조"],["시효취득","계속되고 표현된 것에 한함","제294조"]]},{"종류":"비교","제목":"지상권과 지역권","왼쪽":{"이름":"지상권","항목":["타인 토지에서 건물·수목 등을 소유하기 위해 그 토지를 사용","토지 점유를 수반","양도·임대 가능","지료 약정은 요소 아님"]},"오른쪽":{"이름":"지역권","항목":["자기 토지의 편익을 위해 타인 토지를 이용","승역지를 점유하지 않고 이용","요역지와 분리하여 양도 불가","표현되지 않은 것은 시효취득 불가"]}}],"함정":"선지 ②는 시효취득 요건인 계속과 표현 가운데 표현을 빼고 읽게 한다. 표현되지 않은 지역권은 시효취득할 수 없다."},"35회-1차-060":{"한줄":"전세권이 소멸하면 전세금 반환과 목적물 인도·말소등기 서류 교부가 동시이행이므로, 반환이 서류 교부보다 먼저 이루어져야 하는 것은 아니다.","근거":[{"법령":"민법","조문":"제317조","원문":"전세권이 소멸한 때에는 전세권설정자는 전세권자로부터 그 목적물의 인도 및 전세권설정등기의 말소등기에 필요한 서류의 교부를 받는 동시에 전세금을 반환하여야 한다."},{"법령":"민법","조문":"제308조","원문":"전세권의 목적물을 전전세 또는 임대한 경우에는 전세권자는 전전세 또는 임대하지 아니하였으면 면할 수 있는 불가항력으로 인한 손해에 대하여 그 책임을 부담한다."},{"법령":"민법","조문":"제309조","원문":"전세권자는 목적물의 현상을 유지하고 그 통상의 관리에 속한 수선을 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"전세금 반환과 목적물 인도 및 말소등기 서류 교부는 동시이행 관계다(제317조). 서류 교부가 반환보다 뒤에 와도 되고, 반환이 먼저 이루어져야 하는 것도 아니다."},{"번호":2,"판정":"옳음","설명":"통상의 관리에 속한 수선은 전세권자가 할 의무다(제309조). 그래서 통상 수선비는 상환 청구 대상이 아니다. 유익비는 가액 증가가 남아 있을 때만 소유자 선택에 따라 청구한다(제310조제1항)."},{"번호":3,"판정":"옳음","설명":"전전세·임대한 경우 전세권자는 전전세하지 않았으면 면했을 불가항력 손해까지 책임진다(제308조)."},{"번호":4,"판정":"옳음","설명":"대지와 건물이 같은 소유자일 때 건물에만 전세권을 설정하면 대지소유권의 특별승계인은 전세권설정자에 대하여 지상권을 설정한 것으로 본다. 지료는 당사자 청구로 법원이 정한다(제305조제1항)."},{"번호":5,"판정":"옳음","설명":"타인 토지 위 건물에 전세권을 설정하면 전세권의 효력이 건물 소유를 위한 지상권·임차권에 미치고, 설정자는 전세권자 동의 없이 그 지상권·임차권을 소멸시키는 행위를 하지 못한다(제304조)."}],"개념":[{"종류":"표","제목":"전세권의 존속기간·갱신·소멸통고","머리":["구분","내용","조문"],"행":[["최장 존속기간","10년(약정이 더 길면 10년으로 단축)","제312조제1항"],["건물 전세권의 최단 기간","1년(1년 미만으로 정하면 1년)","제312조제2항"],["갱신","갱신 가능, 갱신한 날부터 10년을 넘지 못함","제312조제3항"],["건물 전세권의 법정갱신","만료 전 6월~1월 사이에 설정자가 갱신거절·조건변경 통지를 하지 않으면 종전과 같은 조건으로 다시 설정한 것으로 봄, 존속기간은 정함 없음","제312조제4항"],["기간 약정이 없는 경우","각 당사자가 언제든 소멸 통고, 상대방이 통고를 받은 날부터 6월이 지나면 소멸","제313조"],["목적물","농경지는 전세권의 목적이 될 수 없음","제303조제2항"]]},{"종류":"흐름","제목":"전세권 소멸 후 정산 절차","단계":[{"이름":"소멸","설명":"존속기간 만료·소멸통고·소멸청구 등. 전세권자는 목적물을 원상회복하고 부속시킨 물건을 수거할 수 있다(제316조제1항)"},{"이름":"부속물 정리","설명":"설정자가 매수를 청구하면 전세권자는 정당한 이유 없이 거절하지 못한다. 설정자 동의를 얻어 부속시킨 물건은 전세권자가 매수를 청구할 수 있다(제316조)"},{"이름":"동시이행","설명":"목적물 인도·말소등기 서류 교부와 전세금 반환이 동시이행(제317조)"},{"이름":"반환 지체","설명":"설정자가 전세금 반환을 지체하면 전세권자는 민사집행법에 따라 목적물 경매를 청구할 수 있다(제318조)"},{"이름":"손해 충당","설명":"전세권자 책임 있는 사유로 목적물이 멸실된 때 설정자는 전세금에서 손해를 충당하고 잉여를 반환, 부족하면 다시 청구(제315조제2항)"}]}],"함정":"4번과 5번을 틀린 문장으로 고르기 쉽다. 제304조·제305조는 건물 전세권의 특칙이라 낯설 뿐 두 문장 모두 조문 그대로 옳다. 1번은 동시이행(제317조)을 반환 선행으로 바꾼 문장이다. 정답률 24%."},"35회-1차-079":{"한줄":"임차인이 만료 전에 갱신거절을 통지하여 임대인에게 도달했으므로 묵시적 갱신이 이루어지지 않고 임대차는 약정 기간 만료일인 2024. 5. 23.에 끝난다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제10조제4항","원문":"임대인이 제1항의 기간 이내에 임차인에게 갱신 거절의 통지 또는 조건 변경의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 이 경우에 임대차의 존속기간은 1년으로 본다."},{"법령":"상가건물 임대차보호법","조문":"제10조제5항","원문":"제4항의 경우 임차인은 언제든지 임대인에게 계약해지의 통고를 할 수 있고, 임대인이 통고를 받은 날부터 3개월이 지나면 효력이 발생한다."}],"선지":[{"번호":1,"판정":"-","설명":"갱신거절 통지가 도달한 날은 2024. 5. 10.이지만 통지가 도달해도 임대차가 그날 끝나는 것은 아니다. 약정 기간이 남아 있다."},{"번호":2,"판정":"-","설명":"정답. 임차인이 스스로 갱신하지 않겠다는 통지를 했고 그 통지가 임대인에게 도달했으므로 묵시적 갱신이 되지 않아 약정 기간 만료일에 끝난다."},{"번호":3,"판정":"-","설명":"만료일에 3개월을 더한 날이다. 묵시적으로 갱신된 임대차에서 임차인이 해지를 통고하는 경우의 3개월(제10조제5항)을 잘못 적용한 값이다."},{"번호":4,"판정":"-","설명":"만료일에 6개월을 더한 날로 근거 조문이 없다."},{"번호":5,"판정":"-","설명":"묵시적으로 갱신된 경우의 존속기간 1년(제10조제4항)을 적용한 날이다. 임차인이 갱신거절을 통지했으므로 갱신되지 않는다."}],"개념":[{"종류":"표","제목":"상가건물 임대차보호법 시행령의 금액 기준","머리":["지역","적용 보증금 상한(제2조)","우선변제 임차인 범위(제6조)","보증금 중 일정액 한도(제7조제1항)"],"행":[["서울특별시","9억원","6천500만원","2천200만원"],["과밀억제권역(서울 제외)","6억9천만원 (부산광역시 포함)","5천500만원","1천900만원"],["광역시 등(과밀억제권역·군지역 제외)","5억4천만원 (세종, 파주, 화성, 안산, 용인, 김포, 광주 포함)","3천8백만원 (안산, 용인, 김포, 광주 포함)","1천300만원"],["그 밖의 지역","3억7천만원","3천만원","1천만원"]]},{"종류":"표","제목":"환산보증금과 권리금","머리":["구분","내용","조문"],"행":[["환산보증금","보증금 + 월차임 × 100(1분의 100)","법 제2조제2항, 시행령 제2조제3항"],["보증금액 초과 임대차에도 적용","대항력(제3조), 갱신요구(제10조제1항·제2항·제3항 본문), 권리금 규정(제10조의2~제10조의9) 등","법 제2조제3항"],["권리금 회수기회 보호 기간","임대차기간이 끝나기 6개월 전부터 임대차 종료 시까지","법 제10조의4제1항"],["권리금 손해배상 상한","신규임차인이 지급하기로 한 권리금과 임대차 종료 당시 권리금 중 낮은 금액","법 제10조의4제3항"],["손해배상청구권 시효","임대차가 종료한 날부터 3년","법 제10조의4제4항"],["차임연체 해지","3기의 차임액","법 제10조의8"]]}],"함정":"1번은 통지 도달일을 종료일로 읽은 오답이고, 5번은 묵시적 갱신 효과(1년)를 적용한 오답이다. 임차인이 통지를 하면 임대인이 통지를 하지 않았다는 이유로 갱신되지 않는다. 정답률 38%."},"35회-1차-078":{"한줄":"수탁자의 처분으로 丙이 소유권을 취득하면 甲은 소유권을 잃게 되고, 이는 乙의 불법행위에 해당해 손해배상을 청구할 수 있다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조","원문":"① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"대법원 판례(양자간 명의신탁과 수탁자의 처분)","요지":"수탁자가 신탁부동산을 제3자에게 처분하면 제3자는 소유권을 취득하고(제4조제3항), 신탁자는 소유권을 잃는다. 신탁자는 수탁자에게 불법행위로 인한 손해배상을 청구할 수 있다. 신탁자가 해지를 원인으로 이전등기를 청구하는 것은 허용되지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수탁자 乙의 처분으로 甲이 소유권을 잃었으므로 乙은 甲에게 불법행위 책임을 진다(판례)."},{"번호":2,"판정":"틀림","설명":"명의신탁약정의 무효는 乙과 丙 사이의 매매에 영향을 주지 않는다. 매매계약은 유효하고 丙은 소유권을 취득한다(제4조제3항)."},{"번호":3,"판정":"틀림","설명":"丙은 제3자로서 소유권을 확정적으로 취득하므로 甲은 말소를 청구할 수 없다(제4조제3항)."},{"번호":4,"판정":"틀림","설명":"명의신탁약정이 무효이므로 약정 해지를 원인으로 한 이전등기 청구는 인정되지 않는다."},{"번호":5,"판정":"틀림","설명":"丙 앞의 등기가 유효하여 甲은 이미 소유권을 잃었다. 乙이 다시 취득해도 甲의 소유권이 되살아나지 않으므로 소유권에 기한 이전등기 청구를 할 수 없다."}],"개념":[{"종류":"흐름","제목":"양자간 명의신탁 후 수탁자의 처분","단계":[{"이름":"명의신탁약정","설명":"甲이 자기 소유 X를 乙 명의로 등기. 약정과 등기 모두 무효(제4조제1항·제2항)"},{"이름":"처분 전","설명":"소유권은 甲에게 있고, 甲은 말소 또는 진정명의회복 이전등기를 청구 가능. 해지를 원인으로 한 이전등기는 불가"},{"이름":"수탁자의 처분","설명":"乙이 丙에게 매도하여 등기. 매매는 유효, 丙은 제3자로서 소유권 취득(제4조제3항)"},{"이름":"신탁자의 지위","설명":"甲은 소유권 상실. 乙에게 불법행위 손해배상 청구 가능, 丙에게 말소 청구 불가"},{"이름":"재취득","설명":"乙이 丙에게서 다시 취득해도 甲은 소유권에 기한 이전등기 청구 불가"}]},{"종류":"표","제목":"양자간 명의신탁에서 신탁자의 청구 가부","머리":["청구","가부","이유"],"행":[["수탁자 상대 소유권에 기한 말소(진정명의회복 이전등기)","가능","약정·등기 무효, 소유권은 신탁자에게 있음"],["수탁자 상대 명의신탁 해지를 원인으로 한 이전등기","불가","약정이 무효이므로 해지권도 없음"],["처분 후 제3자 상대 말소","불가","무효를 제3자에게 대항하지 못함(제4조제3항)"],["처분 후 수탁자 상대 손해배상","가능","수탁자의 처분으로 소유권 상실, 불법행위"],["수탁자의 점유","타주점유","소유권이 없음을 알고 있음"]]}],"함정":"정답률이 10%로 가장 낮다. 2번·3번·4번·5번은 명의신탁 무효 법리를 확장 적용한 오답이다. 매매는 유효하고, 丙은 소유권을 취득하며, 甲의 구제는 손해배상이다."},"35회-2차-003":{"한줄":"휴업기간 변경신고서에는 중개사무소등록증을 첨부하지 않는다. 등록증 첨부 대상은 3개월 초과 휴업과 폐업 신고뿐이다.","근거":[{"법령":"공인중개사법 시행령","조문":"제18조제1항","원문":"개업공인중개사는 법 제21조제1항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부령으로 정하는 신고서에 중개사무소등록증을 첨부(제1호 및 제2호의 경우만 해당한다)하여 등록관청에 미리 신고(제3호 및 제4호에 해당하여 신고하는 경우에는 전자문서에 의한 신고를 포함한다)해야 한다."},{"법령":"공인중개사법 시행령","조문":"제18조제5항","원문":"제1항 또는 제2항에 따른 중개사무소재개신고를 받은 등록관청은 반납받은 중개사무소등록증 또는 신고확인서를 즉시 반환해야 한다."},{"법령":"공인중개사법 시행령","조문":"제18조제4항","원문":"관할 세무서장이 「부가가치세법 시행령」 제13조제5항에 따라 제1항의 신고서를 받아 해당 등록관청에 송부한 경우에는 제1항의 신고서가 제출된 것으로 본다."},{"법령":"공인중개사법","조문":"제38조제2항제5호","원문":"제21조제2항의 규정을 위반하여 계속하여 6개월을 초과하여 휴업한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"분사무소의 3개월 초과 휴업은 분사무소설치신고확인서를 첨부해 분사무소별로 신고한다(영 제18조제2항)."},{"번호":2,"판정":"틀림","설명":"변경신고는 영 제18조제1항제4호이고, 등록증 첨부는 제1호ㆍ제2호만 해당한다."},{"번호":3,"판정":"옳음","설명":"세무서장이 휴업신고서를 받아 등록관청에 송부하면 제출된 것으로 본다(영 제18조제4항)."},{"번호":4,"판정":"옳음","설명":"부득이한 사유 없이 계속해서 6개월을 초과해 휴업하면 등록관청이 개설등록을 취소할 수 있다(법 제38조제2항제5호). 취소 여부는 재량이다."},{"번호":5,"판정":"옳음","설명":"재개신고를 받은 등록관청은 반납받은 등록증을 즉시 반환한다(영 제18조제5항)."}],"개념":[{"종류":"흐름","제목":"휴업 신고에서 재개까지","단계":[{"이름":"휴업 신고","설명":"3개월을 초과해 휴업하려면 미리 신고한다. 신고서에 중개사무소등록증을 첨부한다. 분사무소는 신고확인서를 첨부한다(영 제18조제1항제1호ㆍ제2항)."},{"이름":"휴업기간 변경","설명":"기간을 바꾸려면 미리 변경신고를 한다. 등록증은 첨부하지 않는다(영 제18조제1항제4호)."},{"이름":"휴업 상한","설명":"휴업은 6개월을 넘길 수 없다. 질병 요양, 징집 입영, 취학, 임신ㆍ출산 등 부득이한 사유는 예외다(법 제21조제2항, 영 제18조제6항)."},{"이름":"재개 신고","설명":"3개월을 초과해 휴업한 중개업을 다시 하려면 미리 신고한다(영 제18조제1항제3호)."},{"이름":"등록증 반환","설명":"재개신고를 받은 등록관청은 반납받은 등록증을 즉시 반환한다(영 제18조제5항)."},{"이름":"위반 시 처분","설명":"부득이한 사유 없이 계속하여 6개월을 초과해 휴업하면 개설등록 취소 사유다(법 제38조제2항제5호). 신고를 하지 않으면 100만원 이하의 과태료다(법 제51조제3항제4호)."}]},{"종류":"표","제목":"부동산중개업 휴업(폐업ㆍ재개ㆍ휴업기간변경)신고서의 신고사항 기재(별지 제13호서식)","머리":["신고 종류","기재하는 내용"],"행":[["휴업","휴업기간(시작일~종료일, 일수)"],["폐업","폐업일"],["재개","재개일"],["휴업기간 변경","원래 휴업기간과 변경 휴업기간"],["공통","신고인, 개업공인중개사 종별(법인ㆍ공인중개사ㆍ부칙 제6조제2항 개업공인중개사), 중개사무소 명칭ㆍ등록번호ㆍ소재지"]]}],"함정":"'휴업은 모두 등록증을 첨부한다'로 일반화하면 변경신고에서 걸린다. 영 제18조제1항은 제1호(3개월 초과 휴업)와 제2호(폐업)에만 첨부를 요구한다."},"35회-2차-010":{"한줄":"전속중개계약의 유효기간은 3개월이 원칙이고 당사자가 달리 약정하면 그 약정에 따른다. 3개월 미만으로 정해도 약정한 기간이 유효기간이다.","근거":[{"법령":"공인중개사법 시행령","조문":"제20조제1항","원문":"법 제23조제1항의 규정에 따른 전속중개계약의 유효기간은 3월로 한다. 다만, 당사자간에 다른 약정이 있는 경우에는 그 약정에 따른다."},{"법령":"공인중개사법 시행령","조문":"제20조제2항제5호","원문":"소유권ㆍ전세권ㆍ저당권ㆍ지상권 및 임차권 등 중개대상물의 권리관계에 관한 사항. 다만, 각 권리자의 주소ㆍ성명 등 인적 사항에 관한 정보는 공개하여서는 아니 된다."},{"법령":"공인중개사법 시행령","조문":"제20조제2항제7호","원문":"중개대상물의 거래예정금액 및 공시지가. 다만, 임대차의 경우에는 공시지가를 공개하지 아니할 수 있다."},{"법령":"공인중개사법","조문":"제22조제2호","원문":"거래예정가격"}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제22조는 중개의뢰인이 계약서 작성을 요청할 수 있다고만 정한다. 일반중개계약은 서면 없이도 체결된다."},{"번호":2,"판정":"틀림","설명":"3개월 미만으로 약정하면 그 약정이 유효기간이다(영 제20조제1항 단서). 3개월로 늘려 보정하지 않는다."},{"번호":3,"판정":"옳음","설명":"권리자의 주소ㆍ성명 등 인적 사항은 공개하지 않는다(영 제20조제2항제5호 단서)."},{"번호":4,"판정":"옳음","설명":"일반중개계약서 기재사항에 거래예정가격이 있다(법 제22조제2호)."},{"번호":5,"판정":"옳음","설명":"임대차의 경우 공시지가는 공개하지 않을 수 있다(영 제20조제2항제7호 단서). 비공개 요청 여부와 관계가 없다."}],"개념":[{"종류":"비교","제목":"일반중개계약과 전속중개계약","왼쪽":{"이름":"일반중개계약(법 제22조)","항목":["다른 개업공인중개사에게도 중개를 의뢰할 수 있음","서면 작성은 중개의뢰인의 요청이 있을 때, 표준서식은 별지 제14호서식(영 제19조)","기재사항: 중개대상물의 위치ㆍ규모, 거래예정가격, 중개보수, 그 밖의 준수사항","유효기간 3개월 원칙, 합의로 달리 정함(서식)","정보공개 의무 없음"]},"오른쪽":{"이름":"전속중개계약(법 제23조)","항목":["특정 개업공인중개사에 한정해 중개를 의뢰","국토교통부령이 정한 계약서(별지 제15호서식)에 의해야 하며 3년 보존(시행규칙 제14조제2항)","유효기간 3개월 원칙, 약정이 있으면 약정에 따름(영 제20조제1항)","체결 시 부동산거래정보망 또는 일간신문에 정보 공개, 의뢰인이 비공개를 요청하면 공개 금지(법 제23조제3항)","서식상 공개는 체결 후 7일 이내, 처리상황은 2주일에 1회 이상 문서 통지"]}},{"종류":"표","제목":"전속중개계약 공개 정보의 범위(영 제20조제2항)","머리":["공개 정보","공개 여부와 예외"],"행":[["중개대상물의 종류ㆍ소재지ㆍ지목ㆍ면적ㆍ건축물 용도ㆍ구조ㆍ건축연도","공개"],["벽면 및 도배의 상태","공개"],["수도ㆍ전기ㆍ가스ㆍ소방ㆍ열공급ㆍ승강기 설비, 오수ㆍ폐수ㆍ쓰레기 처리시설 상태","공개"],["도로ㆍ대중교통 연계성, 시장ㆍ학교 근접성, 입지ㆍ환경 조건","공개"],["소유권ㆍ전세권ㆍ저당권ㆍ지상권ㆍ임차권 등 권리관계","공개하되 권리자의 주소ㆍ성명 등 인적 사항은 공개 금지"],["공법상 이용제한 및 거래규제","공개"],["거래예정금액 및 공시지가","공개하되 임대차는 공시지가를 공개하지 않을 수 있음"]]}],"함정":"'3개월 미만으로 정하면 3개월로 본다'는 보정 규정은 없다. 영 제20조제1항 단서가 약정을 우선한다."},"35회-2차-025":{"한줄":"해제등 신고는 거래당사자가 공동으로 하는 것이 원칙이다. 단독 신고는 일방이 신고를 거부하는 경우에만 할 수 있다(법 제3조의2제1항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조의2 제1항 제2항","원문":"① 거래당사자는 제3조에 따라 신고한 후 해당 거래계약이 해제, 무효 또는 취소(이하 \"해제등\"이라 한다)된 경우 해제등이 확정된 날부터 30일 이내에 해당 신고관청에 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 신고를 거부하는 경우에는 국토교통부령으로 정하는 바에 따라 단독으로 신고할 수 있다.\n② 개업공인중개사가 제3조제3항에 따라 신고를 한 경우에는 제1항에도 불구하고 개업공인중개사가 같은 항에 따른 신고(공동으로 중개를 한 경우에는 해당 개업공인중개사가 공동으로 신고하는 것을 말한다)를 할 수 있다. 다만, 개업공인중개사 중 일방이 신고를 거부한 경우에는 제1항 단서를 준용한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제3조 제1항","원문":"① 거래당사자 또는 개업공인중개사는 부동산 거래계약 신고 내용 중 다음 각 호의 어느 하나에 해당하는 사항이 잘못 기재된 경우에는 신고관청에 신고 내용의 정정을 신청할 수 있다.\n1. 거래당사자의 주소ㆍ전화번호 또는 휴대전화번호\n2. 거래 지분 비율\n3. 개업공인중개사의 전화번호ㆍ상호 또는 사무소 소재지\n4. 거래대상 건축물의 종류\n5. 거래대상 부동산등(부동산을 취득할 수 있는 권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다. 이하 같다)의 지목, 면적, 거래 지분 및 대지권비율"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조 제6항","원문":"⑥ 부동산등의 매수인은 신고인이 제5항에 따른 신고필증을 발급받은 때에 「부동산등기 특별조치법」 제3조제1항에 따른 검인을 받은 것으로 본다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"별표 1 제2호 나목·제3호","원문":"2. 법인이 주택의 거래계약을 체결하는 경우 / 나. 주택 취득 목적 및 취득 자금 등에 관한 다음의 사항(법인이 주택의 매수자인 경우만 해당한다) 1) 거래대상인 주택의 취득목적 2) 거래대상 주택의 취득에 필요한 자금의 조달계획 및 지급방식 3) 임대 등 거래대상 주택의 이용계획\n3. 법인 외의 자가 실제 거래가격이 6억원 이상인 주택을 매수하거나 투기과열지구 또는 조정대상지역에 소재하는 주택을 매수하는 경우(매수인 중 국가등이 포함되어 있는 경우는 제외한다) / 가. 거래대상 주택의 취득에 필요한 자금의 조달계획 및 지급방식 나. 거래대상 주택에 매수자 본인이 입주할지 여부, 입주 예정 시기 등 거래대상 주택의 이용계획"}],"선지":[{"번호":1,"판정":"옳음","설명":"거래 지분 비율이 잘못 기재되면 거래당사자 또는 개업공인중개사가 정정을 신청할 수 있다(시행규칙 제3조제1항제2호)."},{"번호":2,"판정":"옳음","설명":"법인 외의 자가 실제 거래가격 6억원 이상 주택을 사면 투기과열지구가 아니어도 자금조달계획과 입주 여부·시기 등 이용계획을 신고한다(시행령 별표 1 제3호)."},{"번호":3,"판정":"옳음","설명":"법인이 주택의 매수자이면 취득목적, 자금조달계획·지급방식, 임대 등 이용계획을 신고한다(시행령 별표 1 제2호 나목)."},{"번호":4,"판정":"옳음","설명":"신고인이 신고필증을 발급받은 때에 매수인이 검인을 받은 것으로 본다(법 제3조제6항). 신고서를 낸 때가 아니다."},{"번호":5,"판정":"틀림","설명":"해제등 신고는 거래당사자가 해제등이 확정된 날부터 30일 이내에 공동으로 한다. 개업공인중개사가 거래를 신고했다면 그 개업공인중개사가 해제등 신고를 할 수도 있다. 단독 신고는 일방이 거부하는 경우다(법 제3조의2제1항·제2항)."}],"개념":[{"종류":"표","제목":"신고 후 정정·변경·해제 (시행규칙 제3조, 법 제3조의2)","머리":["구분","대상","방법"],"행":[["정정 신청","거래당사자 주소·전화번호, 거래 지분 비율, 개업공인중개사의 전화번호·상호·소재지, 건축물 종류, 지목·면적·지분·대지권비율","신고필증에 정정 사항을 표시하고 서명·날인. 주소·전화번호는 당사자 일방이 단독으로 가능"],["변경 신고","거래 지분 비율·지분, 면적, 계약 조건·기한, 거래가격, 중도금·잔금과 지급일, 일부 매수인·일부 부동산 제외 등","부동산등기 신청 전에 신고"],["해제등 신고","신고한 계약이 해제·무효·취소된 경우","확정일부터 30일 이내 공동 신고. 일방 거부 시 단독. 개업공인중개사가 신고했으면 개업공인중개사 신고 가능"]]},{"종류":"표","제목":"주택 거래에서 추가로 신고하는 사항 (시행령 별표 1)","머리":["거래","추가 신고사항","제외"],"행":[["법인이 주택을 거래","법인 등기 현황, 상대방과의 임원 관계","국가등이 당사자이거나 공급계약·분양권 매매"],["법인이 주택을 매수","취득목적, 자금조달계획·지급방식, 임대 등 이용계획","-"],["법인 외의 자가 6억원 이상 주택을 매수, 또는 투기과열지구·조정대상지역 주택 매수","자금조달계획·지급방식, 본인 입주 여부·입주 예정 시기","매수인 중 국가등이 포함된 경우"],["토지거래허가를 받아 허가구역 주택을 매수","자금조달계획(증빙 첨부), 입주 여부·이용계획","-"]]}],"함정":"6억원 이상이면 투기과열지구 밖의 주택도 이용계획 신고 대상이다. 검인은 신고필증을 발급받은 때에 받은 것으로 본다. 해제등 신고의 단독 신고는 일방이 거부할 때만 가능하다."},"35회-2차-036":{"한줄":"명의신탁약정과 그에 따른 등기는 무효이지만 그 무효는 제3자에게 대항하지 못한다. 丁은 선의·악의를 가리지 않고 보호되는 제3자이므로 甲도 임대차의 무효를 주장할 수 없다(부동산 실권리자명의 등기에 관한 법률 제4조제3항).","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조 제1항 제2항 제3항","원문":"① 명의신탁약정은 무효로 한다.\n② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다.\n③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"이론":"3자간 등기명의신탁의 법률관계 (판례)","내용":"신탁자 甲이 매도인 乙과 매매계약을 맺고 등기만 수탁자 丙 명의로 한 경우 명의신탁약정과 丙 명의 등기는 무효다. 소유권은 매도인 乙에게 남고, 매매계약은 유효하므로 甲은 乙에게 이전등기를 청구할 수 있고 乙은 丙에게 말소 또는 진정명의회복을 위한 이전등기를 청구할 수 있다. 수탁자 丙으로부터 임차한 丁은 제4조제3항의 제3자로서 명의신탁 사실을 알았더라도 보호된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"명의신탁약정에 따른 등기로 이루어진 물권변동은 무효다(제4조제2항). 매도인이 명의신탁 사실을 알았는지와 관계없이 3자간 등기명의신탁에서 丙은 소유권을 취득하지 못한다."},{"번호":2,"판정":"옳음","설명":"소유권은 乙에게 남아 있으므로 乙은 丙을 상대로 진정명의 회복을 위한 소유권이전등기를 청구할 수 있다."},{"번호":3,"판정":"옳음","설명":"甲과 乙 사이의 매매계약은 유효하다. 甲은 매매계약에 기한 이전등기청구권을 乙에게 행사할 수 있다."},{"번호":4,"판정":"옳음","설명":"丁은 제4조제3항의 제3자에 해당한다. 명의신탁을 알고 있었더라도 임차권으로 甲 또는 乙에게 대항할 수 있다."},{"번호":5,"판정":"틀림","설명":"丙이 임대차의 무효를 주장할 수 없는 것은 맞다. 그러나 명의신탁의 무효는 제3자인 丁에게 대항하지 못하므로 甲도 임대차계약의 무효를 주장할 수 없다."}],"개념":[{"종류":"표","제목":"명의신탁 유형별 효력 (부동산 실권리자명의 등기에 관한 법률 제4조)","머리":["유형","명의신탁약정","수탁자 명의 등기·물권변동","소유권·청구권"],"행":[["양자간 등기명의신탁 (신탁자 소유 부동산을 수탁자 명의로 등기)","무효","무효","신탁자가 소유권 유지, 수탁자 명의 등기는 말소 또는 진정명의회복 청구 대상"],["3자간 등기명의신탁 (신탁자가 매수하고 등기만 수탁자 명의)","무효","무효","매도인이 소유권 유지. 신탁자는 매도인에게 이전등기 청구, 매도인은 수탁자에게 말소 청구"],["계약명의신탁 (수탁자가 매매 당사자), 매도인이 약정을 모른 경우","무효","유효 (제4조제2항 단서)","수탁자가 소유권 취득"],["계약명의신탁, 매도인이 약정을 안 경우","무효","무효","매도인이 소유권 유지"],["공통","-","-","무효는 제3자에게 대항하지 못한다 (제4조제3항)"]]},{"종류":"흐름","제목":"사례의 법률관계 순서","단계":[{"이름":"명의신탁약정","설명":"甲이 매수하면서 丙 명의로 등기하기로 하고 丙이 동의. 약정은 무효 (제4조제1항)."},{"이름":"丙 명의 등기","설명":"물권변동이 무효이므로 소유권은 乙에게 남는다 (제4조제2항)."},{"이름":"甲·乙 관계","설명":"매매계약은 유효. 甲은 乙에게 이전등기를 청구할 수 있다."},{"이름":"乙·丙 관계","설명":"乙은 丙에게 진정명의 회복을 위한 이전등기(또는 말소)를 청구할 수 있다."},{"이름":"丙·丁 관계","설명":"丙이 맺은 임대차에서 丁은 제3자. 악의여도 보호되어 甲·乙에게 임차권을 주장할 수 있다 (제4조제3항)."}]}],"함정":"丙 명의 등기가 무효여도 丁의 임차권은 무효가 되지 않는다. 제4조제3항의 제3자는 선의·악의를 가리지 않는다. 명의신탁자는 5년 이하 징역 또는 2억원 이하 벌금(제7조제1항), 명의수탁자는 3년 이하 징역 또는 1억원 이하 벌금(제7조제2항)이고, 신탁자에게는 부동산 가액 100분의 30 범위의 과징금이 붙는다(제5조)."},"35회-2차-044":{"한줄":"국토교통부장관이 입안·결정한 도시·군관리계획을 시·도지사가 변경하려면 미리 국토교통부장관과 협의한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제30조제2항","원문":"② 시ㆍ도지사는 제24조제5항에 따라 국토교통부장관이 입안하여 결정한 도시ㆍ군관리계획을 변경하거나 그 밖에 대통령령으로 정하는 중요한 사항에 관한 도시ㆍ군관리계획을 결정하려면 미리 국토교통부장관과 협의하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제31조제1항","원문":"① 도시ㆍ군관리계획 결정의 효력은 제32조제4항에 따라 지형도면을 고시한 날부터 발생한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제31조제2항","원문":"② … 다만, 시가화조정구역이나 수산자원보호구역의 지정에 관한 도시ㆍ군관리계획 결정이 있는 경우에는 대통령령으로 정하는 바에 따라 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수에게 신고하고 그 사업이나 공사를 계속할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제32조제3항","원문":"③ 국토교통부장관(제40조에 따른 수산자원보호구역의 경우 해양수산부장관을 말한다. 이하 이 조에서 같다)이나 도지사는 도시ㆍ군관리계획을 직접 입안한 경우에는 제1항과 제2항에도 불구하고 관계 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 의견을 들어 직접 지형도면을 작성할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제29조제1항","원문":"① … 다음 각 호의 도시ㆍ군관리계획은 시장 또는 군수가 직접 결정한다.\n  1. 시장 또는 군수가 입안한 지구단위계획구역의 지정ㆍ변경과 지구단위계획의 수립ㆍ변경에 관한 도시ㆍ군관리계획"}],"선지":[{"번호":1,"판정":"틀림","설명":"효력은 지형도면을 고시한 날부터 생긴다. 다음 날이 아니다(법 제31조제1항)."},{"번호":2,"판정":"틀림","설명":"시가화조정구역·수산자원보호구역 지정 결정 당시 이미 착수한 사업은 시장·군수 등에게 신고하고 계속한다. 이 두 구역에만 신고 의무가 붙는다(법 제31조제2항 단서)."},{"번호":3,"판정":"틀림","설명":"국토교통부장관이나 도지사가 직접 입안한 계획은 그 입안자가 관계 시장·군수의 의견을 들어 직접 지형도면을 작성할 수 있다(법 제32조제3항)."},{"번호":4,"판정":"틀림","설명":"시장·군수가 입안한 지구단위계획 관련 도시·군관리계획은 시장·군수가 직접 결정한다(법 제29조제1항제1호)."},{"번호":5,"판정":"옳음","설명":"국토교통부장관이 국가계획과 관련해 입안·결정한 계획을 시·도지사가 변경할 때는 사전 협의를 거친다(법 제30조제2항)."}],"개념":[{"종류":"표","제목":"도시·군관리계획의 결정권자","머리":["구분","결정권자","근거"],"행":[["일반 도시·군관리계획","시·도지사(직접 또는 시장·군수의 신청)","법 제29조제1항"],["인구 50만 이상 대도시","해당 대도시 시장","법 제29조제1항"],["시장·군수가 입안한 지구단위계획구역 지정·변경, 지구단위계획 수립·변경","시장 또는 군수","법 제29조제1항제1호"],["국토교통부장관이 입안한 계획","국토교통부장관","법 제29조제2항제1호"],["개발제한구역의 지정·변경","국토교통부장관","법 제29조제2항제2호"],["시가화조정구역(국가계획과 연계해 필요한 경우)","국토교통부장관","법 제29조제2항제3호, 제39조제1항 단서"],["수산자원보호구역","1제곱킬로미터 이상 공유수면은 해양수산부장관, 인접 토지·1제곱킬로미터 미만 공유수면은 시·도지사","법 제29조제2항제4호"]]},{"종류":"흐름","제목":"도시·군관리계획의 입안에서 효력 발생까지","단계":[{"이름":"입안","설명":"입안권자가 기초조사와 환경성 검토를 거쳐 계획도서·계획설명서를 만든다(법 제24조, 제25조, 제27조)."},{"이름":"의견 청취","설명":"주민과 지방의회의 의견을 듣는다(법 제28조)."},{"이름":"협의·심의","설명":"관계 행정기관과 협의한다. 협의 기관은 30일 이내에 의견을 낸다. 이어 도시계획위원회 심의를 거친다(법 제30조제1항·제3항)."},{"이름":"결정·고시","설명":"결정권자가 결정 내용을 고시하고 관계 서류를 열람하게 한다(법 제30조제6항)."},{"이름":"지형도면 고시","설명":"시장·군수가 만든 지형도면은 도지사가 승인한다. 이후 지형도면을 고시한다(법 제32조제2항·제4항)."},{"이름":"효력 발생","설명":"지형도면을 고시한 날부터 효력이 생긴다(법 제31조제1항)."}]}],"함정":"효력 발생을 결정 고시일이나 지형도면 고시 다음 날로 잡는 오답이 많다. 지형도면 고시일 당일부터다. 국토교통부장관 입안분의 지형도면을 시·도지사가 작성한다고 단정하는 선지도 흔하다."},"35회-2차-047":{"한줄":"개발행위허가를 받아 건축한 뒤 건축법상 사용승인을 받았다면 개발행위 준공검사는 받지 않는다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제62조제1항","원문":"① 제56조제1항제1호부터 제3호까지의 행위에 대한 개발행위허가를 받은 자는 그 개발행위를 마치면 국토교통부령으로 정하는 바에 따라 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 준공검사를 받아야 한다. 다만, 같은 항 제1호의 행위에 대하여 「건축법」 제22조에 따른 건축물의 사용승인을 받은 경우에는 그러하지 아니하다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제56조제1항","원문":"① … 다만, 도시ㆍ군계획사업(다른 법률에 따라 도시ㆍ군계획사업을 의제한 사업을 포함한다)에 의한 행위는 그러하지 아니하다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제52조제1항·제2항","원문":"① 법 제56조제2항 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하는 경우\"란 … 다음 각 호의 어느 하나에 해당하는 경우 …\n  2. 다음 각 목의 어느 하나에 해당하는 경우\n    가. 부지면적 또는 건축물 연면적을 5퍼센트 범위에서 축소[…]하는 경우\n② 개발행위허가를 받은 자는 제1항 각호의 1에 해당하는 경미한 사항을 변경한 때에는 지체없이 그 사실을 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수에게 통지하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제54조제1항","원문":"① 법 제57조제2항에서 \"대통령령으로 정하는 기간\"이란 15일(도시계획위원회의 심의를 거쳐야 하거나 관계 행정기관의 장과 협의를 하여야 하는 경우에는 심의 또는 협의기간을 제외한다)을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제63조제1항","원문":"① … 다만, 제3호부터 제5호까지에 해당하는 지역에 대해서는 중앙도시계획위원회나 지방도시계획위원회의 심의를 거치지 아니하고 한 차례만 2년 이내의 기간 동안 개발행위허가의 제한을 연장할 수 있다.\n  4. 지구단위계획구역으로 지정된 지역"}],"선지":[{"번호":1,"판정":"틀림","설명":"도시·군계획사업에 의한 행위는 개발행위허가를 받지 않는다. 도시·군계획사업의 인가 단계에서 이미 걸러지기 때문이다(법 제56조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"제56조제1항제1호의 건축에 대해 건축법 제22조의 사용승인을 받으면 준공검사를 따로 받지 않는다(법 제62조제1항 단서)."},{"번호":3,"판정":"틀림","설명":"건축물 연면적을 5퍼센트 범위에서 줄이는 것은 경미한 변경이다. 변경허가도 신고도 필요 없고, 변경한 뒤 지체 없이 통지만 한다(영 제52조제1항제2호가목, 제2항)."},{"번호":4,"판정":"틀림","설명":"처분 기간은 15일이다. 위원회 심의나 관계기관 협의에 걸린 기간은 이 15일에 넣지 않는다(영 제54조제1항)."},{"번호":5,"판정":"틀림","설명":"지구단위계획구역에 대한 허가 제한은 위원회 심의 없이 2년 이내에 한 번 연장할 수 있다(법 제63조제1항 단서)."}],"개념":[{"종류":"표","제목":"개발행위허가의 규모(토지 형질변경 면적, 영 제55조제1항)","머리":["용도지역","규모"],"행":[["주거지역·상업지역·자연녹지지역·생산녹지지역","1만 제곱미터 미만"],["공업지역","3만 제곱미터 미만"],["보전녹지지역","5천 제곱미터 미만"],["관리지역","3만 제곱미터 미만(조례로 달리 정할 수 있음)"],["농림지역","3만 제곱미터 미만(조례로 달리 정할 수 있음)"],["자연환경보전지역","5천 제곱미터 미만"]]},{"종류":"흐름","제목":"개발행위허가의 절차","단계":[{"이름":"신청","설명":"기반시설 설치, 위해 방지, 환경오염 방지, 경관·조경 계획서를 붙여 신청한다. 개발밀도관리구역에서는 기반시설 계획서가 빠진다(법 제57조제1항)."},{"이름":"심의·협의","설명":"대통령령이 정한 개발행위는 중앙·지방도시계획위원회 심의를 거친다(법 제59조)."},{"이름":"처분","설명":"15일 이내에 허가 또는 불허가한다. 위원회 심의와 관계기관 협의 기간은 제외한다(영 제54조제1항)."},{"이름":"조건·이행보증","설명":"허가에 조건을 붙이려면 신청인의 의견을 듣는다. 필요하면 이행보증금을 예치하게 한다(영 제54조제2항, 법 제60조제1항)."},{"이름":"준공검사","설명":"건축물 사용승인을 받은 건축은 준공검사를 받지 않는다(법 제62조제1항)."}]}],"함정":"경미한 변경을 신고 대상으로 외우기 쉽다. 5퍼센트 범위 축소는 허가·신고 모두 불필요하고 통지만 한다. 허가 제한 연장에서 중앙도시계획위원회 심의 여부는 제한 사유별로 다르다."},"35회-2차-054":{"한줄":"조합은 사업 전부를 환지 방식으로 시행하는 경우에만 시행자가 되므로 수용·사용 방식의 시행자가 될 수 없다.","근거":[{"법령":"도시개발법","조문":"제11조제1항","원문":"① 도시개발사업의 시행자(…)는 다음 각 호의 자 중에서 지정권자가 지정한다. 다만, 도시개발구역의 전부를 환지 방식으로 시행하는 경우에는 제5호의 토지 소유자나 제6호의 조합을 시행자로 지정한다.\n  1. 국가나 지방자치단체\n  2. 대통령령으로 정하는 공공기관\n  4. 「지방공기업법」에 따라 설립된 지방공사\n  5. 도시개발구역의 토지 소유자(… 제21조에 따른 수용 또는 사용 방식의 경우에는 도시개발구역의 국공유지를 제외한 토지면적의 3분의 2 이상을 소유한 자를 말한다)\n  6. 도시개발구역의 토지 소유자(…)가 도시개발을 위하여 설립한 조합(도시개발사업의 전부를 환지 방식으로 시행하는 경우에만 해당하며, 이하 \"조합\"이라 한다)"},{"법령":"도시개발법 시행령","조문":"제18조제1항","원문":"① 법 제11조제1항제2호에서 \"대통령령으로 정하는 공공기관\"이란 다음 각 호의 공공기관을 말한다.\n  1. 「한국토지주택공사법」에 따른 한국토지주택공사 …\n  6. 「한국철도공사법」에 따른 한국철도공사"}],"선지":[{"번호":1,"판정":"옳음","설명":"한국철도공사는 시행령이 정한 공공기관이므로 시행자가 될 수 있다(영 제18조제1항제6호, 법 제11조제1항제2호)."},{"번호":2,"판정":"옳음","설명":"지방자치단체는 시행자다(법 제11조제1항제1호)."},{"번호":3,"판정":"옳음","설명":"지방공사는 시행자다(법 제11조제1항제4호)."},{"번호":4,"판정":"옳음","설명":"수용·사용 방식에서는 국공유지를 제외한 토지면적의 3분의 2 이상을 소유한 토지 소유자가 시행자가 될 수 있다(법 제11조제1항제5호)."},{"번호":5,"판정":"틀림","설명":"조합은 사업 전부를 환지 방식으로 시행하는 경우에만 해당한다(법 제11조제1항제6호)."}],"개념":[{"종류":"표","제목":"시행방식별 시행자","머리":["시행방식","시행자가 될 수 있는 자","근거"],"행":[["수용·사용 방식","국가·지방자치단체, 공공기관(한국토지주택공사, 한국수자원공사, 한국농어촌공사, 한국관광공사, 한국철도공사, 한국공항공사 등), 정부출연기관, 지방공사, 국공유지 제외 토지면적의 3분의 2 이상을 소유한 토지 소유자, 과밀억제권역 이전 법인, 주택 등록업자, 건설업자, 부동산개발업자, 부동산투자회사, 이들이 출자한 법인","법 제11조제1항제1호~제5호·제7호~제11호, 영 제18조"],["전부 환지 방식","토지 소유자 또는 조합을 시행자로 지정한다","법 제11조제1항 단서"],["조합","도시개발사업의 전부를 환지 방식으로 시행하는 경우에만","법 제11조제1항제6호"],["지방자치단체등 지정","토지 소유자·조합이 지정을 신청하지 않거나 신청이 부당한 경우, 공공시설 사업과 병행할 필요가 있는 경우, 국공유지 제외 토지면적의 2분의 1 이상 소유자와 소유자 총수의 2분의 1 이상이 동의한 경우","법 제11조제2항"]]},{"종류":"표","제목":"시행자 관련 동의·기간 요건","머리":["항목","요건","근거"],"행":[["조합 설립 인가 신청","토지면적의 3분의 2 이상 소유자와 토지 소유자 총수의 2분의 1 이상 동의","법 제13조제3항"],["환지 방식 개발계획 수립","환지 방식 지역 토지면적의 3분의 2 이상 소유자와 소유자 총수의 2분의 1 이상 동의","법 제4조제4항"],["수용·사용 방식의 민간 시행자","사업대상 토지면적의 3분의 2 이상 소유하고 토지 소유자 총수의 2분의 1 이상 동의","법 제22조제1항"],["구역 지정 제안 시 동의","대상 구역 토지면적의 3분의 2 이상 소유자(지상권자 포함) 동의","법 제11조제6항"],["시행자 변경 사유","실시계획 인가 후 2년 내 사업 미착수 등","법 제11조제8항제1호"]]}],"함정":"조합을 토지 소유자 단체이니 모든 방식의 시행자로 읽기 쉽다. 조합과 토지 소유자의 지위는 방식에 따라 달라진다. 수용·사용 방식에서 토지 소유자는 3분의 2 이상 소유 요건이 붙는다."},"35회-2차-055":{"한줄":"보증기관 및 보증의 내용은 법 제11조제1항제5호부터 제11호까지에 해당하는 자가 발행하는 경우에만 발행계획에 들어간다.","근거":[{"법령":"도시개발법 시행령","조문":"제47조","원문":"법 제23조제2항에 따른 토지상환채권의 발행계획에는 다음 각 호의 사항이 포함되어야 한다.\n  1. 시행자의 명칭\n  2. 토지상환채권의 발행총액\n  3. 토지상환채권의 이율\n  4. 토지상환채권의 발행가액 및 발행시기\n  5. 상환대상지역 또는 상환대상토지의 용도\n  6. 토지가격의 추산방법\n  7. 보증기관 및 보증의 내용(법 제11조제1항제5호부터 제11호까지의 규정에 해당하는 자가 발행하는 경우에만 해당한다)"},{"법령":"도시개발법","조문":"제23조제1항","원문":"① 시행자는 토지 소유자가 원하면 토지등의 매수 대금의 일부를 지급하기 위하여 대통령령으로 정하는 바에 따라 사업 시행으로 조성된 토지ㆍ건축물로 상환하는 채권(…)을 발행할 수 있다. 다만, 제11조제1항제5호부터 제11호까지의 규정에 해당하는 자는 대통령령으로 정하는 금융기관 등으로부터 지급보증을 받은 경우에만 이를 발행할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"한국토지주택공사는 법 제11조제1항제2호의 공공기관이다. 보증기관 기재는 제5호~제11호에 해당하는 시행자에게만 요구된다(영 제47조제7호)."},{"번호":2,"판정":"옳음","설명":"토지가격의 추산방법은 발행계획 포함사항이다(영 제47조제6호)."},{"번호":3,"판정":"옳음","설명":"상환대상지역 또는 상환대상토지의 용도는 포함사항이다(영 제47조제5호)."},{"번호":4,"판정":"옳음","설명":"발행가액과 발행시기는 포함사항이다(영 제47조제4호)."},{"번호":5,"판정":"옳음","설명":"발행총액은 포함사항이다(영 제47조제2호)."}],"개념":[{"종류":"표","제목":"토지상환채권(법 제23조, 영 제45조~제54조)","머리":["항목","내용"],"행":[["발행 시기·목적","토지 소유자가 원하면 토지등의 매수 대금 일부를 사업으로 조성된 토지·건축물로 상환하는 채권을 발행"],["발행 규모","상환할 토지·건축물이 분양토지 또는 분양건축물 면적의 2분의 1을 초과하지 않도록 한다(영 제45조)"],["지급보증","법 제11조제1항제5호~제11호 시행자는 금융기관 등의 지급보증이 있어야 발행 가능. 보증기관은 은행, 보험회사, 공제조합(영 제46조)"],["발행계획 승인","지정권자가 시행자인 경우를 제외하고 미리 지정권자의 승인을 받는다(법 제23조제2항)"],["이율","발행 당시 은행 예금금리와 부동산 수급상황을 고려해 발행자가 정함(영 제49조제1항)"],["증권 형식","기명식 증권(영 제49조제2항)"]]},{"종류":"표","제목":"선수금·원형지·조성토지 공급","머리":["항목","내용","근거"],"행":[["선수금","조성토지등과 원형지를 공급받으려는 자로부터 대금 전부 또는 일부를 미리 받을 수 있다. 지정권자가 시행자인 경우를 제외하고 지정권자의 승인이 필요","법 제25조"],["공공 시행자의 선수금 요건","개발계획 수립·고시 후 사업시행 토지면적의 100분의 10 이상 소유권 확보(사용동의 포함)","영 제55조제1항제1호"],["원형지 공급 면적","도시개발구역 전체 토지 면적의 3분의 1 이내","법 제25조의2제1항"],["원형지개발자","국가·지방자치단체, 공공기관, 지방공사, 공모에서 선정된 자, 학교·공장 등 부지로 직접 사용하는 자","법 제25조의2제1항"],["원형지 매각 제한","공사완료 공고일부터 5년 또는 공급계약일부터 10년 중 먼저 끝나는 기간","영 제55조의2제3항"],["원형지 계약 해제","시행자가 2회 이상 시정을 요구하고도 시정하지 않은 경우","영 제55조의2제5항"],["조성토지등의 공급계획","지정권자가 아닌 시행자는 공급계획에 대해 지정권자의 승인을 받는다","법 제26조제1항"]]}],"함정":"발행계획 포함사항 7개 가운데 보증기관은 시행자 유형에 따라 붙는다. 공공 시행자에게는 지급보증 의무가 없으므로 보증 항목도 계획에서 빠진다."},"35회-2차-062":{"한줄":"조합설립인가일부터 3년 안에 사업시행계획인가를 신청하지 않으면 시장·군수등이 직접 시행하거나 토지주택공사등을 시행자로 지정할 수 있다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제26조제1항제3호","원문":"3. 추진위원회가 시장ㆍ군수등의 구성승인을 받은 날부터 3년 이내에 조합설립인가를 신청하지 아니하거나 조합이 조합설립인가를 받은 날부터 3년 이내에 사업시행계획인가를 신청하지 아니한 때"},{"법령":"도시 및 주거환경정비법","조문":"제35조제2항","원문":"② 재개발사업의 추진위원회(제31조제7항에 따라 추진위원회를 구성하지 아니하는 경우에는 토지등소유자를 말한다)가 조합을 설립하려면 토지등소유자의 4분의 3 이상 및 토지면적의 2분의 1 이상의 토지소유자의 동의를 받아 다음 각 호의 사항을 첨부하여 제16조에 따른 정비구역 지정ㆍ고시 후 시장ㆍ군수등의 인가를 받아야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제25조제1항제2호","원문":"2. 토지등소유자가 20인 미만인 경우에는 토지등소유자가 시행하거나 토지등소유자가 토지등소유자의 과반수의 동의를 받아 시장ㆍ군수등, 토지주택공사등, 건설업자, 등록사업자 또는 대통령령으로 정하는 요건을 갖춘 자와 공동으로 시행하는 방법"},{"법령":"도시 및 주거환경정비법 시행령","조문":"제30조제4항","원문":"④ 조합은 조합설립인가를 받은 때에는 정관으로 정하는 바에 따라 토지등소유자에게 그 내용을 통지하고, 이해관계인이 열람할 수 있도록 하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제35조제10항","원문":"⑩ 추진위원회는 조합설립에 필요한 동의를 받기 전에 추정분담금 등 대통령령으로 정하는 정보를 토지등소유자에게 제공하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"재개발·재건축 모두 해당한다. 추진위원회 승인 후 3년 이내 조합설립인가를 신청하지 않은 경우도 같은 호에 있다(법 제26조제1항제3호)."},{"번호":2,"판정":"틀림","설명":"재개발조합 설립동의는 토지등소유자 4분의 3 이상, 토지면적 2분의 1 이상 토지소유자다(법 제35조제2항). 3분의 2는 주택단지가 아닌 지역이 포함된 재건축의 토지면적 기준이다(법 제35조제4항)."},{"번호":3,"판정":"틀림","설명":"조합 없이 토지등소유자가 직접 시행하는 재개발은 토지등소유자가 20인 미만일 때다(법 제25조제1항제2호, 제35조제1항 단서)."},{"번호":4,"판정":"틀림","설명":"조합은 설립인가를 받으면 정관으로 정하는 바에 따라 토지등소유자에게 그 내용을 통지하고 이해관계인이 열람하게 한다(영 제30조제4항)."},{"번호":5,"판정":"틀림","설명":"추정분담금 등 정보는 조합설립에 필요한 동의를 받기 전에 제공한다(법 제35조제10항, 영 제32조). 인가 후가 아니다."}],"개념":[{"종류":"표","제목":"조합설립 동의요건(법 제35조, 제31조)","머리":["구분","사람 기준","토지면적 기준"],"행":[["추진위원회 구성","토지등소유자 과반수(위원장 포함 추진위원 5명 이상)","-"],["재개발 조합설립","토지등소유자 4분의 3 이상","토지면적 2분의 1 이상 토지소유자"],["재건축 조합설립(주택단지)","동별 구분소유자 과반수(동별 구분소유자 5 이하는 제외) + 전체 구분소유자 100분의 70 이상","토지면적 100분의 70 이상 토지소유자"],["재건축 조합설립(주택단지가 아닌 지역 포함)","그 지역의 토지 또는 건축물 소유자 4분의 3 이상","그 지역 토지면적 3분의 2 이상 토지소유자"],["인가받은 사항 변경","총회에서 조합원 3분의 2 이상 찬성 후 인가(경미한 사항은 신고)","-"]]},{"종류":"표","제목":"시장·군수등의 직접 시행·공공시행자 지정 사유(법 제26조제1항)","머리":["사유","내용"],"행":[["긴급한 필요","천재지변, 사용제한·사용금지 등 불가피한 사유로 긴급하게 시행할 필요가 있는 때"],["사업시행계획인가 미신청","정비계획 고시의 정비사업시행 예정일부터 2년 이내 미신청(재건축은 제외)"],["조합설립·사업시행 단계 지연","추진위원회 구성승인일부터 3년 이내 조합설립인가 미신청, 조합설립인가일부터 3년 이내 사업시행계획인가 미신청"],["국·공유지 비율","국·공유지(또는 토지주택공사등 소유 합산)가 전체 토지면적의 2분의 1 이상이고 토지등소유자 과반수가 동의"],["주민 요청","토지면적 2분의 1 이상 토지소유자와 토지등소유자 3분의 2 이상이 지정을 요청"]]}],"함정":"2번은 재건축의 주택단지가 아닌 지역에서 쓰는 3분의 2를 재개발에 끌어온 문장이다. 3번은 20인을 30인으로, 5번은 동의 전을 인가 후로 바꿔 놓았다. 3년과 2년, 20인과 30인처럼 숫자 한 칸만 틀리게 하는 유형이다."},"35회-2차-069":{"한줄":"사전방문은 입주지정기간 시작일 45일 전까지 2일 이상 실시한다.","근거":[{"법령":"주택법 시행규칙","조문":"제20조의2제1항·제2항","원문":"① 사업주체는 법 제48조의2제1항에 따른 사전방문(이하 \"사전방문\"이라 한다)을 주택공급계약에 따라 정한 입주지정기간 시작일 45일 전까지 2일 이상 실시해야 한다.\n② 사업주체가 사전방문을 실시하려는 경우에는 사전방문기간 및 방법 등 사전방문에 필요한 사항을 포함한  사전방문계획을 수립하여 사용검사권자에게 제출하고, 입주예정자에게 그 내용을 서면(전자문서를 포함한다)으로 알려야 한다. 이 경우 사전방문계획의 제출 및 통보는 사전방문기간 시작일 1개월 전까지 해야 한다."},{"법령":"주택법","조문":"제48조의2제4항","원문":"④ 제3항에도 불구하고 입주예정자가 요청한 사항이 하자가 아니라고 판단하는 사업주체는 대통령령으로 정하는 바에 따라 제49조제1항에 따른 사용검사를 하는 시장ㆍ군수ㆍ구청장(이하 \"사용검사권자\"라 한다)에게 하자 여부를 확인해줄 것을 요청할 수 있다. 이 경우 사용검사권자는 제48조의3에 따른 공동주택 품질점검단의 자문을 받는 등 대통령령으로 정하는 바에 따라 하자 여부를 확인할 수 있다."},{"법령":"주택법 시행령","조문":"제53조의3제3항","원문":"③ 사용검사권자는 제1항에 따라 확인 요청을 받은 날부터 7일 이내에 하자 여부를 확인하여 해당 사업주체에게 통보해야 한다."},{"법령":"주택법 시행령","조문":"제53조의2제3항","원문":"③ 조치계획을 수립한 사업주체는 법 제48조의2에 따른 사전방문 기간의 종료일부터 7일 이내에 사용검사권자(법 제49조제1항에 따라 사용검사를 하는 자를 말한다. 이하 같다)에게 해당 조치계획을 제출하고, 입주예정자에게 그 조치계획을 문서(전자문서를 포함한다)로 알려야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제48조의2제4항 전단."},{"번호":2,"판정":"틀림","설명":"입주지정기간 시작일 45일 전까지 2일 이상 실시한다(규칙 제20조의2제1항)."},{"번호":3,"판정":"옳음","설명":"사전방문계획의 제출·통보는 사전방문기간 시작일 1개월 전까지다(규칙 제20조의2제2항)."},{"번호":4,"판정":"옳음","설명":"영 제53조의3제3항."},{"번호":5,"판정":"옳음","설명":"영 제53조의2제3항."}],"개념":[{"종류":"흐름","제목":"사전방문 절차","단계":[{"이름":"감리자 확인","설명":"전유부분과 공용부분(계단·복도·승강기·현관)이 설계도서대로 시공됐는지 감리자에게 확인받은 뒤 실시(규칙 제20조의2제3항)"},{"이름":"사전방문계획","설명":"사용검사권자에게 제출하고 입주예정자에게 서면 통보. 사전방문기간 시작일 1개월 전까지(규칙 제20조의2제2항)"},{"이름":"사전방문 실시","설명":"입주지정기간 시작일 45일 전까지 2일 이상(규칙 제20조의2제1항)"},{"이름":"하자 조치 요청","설명":"입주예정자가 사업주체에게 보수공사 등 조치 요청(법 제48조의2제2항)"},{"이름":"조치계획 제출","설명":"사전방문기간 종료일부터 7일 이내 사용검사권자에게 제출하고 입주예정자에게 통지(영 제53조의2제3항)"},{"이름":"하자 여부 확인","설명":"사업주체가 하자가 아니라고 판단하면 조치계획 제출 때 자료를 붙여 확인 요청. 사용검사권자는 7일 이내 통보(영 제53조의3)"},{"이름":"조치 완료","설명":"중대한 하자는 특별한 사유가 없으면 사용검사를 받기 전까지 완료(법 제48조의2제3항)"}]},{"종류":"표","제목":"사전방문 숫자 모음","머리":["항목","기준","근거"],"행":[["사전방문 시기·일수","입주지정기간 시작일 45일 전까지 2일 이상","규칙 제20조의2제1항"],["계획 제출","사전방문기간 시작일 1개월 전까지","규칙 제20조의2제2항"],["조치계획 제출","사전방문기간 종료일부터 7일 이내","영 제53조의2제3항"],["하자 여부 통보","확인 요청을 받은 날부터 7일 이내","영 제53조의3제3항"],["그 밖의 하자 조치(전유부분)","입주예정자에게 인도하기 전","영 제53조의2제2항제2호"]]}],"함정":"45일과 2일을 60일과 1일로 바꾼 선지 하나가 정답이다. 나머지 네 선지는 1개월, 7일, 7일, 하자 확인 요청처럼 외워 둔 기한이 맞게 나와서 오히려 안심하고 넘기게 된다. 정답률은 21%였다."},"35회-2차-082":{"한줄":"일시적·임시적 용도로 쓰이는 토지는 그 용도에 따라 지목을 변경하지 않는다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제59조","원문":"제59조(지목의 설정방법 등)\n① 법 제67조제1항에 따른 지목의 설정은 다음 각 호의 방법에 따른다.\n  1. 필지마다 하나의 지목을 설정할 것\n  2. 1필지가 둘 이상의 용도로 활용되는 경우에는 주된 용도에 따라 지목을 설정할 것\n② 토지가 일시적 또는 임시적인 용도로 사용될 때에는 지목을 변경하지 아니한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제1호·제2호","원문":"제58조(지목의 구분) 법 제67조제1항에 따른 지목의 구분은 다음 각 호의 기준에 따른다.\n  1. 전\n　물을 상시적으로 이용하지 않고 곡물ㆍ원예작물(과수류는 제외한다)ㆍ약초ㆍ뽕나무ㆍ닥나무ㆍ묘목ㆍ관상수 등의 식물을 주로 재배하는 토지와 식용(食用)으로 죽순을 재배하는 토지\n  2. 답\n　물을 상시적으로 직접 이용하여 벼ㆍ연(蓮)ㆍ미나리ㆍ왕골 등의 식물을 주로 재배하는 토지"}],"선지":[{"번호":1,"판정":"옳음","설명":"1필 1지목이 원칙이다(영 제59조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"1필지가 둘 이상의 용도로 쓰이면 주된 용도를 따른다(영 제59조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"일시적·임시적 용도로 쓰일 때에는 지목을 변경하지 않는다(영 제59조제2항)."},{"번호":4,"판정":"옳음","설명":"물을 상시 이용하지 않고 닥나무·묘목·관상수 등을 재배하는 토지가 전이다(영 제58조제1호)."},{"번호":5,"판정":"옳음","설명":"물을 상시 직접 이용해 벼·연·미나리·왕골 등을 재배하는 토지가 답이다(영 제58조제2호)."}],"개념":[{"종류":"표","제목":"지목 설정 규정 모음","머리":["구분","내용","근거"],"행":[["지목 종류","전·답·과수원·목장용지·임야·광천지·염전·대·공장용지·학교용지·주차장·주유소용지·창고용지·도로·철도용지·제방·하천·구거·유지·양어장·수도용지·공원·체육용지·유원지·종교용지·사적지·묘지·잡종지, 28종","법 제67조제1항"],["필지와 지목","필지마다 하나의 지목","영 제59조제1항제1호"],["용도가 둘 이상","주된 용도에 따라 설정","영 제59조제1항제2호"],["일시적·임시적 용도","지목을 변경하지 않음","영 제59조제2항"],["지적도면 부호","대부분 첫 글자, 공장용지 장·하천 천·유원지 원·주차장 차","규칙 제64조"]]},{"종류":"비교","제목":"전과 답","왼쪽":{"이름":"전","항목":["물을 상시 이용하지 않음","곡물·원예작물(과수류 제외)·약초·뽕나무·닥나무·묘목·관상수 재배","식용 죽순 재배지 포함"]},"오른쪽":{"이름":"답","항목":["물을 상시 직접 이용","벼·연·미나리·왕골 등 재배"]}}],"함정":"③은 「변경하여야 한다」로 바뀐 문장이다. 일시적·임시적 용도에서는 지목 변경이 일어나지 않는다. ④의 닥나무·묘목·관상수는 낯선 작물 이름이지만 전의 정의 그대로다."},"35회-2차-090":{"한줄":"경계점좌표등록부에는 토지의 소재, 지번, 좌표와 함께 토지의 고유번호, 지적도면의 번호, 장번호, 부호 및 부호도를 등록한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제73조","원문":"제73조(경계점좌표등록부의 등록사항) 지적소관청은 제86조에 따른 도시개발사업 등에 따라 새로이 지적공부에 등록하는 토지에 대하여는 다음 각 호의 사항을 등록한 경계점좌표등록부를 작성하고 갖춰 두어야 한다.\n  1. 토지의 소재\n  2. 지번\n  3. 좌표\n  4. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제71조제3항","원문":"제71조(경계점좌표등록부의 등록사항 등)\n③ 법 제73조제4호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다.\n  1. 토지의 고유번호\n  2. 지적도면의 번호\n  3. 필지별 경계점좌표등록부의 장번호\n  4. 부호 및 부호도"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제71조제1항","원문":"제71조(토지대장 등의 등록사항)\n① 토지대장과 임야대장에는 다음 각 호의 사항을 등록하여야 한다.\n  1. 토지의 소재\n  2. 지번\n  3. 지목\n  4. 면적\n  5. 소유자의 성명 또는 명칭, 주소 및 주민등록번호(국가, 지방자치단체, 법인, 법인 아닌 사단이나 재단 및 외국인의 경우에는 「부동산등기법」 제49조에 따라 부여된 등록번호를 말한다. 이하 같다)\n  1. 토지의 소재\n  2. 지번\n  3. 소유권 지분\n  4. 소유자의 성명 또는 명칭, 주소 및 주민등록번호\n  5. 그 밖에 국토교통부령으로 정하는 사항\n  1. 토지의 소재\n  2. 지번\n  3. 대지권 비율\n  4. 소유자의 성명 또는 명칭, 주소 및 주민등록번호\n  5. 그 밖에 국토교통부령으로 정하는 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"토지대장에는 토지의 소재·지번·지목·면적·소유자 등을 등록하고 경계는 등록하지 않는다(법 제71조제1항). 경계는 지적도·임야도에 등록한다(법 제72조)."},{"번호":2,"판정":"옳음","설명":"지번은 법 제73조제2호, 고유번호와 지적도면의 번호는 규칙 제71조제3항제1호·제2호다."},{"번호":3,"판정":"틀림","설명":"공유지연명부에는 지목이 없다. 토지의 소재·지번·소유권 지분·소유자 정보·고유번호 등을 등록한다(법 제71조제2항, 규칙 제68조제3항)."},{"번호":4,"판정":"틀림","설명":"대지권등록부에 좌표는 없다. 토지의 소재·지번·대지권 비율·소유자 정보·건물의 명칭 등을 등록한다(법 제71조제3항, 규칙 제68조제4항)."},{"번호":5,"판정":"틀림","설명":"부호 및 부호도는 경계점좌표등록부 등록사항이다(규칙 제71조제3항제4호). 지적도에는 삼각점 및 지적기준점의 위치, 도곽선과 그 수치 등을 등록한다(규칙 제69조제2항)."}],"개념":[{"종류":"표","제목":"지적공부별 등록사항","머리":["지적공부","법정 등록사항","규칙상 추가 등록사항"],"행":[["토지대장·임야대장","토지의 소재, 지번, 지목, 면적, 소유자 성명·주소·주민등록번호","고유번호, 도면 번호·장번호·축척, 토지의 이동사유, 소유자 변경일과 원인, 토지등급, 개별공시지가와 기준일"],["공유지연명부","토지의 소재, 지번, 소유권 지분, 소유자 성명·주소·주민등록번호","고유번호, 장번호, 소유자 변경일과 원인"],["대지권등록부","토지의 소재, 지번, 대지권 비율, 소유자 성명·주소·주민등록번호","고유번호, 전유부분 건물표시, 건물의 명칭, 장번호, 소유자 변경일과 원인, 소유권 지분"],["지적도·임야도","토지의 소재, 지번, 지목, 경계","색인도, 제명과 축척, 도곽선과 수치, 삼각점·지적기준점 위치, 건축물·구조물 위치, 좌표 지역의 경계점 간 거리"],["경계점좌표등록부","토지의 소재, 지번, 좌표","고유번호, 지적도면의 번호, 장번호, 부호 및 부호도"]]}],"함정":"경계는 지적도·임야도에만 있고 토지대장에는 없다. 지목은 공유지연명부에 없다. 좌표는 경계점좌표등록부에만 있다. 부호도를 지적도 등록사항으로 옮겨 적은 ⑤가 가장 많이 걸린다."},"35회-2차-089":{"한줄":"지적도와 임야도에 모두 있는 축척은 1/3000과 1/6000이다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제69조제6항","원문":"제69조(지적도면 등의 등록사항 등)\n  1. 지적도면의 색인도(인접도면의 연결 순서를 표시하기 위하여 기재한 도표와 번호를 말한다)\n  2. 지적도면의 제명 및 축척\n⑥ 지적도면의 축척은 다음 각 호의 구분에 따른다.\n  1. 지적도: 1/500,  1/600, 1/1000, 1/1200, 1/2400, 1/3000, 1/6000\n  2. 임야도: 1/3000, 1/6000"}],"선지":[{"번호":1,"판정":"-","설명":"1/1200, 1/2400은 지적도에만 있다."},{"번호":2,"판정":"-","설명":"1/1200은 지적도에만 있다."},{"번호":3,"판정":"-","설명":"1/2400은 지적도에만 있다."},{"번호":4,"판정":"-","설명":"1/2400은 지적도에만 있다."},{"번호":5,"판정":"-","설명":"두 도면에 모두 있는 축척이다."}],"개념":[{"종류":"표","제목":"지적도면 축척","머리":["도면","축척","개수"],"행":[["지적도","1/500, 1/600, 1/1000, 1/1200, 1/2400, 1/3000, 1/6000","7종"],["임야도","1/3000, 1/6000","2종"],["공통","1/3000, 1/6000","2종"],["지적도에만","1/500, 1/600, 1/1000, 1/1200, 1/2400","5종"]]}],"함정":"임야도의 축척은 1/3000, 1/6000 두 개뿐이다. 1/1200, 1/2400을 임야도에도 있는 축척으로 알면 ①②③④에 걸린다. 1/600은 지적도 축척이고 이 지역은 면적을 0.1m2 단위로 정한다."},"35회-2차-081":{"한줄":"신규등록은 지적소관청의 등기촉탁 대상에서 제외된다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제89조제1항","원문":"제89조(등기촉탁)\n① 지적소관청은 제64조제2항(신규등록은 제외한다), 제66조제2항, 제82조, 제83조제2항, 제84조제2항 또는 제85조제2항에 따른 사유로 토지의 표시 변경에 관한 등기를 할 필요가 있는 경우에는 지체 없이 관할 등기관서에 그 등기를 촉탁하여야 한다. 이 경우 등기촉탁은 국가가 국가를 위하여 하는 등기로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지목변경은 토지의 이동(법 제64조제2항)이어서 촉탁 대상이다."},{"번호":2,"판정":"옳음","설명":"지번변경(법 제66조제2항)은 촉탁 대상이다."},{"번호":3,"판정":"틀림","설명":"신규등록은 법 제89조제1항 괄호에서 제외된다. 신규등록 토지는 미등기 상태여서 토지소유자가 소유권보존등기를 신청한다."},{"번호":4,"판정":"옳음","설명":"축척변경(법 제83조제2항)은 촉탁 대상이다."},{"번호":5,"판정":"옳음","설명":"합병은 토지의 이동(법 제64조제2항)이어서 촉탁 대상이다."}],"개념":[{"종류":"표","제목":"지적소관청의 등기촉탁 사유","머리":["사유","근거 조문","촉탁 여부"],"행":[["토지의 이동(분할·합병·지목변경 등)","법 제64조제2항","촉탁"],["신규등록","법 제64조제2항","촉탁 제외"],["지번변경","법 제66조제2항","촉탁"],["바다로 된 토지의 등록말소","법 제82조","촉탁"],["축척변경","법 제83조제2항","촉탁"],["등록사항 정정(직권)","법 제84조제2항","촉탁"],["행정구역 개편으로 새 지번 부여","법 제85조제2항","촉탁"]]},{"종류":"흐름","제목":"신규등록 토지의 등기","단계":[{"이름":"토지소유자의 신규등록 신청","설명":"공유수면 매립 등으로 새로 생긴 토지를 지적공부에 등록한다."},{"이름":"지적소관청의 지적공부 등록","설명":"토지대장 등에 최초 소유자로 등록한다."},{"이름":"촉탁 없음","설명":"신규등록은 법 제89조제1항 촉탁 대상에서 제외된다."},{"이름":"소유권보존등기 신청","설명":"토지대장에 최초의 소유자로 등록된 자나 그 상속인 등이 신청한다(부동산등기법 제65조제1호)."}]}],"함정":"분할·합병·지목변경 같은 일반 토지이동은 모두 촉탁 대상이다. 같은 토지이동 중에서도 신규등록만 빠진다는 점이 쟁점이다. 미등기 토지에는 바꿀 표시등기가 없다."},"35회-2차-086":{"한줄":"소유권이전등기 연월일이 서로 달라도 합병 신청은 막히지 않는다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제80조제3항","원문":"제80조(합병 신청)\n③ 다음 각 호의 어느 하나에 해당하는 경우에는 합병 신청을 할 수 없다.\n  1. 합병하려는 토지의 지번부여지역, 지목 또는 소유자가 서로 다른 경우\n  2. 합병하려는 토지에 다음 각 목의 등기 외의 등기가 있는 경우\n    가. 소유권ㆍ지상권ㆍ전세권 또는 임차권의 등기\n    나. 승역지(承役地)에 대한 지역권의 등기\n    다. 합병하려는 토지 전부에 대한 등기원인(登記原因) 및 그 연월일과 접수번호가 같은 저당권의 등기\n    라. 합병하려는 토지 전부에 대한 「부동산등기법」 제81조제1항 각 호의 등기사항이 동일한 신탁등기\n  3. 그 밖에 합병하려는 토지의 지적도 및 임야도의 축척이 서로 다른 경우 등 대통령령으로 정하는 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제66조제3항","원문":"제66조(합병 신청)\n③ 법 제80조제3항제3호에서 \"합병하려는 토지의 지적도 및 임야도의 축척이 서로 다른 경우 등 대통령령으로 정하는 경우\"란 다음 각 호의 경우를 말한다.\n  1. 합병하려는 토지의 지적도 및 임야도의 축척이 서로 다른 경우\n  2. 합병하려는 각 필지가 서로 연접하지 않은 경우\n  3. 합병하려는 토지가 등기된 토지와 등기되지 아니한 토지인 경우\n  4. 합병하려는 각 필지의 지목은 같으나 일부 토지의 용도가 다르게 되어 법 제79조제2항에 따른 분할대상 토지인 경우. 다만, 합병 신청과 동시에 토지의 용도에 따라 분할 신청을 하는 경우는 제외한다.\n  5. 합병하려는 토지의 소유자별 공유지분이 다른 경우\n  6. 합병하려는 토지가 구획정리, 경지정리 또는 축척변경을 시행하고 있는 지역의 토지와 그 지역 밖의 토지인 경우\n  7. 합병하려는 토지 소유자의 주소가 서로 다른 경우. 다만, 제1항에 따른 신청을 접수받은 지적소관청이 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 목의 사항을 확인(신청인이 주민등록표 초본 확인에 동의하지 않는 경우에는 해당 자료를 첨부하도록 하여 확인)한 결과 토지 소유자가 동일인임을 확인할 수 있는 경우는 제외한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지번부여지역·지목·소유자가 서로 다르면 합병할 수 없다(법 제80조제3항제1호)."},{"번호":2,"판정":"옳음","설명":"소유자별 공유지분이 다르면 합병할 수 없다(영 제66조제3항제5호)."},{"번호":3,"판정":"옳음","설명":"지번부여지역이 다르면 합병할 수 없다(법 제80조제3항제1호)."},{"번호":4,"판정":"틀림","설명":"소유권이전등기 연월일의 차이는 합병 제한 사유로 규정되어 있지 않다. 소유권 등기가 있으면 합병은 가능하다(법 제80조제3항제2호 가목). 등기원인·연월일·접수번호가 같아야 하는 것은 저당권 등기다(다목)."},{"번호":5,"판정":"옳음","설명":"지적도 및 임야도의 축척이 서로 다르면 합병할 수 없다(영 제66조제3항제1호)."}],"개념":[{"종류":"표","제목":"합병 신청을 할 수 없는 경우","머리":["구분","내용","근거"],"행":[["법 제80조제3항제1호","지번부여지역, 지목 또는 소유자가 서로 다른 경우","법"],["법 제80조제3항제2호","소유권·지상권·전세권·임차권 등기, 승역지 지역권 등기, 전부에 원인·연월일·접수번호가 같은 저당권 등기, 신탁등기사항이 동일한 신탁등기 외의 등기가 있는 경우","법"],["영 제66조제3항","축척이 다른 경우, 연접하지 않은 경우, 등기·미등기 혼합, 분할대상 토지, 공유지분이 다른 경우, 구획정리·경지정리·축척변경 시행지역과 지역 밖 토지, 소유자 주소가 다른 경우","영"]]},{"종류":"비교","제목":"합병 의무와 합병 신청","왼쪽":{"이름":"합병 신청 의무","항목":["공동주택 부지, 도로, 제방, 하천, 구거, 유지 등 합병하여야 할 토지","사유가 발생한 날부터 60일 이내에 신청(법 제80조제2항)"]},"오른쪽":{"이름":"일반 합병","항목":["토지소유자가 임의로 신청(법 제80조제1항)","합병 제한 사유가 있으면 신청 불가(법 제80조제3항)"]}}],"함정":"소유자가 서로 다르면 합병할 수 없지만, 소유권이전등기를 한 날이 다른 것은 별개 문제다. 이전등기 연월일은 저당권 등기에서만 같아야 한다. ②는 소유자가 같아도 지분이 다르면 안 된다는 규정이다."},"35회-2차-092":{"한줄":"청산금의 납부·지급이 끝나면 확정공고를 하고, 확정공고에는 토지의 소재 및 지역명, 축척변경 지번별 조서, 청산금 조서, 지적도의 축척이 들어간다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제78조제1항","원문":"제78조(축척변경의 확정공고)\n① 청산금의 납부 및 지급이 완료되었을 때에는 지적소관청은 지체 없이 축척변경의 확정공고를 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제92조제1항","원문":"제92조(축척변경의 확정공고)\n① 영 제78조제1항에 따른 축척변경의 확정공고에는 다음 각 호의 사항이 포함되어야 한다.\n  1. 토지의 소재 및 지역명\n  2. 영 제73조에 따른 축척변경 지번별 조서\n  3. 영 제75조제4항에 따른 청산금 조서\n  4. 지적도의 축척\n  1. 토지대장은 제1항제2호에 따라 확정공고된 축척변경 지번별 조서에 따를 것\n  2. 지적도는 확정측량 결과도 또는 경계점좌표에 따를 것"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제83조제3항","원문":"제83조(축척변경)\n  1. 잦은 토지의 이동으로 1필지의 규모가 작아서 소축척으로는 지적측량성과의 결정이나 토지의 이동에 따른 정리를 하기가 곤란한 경우\n  2. 하나의 지번부여지역에 서로 다른 축척의 지적도가 있는 경우\n③ 지적소관청은 제2항에 따라 축척변경을 하려면 축척변경 시행지역의 토지소유자 3분의 2 이상의 동의를 받아 제1항에 따른 축척변경위원회의 의결을 거친 후 시ㆍ도지사 또는 대도시 시장의 승인을 받아야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 축척변경위원회의 의결 및 시ㆍ도지사 또는 대도시 시장의 승인 없이 축척변경을 할 수 있다.\n  1. 합병하려는 토지가 축척이 다른 지적도에 각각 등록되어 있어 축척변경을 하는 경우\n  2. 제86조에 따른 도시개발사업 등의 시행지역에 있는 토지로서 그 사업 시행에서 제외된 토지의 축척변경을 하는 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제71조제1항","원문":"제71조(축척변경 시행공고 등)\n① 지적소관청은 법 제83조제3항에 따라 시ㆍ도지사 또는 대도시 시장으로부터 축척변경 승인을 받았을 때에는 지체 없이 다음 각 호의 사항을 20일 이상 공고하여야 한다.\n  1. 축척변경의 목적, 시행지역 및 시행기간\n  2. 축척변경의 시행에 관한 세부계획\n  3. 축척변경의 시행에 따른 청산방법\n  4. 축척변경의 시행에 따른 토지소유자 등의 협조에 관한 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제75조제1항","원문":"제75조(청산금의 산정)\n① 지적소관청은 축척변경에 관한 측량을 한 결과 측량 전에 비하여 면적의 증감이 있는 경우에는 그 증감면적에 대하여 청산을 하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.\n  1. 필지별 증감면적이 제19조제1항제2호가목에 따른 허용범위 이내인 경우. 다만, 축척변경위원회의 의결이 있는 경우는 제외한다.\n  2. 토지소유자 전원이 청산하지 아니하기로 합의하여 서면으로 제출한 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제76조제2항·제5항","원문":"제76조(청산금의 납부고지 등)\n② 제1항에 따른 납부고지를 받은 자는 그 고지를 받은 날부터 6개월 이내에 청산금을 지적소관청에 내야 한다.\n⑤ 지적소관청은 청산금을 내야 하는 자가 제77조제1항에 따른 기간 내에 청산금에 관한 이의신청을 하지 아니하고 제2항에 따른 기간 내에 청산금을 내지 아니하면 「지방행정제재ㆍ부과금의 징수 등에 관한 법률」에 따라 징수할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"사업시행에서 제외된 토지의 축척변경은 위원회 의결과 시·도지사 또는 대도시 시장의 승인 없이 할 수 있다(법 제83조제3항 단서 제2호)."},{"번호":2,"판정":"틀림","설명":"시행공고 기간은 20일 이상이고, 공고사항은 「청산금액」이 아니라 「청산방법」이다(영 제71조제1항)."},{"번호":3,"판정":"틀림","설명":"청산하지 않을 수 있는 경우는 토지소유자 전원이 합의해 서면으로 제출한 때다(영 제75조제1항제2호). 3분의 2가 아니다."},{"번호":4,"판정":"틀림","설명":"청산금 납부기간은 납부고지를 받은 날부터 6개월이다(영 제76조제2항). 이의신청 기간 1개월은 맞다(영 제77조제1항)."},{"번호":5,"판정":"옳음","설명":"영 제78조제1항, 규칙 제92조제1항 그대로다."}],"개념":[{"종류":"흐름","제목":"축척변경 절차","단계":[{"이름":"신청 또는 직권","설명":"토지소유자의 신청 또는 지적소관청의 직권으로 일정한 지역을 정한다."},{"이름":"동의·의결·승인","설명":"시행지역 토지소유자 3분의 2 이상 동의 → 축척변경위원회 의결 → 시·도지사 또는 대도시 시장 승인."},{"이름":"시행공고","설명":"승인 후 지체 없이 20일 이상 공고한다."},{"이름":"경계점표지 설치","설명":"토지소유자 또는 점유자가 시행공고일부터 30일 이내에 설치한다."},{"이름":"측량과 지번별 조서","설명":"새 축척으로 측량하고 축척변경 지번별 조서를 작성한다."},{"이름":"청산금 산정·공고","설명":"청산금 조서를 작성하고 15일 이상 공고한다."},{"이름":"납부고지·수령통지","설명":"결정 공고일부터 20일 이내에 한다."},{"이름":"납부·지급","설명":"납부는 고지받은 날부터 6개월, 지급은 통지한 날부터 6개월 이내. 이의신청은 1개월 이내."},{"이름":"확정공고","설명":"납부·지급 완료 후 지체 없이. 확정공고일에 토지의 이동이 있는 것으로 본다."}]},{"종류":"표","제목":"축척변경의 기간·비율","머리":["항목","수치","근거"],"행":[["토지소유자 동의","3분의 2 이상","법 제83조제3항"],["시행공고","20일 이상","영 제71조제1항"],["경계점표지 설치","시행공고일부터 30일 이내","영 제71조제3항"],["청산금 결정 공고","15일 이상","영 제75조제4항"],["납부고지","청산금 결정 공고일부터 20일 이내","영 제76조제1항"],["청산금 납부","고지받은 날부터 6개월 이내","영 제76조제2항"],["이의신청","고지·통지받은 날부터 1개월 이내","영 제77조제1항"],["청산 생략 합의","토지소유자 전원","영 제75조제1항제2호"]]}],"함정":"공고 기간(20일)·청산금 공고(15일)를 서로 바꿔 놓은 ②와, 청산 생략 합의를 3분의 2로 바꾼 ③이 대표 함정이다. 청산금 납부는 6개월인데 ④는 3개월로 줄였다. ①은 도시개발사업 제외 토지의 특례를 반대로 적었다."},"35회-2차-098":{"한줄":"권리의 변경·경정등기는 원칙적으로 부기등기로 하되, 등기상 이해관계 있는 제3자의 승낙이 없으면 주등기로 한다.","근거":[{"법령":"부동산등기법","조문":"제52조제5호","원문":"제52조(부기로 하는 등기) 등기관이 다음 각 호의 등기를 할 때에는 부기로 하여야 한다. 다만, 제5호의 등기는 등기상 이해관계 있는 제3자의 승낙이 없는 경우에는 그러하지 아니하다.\n  5. 권리의 변경이나 경정의 등기"},{"법령":"부동산등기규칙","조문":"제46조제1항제3호","원문":"제46조(첨부정보)\n① 등기를 신청하는 경우에는 다음 각 호의 정보를 그 신청정보와 함께 첨부정보로서 등기소에 제공하여야 한다.\n  3. 등기상 이해관계 있는 제3자의 승낙이 필요한 경우에는 이를 증명하는 정보 또는 이에 대항할 수 있는 재판이 있음을 증명하는 정보\n  3. 건물의 소유자가 그 건물이 속하는 1동의 건물이 있는 「집합건물의 소유 및 관리에 관한 법률」 제2조제5호에 따른 건물의 대지에 대하여 가지는 대지사용권이 대지권이 아닌 경우"},{"이론":"상속·유증 등기 실무","내용":"유증은 유증자 명의에서 수증자 명의로 직접 이전하고, 상속재산분할심판·협의분할에 따른 상속등기의 등기원인일자는 상속개시일이다. 등기관은 형식적 심사만 하므로 유류분 침해 여부를 이유로 각하하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"유증은 상속등기를 거치지 않고 유증자로부터 직접 수증자 명의로 신청한다."},{"번호":2,"판정":"틀림","설명":"등기관은 형식적 심사권만 가지므로 유류분 침해 여부를 이유로 신청을 각하하지 못한다(법 제29조 각 호에 해당 사유가 없다)."},{"번호":3,"판정":"틀림","설명":"상속재산분할심판에 따른 이전등기는 법정상속분에 따른 상속등기를 거치지 않고 해당 상속인 명의로 직접 신청할 수 있다."},{"번호":4,"판정":"틀림","설명":"협의분할에 따른 상속등기의 등기원인일자는 협의분할일이 아니라 상속개시일(피상속인의 사망일)이다."},{"번호":5,"판정":"옳음","설명":"법 제52조 제5호 단서 그대로다. 제3자의 승낙이 없으면 부기가 아니라 주등기로 한다."}],"개념":[{"종류":"표","제목":"부기등기로 하는 등기(법 제52조)","머리":["호","대상","비고"],"행":[["1호","등기명의인표시의 변경·경정",""],["2호","소유권 외의 권리의 이전등기","저당권이전 등"],["3호","소유권 외의 권리를 목적으로 하는 권리에 관한 등기","전세권저당권 등"],["4호","소유권 외의 권리에 대한 처분제한 등기",""],["5호","권리의 변경·경정등기","이해관계 있는 제3자의 승낙이 없으면 주등기"],["6~8호","환매특약, 권리소멸약정, 공유물 분할금지 약정등기",""]]},{"종류":"비교","제목":"상속과 유증의 등기","왼쪽":{"이름":"상속","항목":["법정상속분대로 상속인 단독신청(법 제23조제3항)","협의분할이면 등기원인일자는 상속개시일"]},"오른쪽":{"이름":"유증","항목":["유증자 → 수증자 직접 신청","공동신청(법 제23조제1항)"]}}],"함정":"변경등기를 부기로 하는 것은 맞지만, 제3자의 승낙이 없으면 주등기다. 상속의 등기원인일자는 협의분할일이 아니라 상속개시일이다. 유증등기에 상속등기를 먼저 하라는 설명도 틀렸다."},"35회-2차-107":{"한줄":"주택 수는 과세기준일(6월 1일) 현재로 따지므로, 6월 17일에 2주택을 양도해도 그해 종합부동산세는 3주택 이상 세율로 계산한다.","근거":[{"법령":"종합부동산세법","조문":"제3조","원문":"제3조(과세기준일) 종합부동산세의 과세기준일은 「지방세법」 제114조에 따른 재산세의 과세기준일로 한다."},{"법령":"지방세법","조문":"제114조","원문":"제114조(과세기준일) 재산세의 과세기준일은 매년 6월 1일로 한다."},{"법령":"종합부동산세법","조문":"제9조제1항제2호","원문":"① 주택에 대한 종합부동산세는 다음 각 호와 같이 납세의무자가 소유한 주택 수에 따라 과세표준에 해당 세율을 적용하여 계산한 금액을 그 세액(이하 \"주택분 종합부동산세액\"이라 한다)으로 한다. 2. 납세의무자가 3주택 이상을 소유한 경우"},{"법령":"종합부동산세법","조문":"제9조제2항제3호","원문":"② 납세의무자가 법인 또는 법인으로 보는 단체인 경우 제1항에도 불구하고 과세표준에 다음 각 호에 따른 세율을 적용하여 계산한 금액을 주택분 종합부동산세액으로 한다. 3. 제1호 및 제2호 외의 경우: 다음 각 목에 따른 세율 가. 2주택 이하를 소유한 경우: 1천분의 27 나. 3주택 이상을 소유한 경우: 1천분의 50"},{"법령":"종합부동산세법","조문":"제7조제2항","원문":"② 「신탁법」 제2조에 따른 수탁자(이하 \"수탁자\"라 한다)의 명의로 등기 또는 등록된 신탁재산으로서 주택(이하 \"신탁주택\"이라 한다)의 경우에는 제1항에도 불구하고 같은 조에 따른 위탁자[「주택법」 제2조제11호가목에 따른 지역주택조합, 같은 호 나목에 따른 직장주택조합 등 위탁자별로 구분 과세가 곤란한 조합으로서 대통령령으로 정하는 조합(이하 \"지역주택조합등\"이라 한다)이 조합원이 납부한 금전으로 매수하여 소유하고 있는 신탁주택의 경우에는 해당 지역주택조합등을 말한다. 이하 \"위탁자\"라 한다]가 종합부동산세를 납부할 의무가 있다. 이 경우 위탁자가 신탁주택을 소유한 것으로 본다."},{"법령":"종합부동산세법","조문":"제7조의2","원문":"제7조의2(신탁주택 관련 수탁자의 물적납세의무) 신탁주택의 위탁자가 다음 각 호의 어느 하나에 해당하는 종합부동산세 또는 강제징수비(이하 \"종합부동산세등\"이라 한다)를 체납한 경우로서 그 위탁자의 다른 재산에 대하여 강제징수를 하여도 징수할 금액에 미치지 못할 때에는 해당 신탁주택의 수탁자는 그 신탁주택(해당 신탁주택의 관리, 처분, 운용 또는 개발 등을 통하여 수탁자가 얻은 재산으로서 「신탁법」 제27조에 따라 신탁재산에 속하는 재산을 포함한다)으로써 위탁자의 종합부동산세등을 납부할 의무가 있다."},{"법령":"종합부동산세법","조문":"제8조제1항","원문":"① 주택에 대한 종합부동산세의 과세표준은 납세의무자별로 주택의 공시가격을 합산한 금액에서 다음 각 호의 금액을 공제한 금액에 부동산 시장의 동향과 재정 여건 등을 고려하여 100분의 60부터 100분의 100까지의 범위에서 대통령령으로 정하는 공정시장가액비율을 곱한 금액으로 한다. 다만, 그 금액이 영보다 작은 경우에는 영으로 본다. 1. 대통령령으로 정하는 1세대 1주택자(이하 \"1세대 1주택자\"라 한다): 12억원 2. 제9조제2항제3호 각 목의 세율이 적용되는 법인 또는 법인으로 보는 단체: 0원 3. 제1호 및 제2호에 해당하지 아니하는 자: 9억원"},{"법령":"종합부동산세법 시행령","조문":"제2조의4제1항","원문":"① 법 제8조제1항 각 호 외의 부분 본문에서 \"대통령령으로 정하는 공정시장가액비율\"이란 100분의 60을 말하되, 2019년부터 2021년까지 납세의무가 성립하는 종합부동산세에 대해서는 다음 각 호의 연도별 비율을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수탁자 명의 신탁주택은 위탁자가 종합부동산세를 납부할 의무가 있고 위탁자가 소유한 것으로 본다(종합부동산세법 제7조제2항)."},{"번호":2,"판정":"틀림","설명":"법인의 세율은 2주택 이하가 1천분의 27, 3주택 이상이 1천분의 50이다. 2주택이면 1천분의 27이다(종합부동산세법 제9조제2항제3호)."},{"번호":3,"판정":"옳음","설명":"종합부동산세의 과세기준일은 재산세 과세기준일(6월 1일)이다. 6월 17일 양도분도 그해 주택 수에 포함되어 3주택 이상 세율(제9조제1항제2호)을 적용한다(종합부동산세법 제3조, 지방세법 제114조)."},{"번호":4,"판정":"틀림","설명":"납세의무자가 위탁자이고, 위탁자가 체납한 경우에 위탁자의 다른 재산으로 부족하면 수탁자가 신탁주택으로써 납부한다. 선지는 수탁자와 위탁자가 거꾸로 되어 있다(종합부동산세법 제7조의2)."},{"번호":5,"판정":"틀림","설명":"과세표준은 시가가 아니라 공시가격을 합산한 금액에서 공제금액(1세대 1주택자 12억원, 일반 9억원)을 빼고 공정시장가액비율을 곱한다. 비율은 100분의 60부터 100까지 범위에서 대통령령으로 정하며 현재 100분의 60이다. 공동명의 1주택자는 신청하면 1세대 1주택자로 본다(종합부동산세법 제8조제1항, 제10조의2제3항, 같은 법 시행령 제2조의4제1항)."}],"개념":[{"종류":"표","제목":"주택분 종합부동산세 공제금액과 세율 구분","머리":["납세의무자","공제금액","세율·기준"],"행":[["개인 - 2주택 이하","9억원","1천분의 5 ~ 1천분의 27(7단계)"],["개인 - 3주택 이상","9억원","1천분의 5 ~ 1천분의 50(7단계)"],["1세대 1주택자","12억원","2주택 이하 세율 적용 후 연령·보유기간 공제(합계 100분의 80 한도)"],["공동명의 1주택자(9월 16일~9월 30일 신청)","12억원","1세대 1주택자로 보아 계산(제10조의2)"],["법인(공익법인등 제외)","0원","2주택 이하 1천분의 27, 3주택 이상 1천분의 50"],["신탁주택","위탁자 기준","위탁자가 납세의무자, 위탁자 체납 시 수탁자 물적납세의무"],["주택 수·세율 구간 판단 시점","해당 없음","과세기준일(6월 1일) 현재 소유 주택 수. 6월 17일 양도분도 그해 주택 수에 포함"]]},{"종류":"계산","제목":"개인 납세의무자 공시가격 합계 34억원, 주택분 종합부동산세 산출(재산세 공제 전, 가정)","단계":[{"설명":"과세표준 = (공시가격 합계 − 공제금액) × 공정시장가액비율","식":"(34억원 − 9억원) × 60%","값":"15억원"},{"설명":"3주택 이상: 12억원 초과 25억원 이하 구간 960만원 + 12억원 초과금액의 1천분의 20","식":"960만원 + (15억원 − 12억원) × 2%","값":"1,560만원"},{"설명":"2주택 이하: 12억원 초과 25억원 이하 구간 960만원 + 12억원 초과금액의 1천분의 13","식":"960만원 + (15억원 − 12억원) × 1.3%","값":"1,350만원"}]}],"함정":"3번의 6월 17일 양도는 과세기준일 6월 1일 이후다. 양도로 2주택이 줄어든 것처럼 보이지만 그해 세율을 정하는 주택 수는 6월 1일 현재로 센다. 1번과 4번은 위탁자와 수탁자의 역할을 바꾼 쌍이다. 납세의무자는 위탁자이고 수탁자는 보충적으로 신탁주택으로 책임진다. 5번은 11억원이라는 공제금액 자체가 현행 규정에 없고 시가가 아니라 공시가격을 합산한다."},"35회-2차-108":{"한줄":"별도합산과세대상 토지의 재산세로 부과된 세액은 가감조정세율·세부담 상한을 반영한 금액 그대로 토지분 별도합산세액에서 공제한다.","근거":[{"법령":"종합부동산세법","조문":"제11조","원문":"제11조(과세방법) 토지에 대한 종합부동산세는 국내에 소재하는 토지에 대하여 「지방세법」 제106조제1항제1호에 따른 종합합산과세대상(이하 \"종합합산과세대상\"이라 한다)과 같은 법 제106조제1항제2호에 따른 별도합산과세대상(이하 \"별도합산과세대상\"이라 한다)으로 구분하여 과세한다."},{"법령":"종합부동산세법","조문":"제12조제1항","원문":"①과세기준일 현재 토지분 재산세의 납세의무자로서 다음 각호의 어느 하나에 해당하는 자는 해당 토지에 대한 종합부동산세를 납부할 의무가 있다. 1. 종합합산과세대상인 경우에는 국내에 소재하는 해당 과세대상토지의 공시가격을 합한 금액이 5억원을 초과하는 자 2. 별도합산과세대상인 경우에는 국내에 소재하는 해당 과세대상토지의 공시가격을 합한 금액이 80억원을 초과하는 자"},{"법령":"종합부동산세법","조문":"제13조제1항","원문":"① 종합합산과세대상인 토지에 대한 종합부동산세의 과세표준은 납세의무자별로 해당 과세대상토지의 공시가격을 합산한 금액에서 5억원을 공제한 금액에 부동산 시장의 동향과 재정 여건 등을 고려하여 100분의 60부터 100분의 100까지의 범위에서 대통령령으로 정하는 공정시장가액비율을 곱한 금액으로 한다."},{"법령":"종합부동산세법","조문":"제14조제6항","원문":"⑥별도합산과세대상인 토지의 과세표준 금액에 대하여 해당 과세대상 토지의 토지분 재산세로 부과된 세액(「지방세법」 제111조제3항에 따라 가감조정된 세율이 적용된 경우에는 그 세율이 적용된 세액, 같은 법 제122조에 따라 세부담 상한을 적용받은 경우에는 그 상한을 적용받은 세액을 말한다)은 토지분 별도합산세액에서 이를 공제한다."},{"법령":"종합부동산세법 시행령","조문":"제2조의4제2항","원문":"② 법 제13조제1항 및 제2항에서 \"대통령령으로 정하는 공정시장가액비율\"이란 100분의 100을 말하되, 2019년부터 2021년까지 납세의무가 성립하는 종합부동산세에 대해서는 다음 각 호의 연도별 비율을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"종합합산과세대상 토지는 공시가격 합계가 5억원을 초과하는 자만 납세의무가 있다. 5억원이면 해당하지 않는다(종합부동산세법 제12조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"별도합산과세대상 토지는 공시가격 합계가 80억원을 초과하는 자만 납세의무가 있다. 80억원이면 해당하지 않는다(종합부동산세법 제12조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"토지분은 종합합산과세대상과 별도합산과세대상으로 구분해 과세한다. 분리과세대상은 종합부동산세를 과세하지 않는다(종합부동산세법 제11조)."},{"번호":4,"판정":"틀림","설명":"공제금액 5억원은 맞지만 공정시장가액비율은 100분의 60부터 100까지의 범위에서 대통령령으로 정하며 현재 100분의 100이다. 100분의 50 한도라는 규정은 없다(종합부동산세법 제13조제1항, 같은 법 시행령 제2조의4제2항)."},{"번호":5,"판정":"옳음","설명":"가감조정된 세율이나 세부담 상한이 적용된 재산세액을 그대로 토지분 별도합산세액에서 공제한다(종합부동산세법 제14조제6항)."}],"개념":[{"종류":"표","제목":"토지분 종합부동산세 비교","머리":["구분","종합합산과세대상","별도합산과세대상"],"행":[["납세의무자","공시가격 합계 5억원 초과","공시가격 합계 80억원 초과"],["공제금액","5억원","80억원"],["공정시장가액비율","100분의 60~100 범위, 현재 100분의 100","100분의 60~100 범위, 현재 100분의 100"],["세율","15억원 이하 1천분의 10, 15억원 초과 45억원 이하 1천500만원+15억원 초과분의 1천분의 20, 45억원 초과 7천500만원+45억원 초과분의 1천분의 30","200억원 이하 1천분의 5, 200억원 초과 400억원 이하 1억원+200억원 초과분의 1천분의 6, 400억원 초과 2억2천만원+400억원 초과분의 1천분의 7"],["재산세 공제","토지분 재산세로 부과된 세액을 토지분 종합합산세액에서 공제","토지분 재산세로 부과된 세액을 토지분 별도합산세액에서 공제"],["분리과세대상","종합부동산세 과세대상 아님","종합부동산세 과세대상 아님"],["신탁토지","위탁자가 납세의무자","위탁자가 납세의무자"]]},{"종류":"계산","제목":"토지분 종합부동산세 산출 예(재산세 공제 전, 가정)","단계":[{"설명":"종합합산: 공시가격 합계 25억원의 과세표준","식":"(25억원 − 5억원) × 100%","값":"20억원"},{"설명":"종합합산: 15억원 초과 45억원 이하 구간","식":"1,500만원 + (20억원 − 15억원) × 2%","값":"2,500만원"},{"설명":"별도합산: 공시가격 합계 100억원의 과세표준","식":"(100억원 − 80억원) × 100%","값":"20억원"},{"설명":"별도합산: 200억원 이하 구간","식":"20억원 × 0.5%","값":"1,000만원"}]}],"함정":"1번과 2번은 5억원과 80억원이 하한이라 '이상'으로 읽는 숫자 함정이다. 법은 초과를 요건으로 한다. 3번은 종합부동산세가 토지를 세 갈래로 나눠 과세한다고 착각하게 만든 선지다. 분리과세대상은 재산세만 낸다. 4번은 공정시장가액비율 범위를 100분의 50 한도로 바꿔 놓았다."},"35회-2차-112":{"한줄":"분리과세 주택임대소득만 있어도 종합소득 과세표준을 다음 연도 5월 1일부터 5월 31일까지 신고해야 한다.","근거":[{"법령":"소득세법","조문":"제70조제1항·제2항","원문":"① 해당 과세기간의 종합소득금액이 있는 거주자(종합소득과세표준이 없거나 결손금이 있는 거주자를 포함한다)는 그 종합소득 과세표준을 그 과세기간의 다음 연도 5월 1일부터 5월 31일까지 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 한다. ② 해당 과세기간에 분리과세 주택임대소득 및 제127조제1항제6호나목의 소득이 있는 경우에도 제1항을 적용한다."},{"법령":"소득세법","조문":"제45조제2항","원문":"② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 사업(이하 \"부동산임대업\"이라 한다)에서 발생한 결손금은 종합소득 과세표준을 계산할 때 공제하지 아니한다. 다만, 주거용 건물 임대업의 경우에는 그러하지 아니하다. 1. 부동산 또는 부동산상의 권리를 대여하는 사업 2. 공장재단 또는 광업재단을 대여하는 사업 3. 채굴에 관한 권리를 대여하는 사업으로서 대통령령으로 정하는 사업"},{"법령":"소득세법","조문":"제19조제1항제12호","원문":"12. 부동산업에서 발생하는 소득. 다만, 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 제4조에 따른 공익사업과 관련하여 지역권ㆍ지상권(지하 또는 공중에 설정된 권리를 포함한다)을 설정하거나 대여함으로써 발생하는 소득은 제외한다."},{"법령":"소득세법","조문":"제21조제1항제9호","원문":"9. 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 제4조에 따른 공익사업과 관련하여 지역권ㆍ지상권(지하 또는 공중에 설정된 권리를 포함한다)을 설정하거나 대여함으로써 발생하는 소득"},{"법령":"소득세법","조문":"제160조제4항","원문":"④ 제1항이나 제2항의 경우에 사업소득에 부동산임대업에서 발생한 소득이 포함되어 있는 사업자는 그 소득별로 구분하여 회계처리하여야 한다. 이 경우에 소득별로 구분할 수 없는 공통수입금액과 그 공통수입금액에 대응하는 공통경비는 각 총수입금액에 비례하여 그 금액을 나누어 장부에 기록한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"종합소득금액이 있는 거주자는 다음 연도 5월 1일~5월 31일에 신고한다. 분리과세 주택임대소득이 있는 경우에도 같다(소득세법 제70조제1항·제2항)."},{"번호":2,"판정":"틀림","설명":"공장재단 또는 광업재단을 대여하는 사업도 부동산임대업에 해당한다(소득세법 제45조제2항제2호)."},{"번호":3,"판정":"틀림","설명":"주거용 건물 임대업을 제외한 부동산임대업의 결손금은 종합소득 과세표준을 계산할 때 공제하지 않는다. 주거용 건물 임대업만 공제한다(소득세법 제45조제2항)."},{"번호":4,"판정":"틀림","설명":"공익사업과 관련해 지역권·지상권을 설정하거나 대여해 얻는 소득은 부동산업 사업소득에서 제외한다. 기타소득으로 본다(소득세법 제19조제1항제12호 단서, 제21조제1항제9호)."},{"번호":5,"판정":"틀림","설명":"부동산임대업 소득이 포함된 사업자는 그 소득별로 구분하여 회계처리해야 한다. 공통수입금액과 공통경비는 총수입금액에 비례해 나눈다(소득세법 제160조제4항)."}],"개념":[{"종류":"표","제목":"주택임대소득 과세(소득세법)","머리":["항목","내용","근거"],"행":[["비과세","1개의 주택을 소유하는 자의 주택임대소득. 기준시가 12억원 초과 주택과 국외 주택은 제외","제12조제2호나목"],["분리과세 대상","해당 과세기간 주택임대 총수입금액 합계가 2천만원 이하인 자의 주택임대소득","제14조제3항제7호"],["분리과세 세액","사업소득금액 × 100분의 14. 종합과세한 세액과 비교해 선택","제64조의2제1항"],["필요경비","총수입금액의 100분의 50(대통령령으로 정하는 임대주택은 100분의 60)","제64조의2제2항"],["추가 차감","분리과세 주택임대소득을 뺀 종합소득금액이 2천만원 이하이면 200만원(대통령령으로 정하는 임대주택은 400만원)","제64조의2제2항"],["신고","분리과세 주택임대소득만 있어도 다음 연도 5월 1일~5월 31일 신고","제70조제2항"],["보증금등 간주임대료","3주택 이상 소유 + 보증금등 합계 3억원 초과이면 총수입금액에 산입","제25조제1항제1호"]]},{"종류":"계산","제목":"분리과세 주택임대소득의 세액(가정: 연 총수입금액 1,800만원, 일반 임대주택)","단계":[{"설명":"분리과세 주택임대소득을 뺀 종합소득금액이 2천만원 초과: 필요경비 50%만 차감","식":"1,800만원 − 1,800만원 × 50%","값":"사업소득금액 900만원"},{"설명":"세액 = 사업소득금액 × 100분의 14","식":"900만원 × 14%","값":"126만원"},{"설명":"종합소득금액이 2천만원 이하이면 추가로 200만원 차감","식":"1,800만원 − 900만원 − 200만원","값":"사업소득금액 700만원"},{"설명":"세액 = 사업소득금액 × 100분의 14","식":"700만원 × 14%","값":"98만원"}]}],"함정":"3번은 주거용 건물 임대업과 그 밖의 부동산임대업의 결손금 처리를 뒤바꾼 선지다. 상가·토지 임대업의 결손금은 종합소득에서 공제하지 않고 이월해 부동산임대업 소득금액에서만 뺀다. 2번은 공장재단·광업재단 대여가 부동산임대업에 포함된다는 규정을 놓친 선지다. 4번은 공익사업 지역권 소득이 사업소득이 아니라 기타소득이라는 점이 관건이다. 1번은 분리과세라서 신고를 생략한다고 오해하기 쉬운데, 분리과세 주택임대소득도 확정신고 대상이다."},"35회-1차-012":{"한줄":"저량은 일정 시점에 존재하는 양이고, 주택재고가 이에 해당한다.","근거":[{"이론":"수요·공급의 변수","내용":"저량(stock)은 일정 시점에 측정하는 변수(주택재고, 인구, 자산 등), 유량(flow)은 일정 기간에 측정하는 변수(소득, 거래량, 신규공급량, 임대료 수입 등)다."}],"선지":[{"번호":1,"판정":"-","설명":"주택재고는 어느 시점에 존재하는 주택 수라서 저량이다."},{"번호":2,"판정":"-","설명":"가계소득은 일정 기간에 벌어들이는 양이므로 유량이다."},{"번호":3,"판정":"-","설명":"주택거래량은 일정 기간에 이루어진 거래 수라서 유량이다."},{"번호":4,"판정":"-","설명":"임대료 수입도 일정 기간의 수입이므로 유량이다."},{"번호":5,"판정":"-","설명":"신규주택 공급량은 일정 기간에 새로 공급되는 양이라 유량이다."}],"개념":[{"종류":"표","제목":"저량과 유량","머리":["구분","측정 방식","부동산 예"],"행":[["저량(stock)","일정 시점","주택재고, 인구, 자산, 통화량"],["유량(flow)","일정 기간","소득, 거래량, 신규 공급량, 임대료 수입, 소비, 투자"],["수요량·공급량","일정 기간","기간을 정해 말하므로 유량"],["가격","-","저량·유량 어느 쪽도 아닌 시장가격"]]},{"종류":"비교","제목":"수요의 변화와 수요량의 변화","왼쪽":{"이름":"수요의 변화","항목":["수요곡선 자체가 이동","소득·선호·인구·대체재 가격·기대 등 가격 이외 요인","소득 증가(정상재) → 오른쪽 이동"]},"오른쪽":{"이름":"수요량의 변화","항목":["같은 수요곡선 위의 점이 이동","해당 재화 가격 변화가 원인","가격 하락 → 수요량 증가"]}}],"함정":"신규주택 공급량·거래량처럼 '량'으로 끝나도 기간으로 재면 유량이다. 주택재고만 시점의 양이다."},"35회-1차-041":{"한줄":"다수의 보험계약으로 보험금을 부정하게 취득하려는 목적의 보험계약은 사회질서에 반하는 법률행위로 무효이다(제103조).","근거":[{"법령":"민법","조문":"제103조","원문":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"법령":"민법","조문":"제108조제1항","원문":"상대방과 통정한 허위의 의사표시는 무효로 한다."},{"법령":"공인중개사법","조문":"제32조제4항","원문":"주택(부속토지를 포함한다. 이하 이 항에서 같다)의 중개에 대한 보수와 제2항에 따른 실비의 한도 등에 관하여 필요한 사항은 국토교통부령으로 정하는 범위 안에서 특별시ㆍ광역시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 조례로 정하고, 주택 외의 중개대상물의 중개에 대한 보수는 국토교통부령으로 정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"한도를 넘는 중개보수 약정은 강행규정(효력규정) 위반으로 초과 부분만 무효가 될 뿐 반사회질서의 법률행위는 아니다."},{"번호":2,"판정":"틀림","설명":"강제집행을 면하려고 상대방과 짜고 허위로 근저당권을 설정하면 통정허위표시로 무효이다(제108조제1항). 반사회질서가 아니라 허위표시로 다룬다."},{"번호":3,"판정":"옳음","설명":"보험금을 부정취득할 목적으로 다수의 보험계약을 체결한 경우 그 보험계약은 사회질서에 반하여 무효이다(제103조)."},{"번호":4,"판정":"틀림","설명":"반사회적 행위로 만든 비자금을 소극적으로 숨겨 두는 임치는 반사회질서에 해당하지 않아 유효하다."},{"번호":5,"판정":"틀림","설명":"양도소득세를 줄이려고 대금을 낮게 기재해도 매매계약 자체는 유효하다. 조세포탈은 별도로 처벌한다."}],"개념":[{"종류":"표","제목":"무효 사유별 비교","머리":["무효 사유","근거","대표 예","선의 제3자 보호"],"행":[["반사회질서","제103조","보험금 부정취득 목적의 보험계약, 이중매매에 적극 가담한 매수","없음(절대적 무효)"],["불공정한 법률행위","제104조","궁박을 알고 이용한 현저히 불균형한 매매","없음(절대적 무효)"],["통정허위표시","제108조","강제집행 면탈용 허위 근저당권, 허위 매매","있음(선의 제3자에게 대항 불가)"],["효력규정 위반","개별 법령","한도를 초과한 중개보수 약정(초과 부분)","개별 사안에 따라 다름"],["유효로 보는 예","-","비자금의 소극적 은닉 임치, 다운계약서식 매매대금 기재","-"]]}],"함정":"허위 근저당권은 제108조의 통정허위표시로 무효가 되고 선의 제3자가 보호된다. 반사회질서 무효에는 이런 보호가 없다. 선지 1은 초과 부분만 무효가 되는 효력규정 위반이다."},"35회-1차-046":{"한줄":"상대방이 정당한 이유 없이 수령을 거절한 경우에는 그 내용을 알 수 있는 객관적 상태에 놓인 때 의사표시가 도달한 것으로 본다.","근거":[{"법령":"민법","조문":"제111조","원문":"① 상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생긴다.\n② 의사표시자가 그 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제112조","원문":"의사표시의 상대방이 의사표시를 받은 때에 제한능력자인 경우에는 의사표시자는 그 의사표시로써 대항할 수 없다. 다만, 그 상대방의 법정대리인이 의사표시가 도달한 사실을 안 후에는 그러하지 아니하다."},{"판례":"대법원 판례","요지":"도달은 상대방이 의사표시의 내용을 알 수 있는 객관적 상태에 놓인 것을 뜻하고 내용을 실제로 알아야 하는 것은 아니다. 등기우편으로 발송된 것이 증명되면 특별한 사정이 없는 한 상당한 기간 내에 도달한 것으로 추정된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"발신 후 표의자가 사망해도 의사표시의 효력에는 영향이 없다(제111조제2항)."},{"번호":2,"판정":"틀림","설명":"상대방이 받을 때 제한능력자이면 의사표시자는 그 의사표시로 대항할 수 없다(제112조). 법정대리인이 도달 사실을 안 뒤에는 대항할 수 있다."},{"번호":3,"판정":"틀림","설명":"도달은 상대방이 알 수 있는 객관적 상태에 놓이면 충분하다. 상대방이 실제로 내용을 알 필요는 없다."},{"번호":4,"판정":"틀림","설명":"등기우편은 발송 사실이 증명되면 상당한 기간 내 도달한 것으로 추정된다."},{"번호":5,"판정":"옳음","설명":"수령을 정당한 이유 없이 거절한 경우에도 상대방이 내용을 알 수 있는 객관적 상태에 놓인 때 효력이 생긴다."}],"개념":[{"종류":"표","제목":"의사표시의 효력발생 정리","머리":["상황","효력","근거"],"행":[["상대방 있는 의사표시","상대방에게 도달한 때(도달주의)","제111조제1항"],["발송 후 표의자의 사망·제한능력","효력에 영향 없음","제111조제2항"],["수령 당시 상대방이 제한능력자","의사표시자는 대항 불가, 법정대리인이 안 뒤에는 가능","제112조"],["수령 거절","알 수 있는 객관적 상태에 놓인 때 도달","판례"],["등기우편 발송","상당한 기간 내 도달 추정","판례"]]},{"종류":"표","제목":"도달주의의 예외(발신주의)","머리":["제도","발신주의가 적용되는 내용","근거"],"행":[["제한능력자 상대방의 확답 촉구","능력자가 된 사람이 기간 내에 확답을 발송하지 않으면 추인한 것으로 봄","제15조"],["사단법인 총회 소집","1주간 전에 목적사항을 적은 통지를 발송","제71조"],["격지자 간 계약의 성립","승낙의 통지를 발송한 때 성립","제531조"]]}],"함정":"도달은 상대방이 내용을 이해한 시점이 아니라 알 수 있는 객관적 상태에 놓인 시점이다. 상대방이 제한능력자일 때는 표의자가 효력을 주장하지 못한다는 점(제112조)이 선지 2의 반대 내용이다."},"35회-1차-054":{"한줄":"甲은 乙에게 대금을 받고 토지를 인도하였으므로 乙은 점유할 권리가 있고, 甲의 소유물반환청구는 제213조 단서에 막힌다.","근거":[{"법령":"민법","조문":"제213조","원문":"소유자는 그 소유에 속한 물건을 점유한 자에 대하여 반환을 청구할 수 있다. 그러나 점유자가 그 물건을 점유할 권리가 있는 때에는 반환을 거부할 수 있다."},{"법령":"부동산등기 특별조치법","조문":"제8조제1호","원문":"조세부과를 면하려 하거나 다른 시점간의 가격변동에 따른 이득을 얻으려 하거나 소유권등 권리변동을 규제하는 법령의 제한을 회피할 목적으로 제2조제2항 또는 제3항의 규정에 위반한 때"},{"판례":"대법원 판례","요지":"순차 매매에서 세 당사자가 중간생략등기에 합의하면 최종 매수인은 최초 매도인에게 직접 이전등기를 청구할 수 있다. 중간생략등기 합의는 단속규정 위반이어도 사법상 유효하다. 매수인이 목적물을 인도받아 사용·수익하는 동안에는 이전등기청구권의 소멸시효가 진행하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"丙은 乙에게서 매수하여 인도받은 점유자로서 점유할 권리가 있어 甲의 반환청구에 대항할 수 있다(제213조 단서)."},{"번호":2,"판정":"옳음","설명":"乙은 대금을 지급하고 인도받은 매수인으로서 점유할 권리가 있어 甲은 소유물반환을 청구할 수 없다."},{"번호":3,"판정":"틀림","설명":"甲·乙·丙 3자 합의가 있으므로 丙은 甲에게 직접 이전등기를 청구할 수 있다."},{"번호":4,"판정":"틀림","설명":"丙은 乙의 甲에 대한 이전등기청구권을 대위행사할 수 있다."},{"번호":5,"판정":"틀림","설명":"매수인이 목적물을 인도받아 사용·수익하는 동안에는 이전등기청구권의 소멸시효가 진행하지 않는다."}],"개념":[{"종류":"표","제목":"중간생략등기","머리":["쟁점","내용"],"행":[["의의","甲→乙→丙으로 순차 매매한 부동산을 중간 등기 없이 甲에서 丙으로 바로 등기하는 것"],["이미 마친 중간생략등기","실체관계에 부합하면 유효(판례)"],["3자 합의가 있는 경우","丙이 甲에게 직접 이전등기 청구 가능"],["3자 합의가 없는 경우","丙은 甲에게 직접 청구할 수 없고, 乙의 이전등기청구권을 대위행사해야 함"],["처벌","조세 회피 등의 목적으로 부동산등기 특별조치법 제2조제2항 등을 위반하면 처벌(제8조제1호), 합의의 사법상 효력은 유효"]]},{"종류":"표","제목":"이전등기청구권의 소멸시효","머리":["상황","시효 진행 여부"],"행":[["매수인이 목적물을 인도받아 점유·사용 중","진행하지 않음(판례)"],["매수인이 점유를 타인에게 양도한 뒤","양도 시부터 진행(판례)"],["매수인이 인도받지 않은 경우","권리를 행사할 수 있는 때부터 진행"]]}],"함정":"매수인이 인도받아 사용·수익하는 동안에는 이전등기청구권의 소멸시효가 진행하지 않으므로 10년이 지나도 청구할 수 있다. 선지 1은 丙의 점유할 권리(제213조 단서)를 놓치면 틀린다."},"35회-1차-065":{"한줄":"임대차는 임대인이 사용·수익하게 할 의무를, 임차인이 차임을 지급할 의무를 서로 대가로 부담하는 유상계약이다.","근거":[{"법령":"민법","조문":"제618조","원문":"임대차는 당사자 일방이 상대방에게 목적물을 사용, 수익하게 할 것을 약정하고 상대방이 이에 대하여 차임을 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제563조","원문":"매매는 당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 그 대금을 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제664조","원문":"도급은 당사자 일방이 어느 일을 완성할 것을 약정하고 상대방이 그 일의 결과에 대하여 보수를 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제596조","원문":"교환은 당사자 쌍방이 금전 이외의 재산권을 상호이전할 것을 약정함으로써 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"틀림","설명":"매매는 합의만으로 성립하는 낙성계약이다(제563조). 물건 인도가 있어야 성립하는 요물계약이 아니다."},{"번호":2,"판정":"틀림","설명":"도급은 일의 완성과 보수 지급이 서로 대가인 쌍무계약이다(제664조)."},{"번호":3,"판정":"틀림","설명":"교환은 서로 재산권을 이전하는 유상계약이다(제596조)."},{"번호":4,"판정":"틀림","설명":"증여는 일정한 방식을 요하지 않는 불요식계약이다. 서면이 없으면 각 당사자가 해제할 수 있을 뿐이다(제555조)."},{"번호":5,"판정":"옳음","설명":"임대차는 사용·수익과 차임이 대가 관계에 있는 유상계약이며 쌍무계약이다(제618조)."}],"개념":[{"종류":"표","제목":"전형계약의 성질 분류","머리":["계약","쌍무·편무","유상·무상","낙성·요물","근거"],"행":[["매매","쌍무","유상","낙성","제563조"],["교환","쌍무","유상","낙성","제596조"],["임대차","쌍무","유상","낙성","제618조"],["도급","쌍무","유상","낙성","제664조"],["증여","편무","무상","낙성","제554조"],["사용대차","편무","무상","낙성","제609조"],["무상임치","편무","무상","낙성","제693조"],["현상광고(통설)","편무","-","요물","제675조"]]}],"함정":"증여를 요식계약으로, 도급을 편무계약으로 오인하는 선지가 자주 나온다. 서면은 증여의 성립요건이 아니라 해제를 막는 요건이다. 매매를 요물계약으로 쓴 선지도 대표적인 오답이다."},"35회-1차-077":{"한줄":"담보가등기권자가 소유권을 취득해도 선순위 저당권은 소멸하지 않고, 가등기권자는 그 부담을 안은 채 소유권을 얻는다.","근거":[{"법령":"가등기담보 등에 관한 법률","조문":"제4조제1항","원문":"채권자는 제3조제1항에 따른 통지 당시의 담보목적부동산의 가액에서 그 채권액을 뺀 금액(이하 \"청산금\"이라 한다)을 채무자등에게 지급하여야 한다. 이 경우 담보목적부동산에 선순위담보권(先順位擔保權) 등의 권리가 있을 때에는 그 채권액을 계산할 때에 선순위담보 등에 의하여 담보된 채권액을 포함한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제4조제3항","원문":"청산금의 지급채무와 부동산의 소유권이전등기 및 인도채무(引渡債務)의 이행에 관하여는 동시이행의 항변권(抗辯權)에 관한 「민법」 제536조를 준용한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제15조","원문":"담보가등기를 마친 부동산에 대하여 강제경매등이 행하여진 경우에는 담보가등기권리는 그 부동산의 매각에 의하여 소멸한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"丙의 선순위 저당권은 甲이 소유권을 취득해도 소멸하지 않는다. 청산금 계산 때 丙의 채권액 5,000만원이 공제될 뿐이다(제4조제1항)."},{"번호":2,"판정":"옳음","설명":"청산금을 지급하지 않고 마친 본등기는 무효다(판례)."},{"번호":3,"판정":"옳음","설명":"청산금 지급채무와 본등기·인도채무는 동시이행관계다(제4조제3항)."},{"번호":4,"판정":"옳음","설명":"담보가등기를 마친 부동산이 경매로 매각되면 담보가등기권리는 소멸한다(제15조)."},{"번호":5,"판정":"옳음","설명":"청산금이 없는 경우 청산기간 2개월이 지나면 사용·수익권이 채권자에게 귀속된다(판례)."}],"개념":[{"종류":"흐름","제목":"가등기담보권 실행(귀속정산)","단계":[{"이름":"변제기 도래","설명":"채무자가 변제하지 않음. 채권자는 변제기 후에 실행 통지"},{"이름":"청산금 평가액 통지","설명":"채무자등에게 통지, 통지 당시 부동산 평가액과 채권액을 밝힘. 청산금이 없다고 인정되면 그 뜻을 통지"},{"이름":"청산기간 2개월","설명":"통지가 도달한 날부터 2개월이 지나야 함(제3조제1항)"},{"이름":"청산금 지급","설명":"청산금 = 평가액 - 채권액(선순위 담보채권 포함). 청산금 지급과 본등기·인도는 동시이행"},{"이름":"소유권 취득","설명":"가등기담보는 청산기간이 지나야 본등기 청구 가능(제4조제2항)"}]},{"종류":"표","제목":"이 문항의 청산금 계산","머리":["항목","금액","설명"],"행":[["부동산 평가액","2억원","통지 당시 가액"],["甲의 채권액","1억원","무이자 대여금"],["선순위 저당권 피담보채권","5,000만원","채권액 계산에 포함(제4조제1항)"],["청산금","5,000만원","2억 - (1억 + 5,000만원)"],["丙의 저당권","존속","甲이 소유권을 취득해도 소멸하지 않음"],["경매로 매각될 때 甲의 가등기","소멸","제15조"]]}],"함정":"담보가등기권자가 소유권을 취득하면 저당권이 정리된다고 생각하기 쉽다. 선순위 저당권은 존속하고 청산금 계산에서 공제될 뿐이다. 경매가 되면 담보가등기가 소멸한다는 제15조와 구분해서 정리한다."},"35회-2차-002":{"한줄":"법인은 주택의 '임대관리'는 할 수 있어도 '임대업' 자체는 법 제14조제1항에 열거되지 않아 할 수 없다.","근거":[{"법령":"공인중개사법","조문":"제14조제1항","원문":"법인인 개업공인중개사는 다른 법률에 규정된 경우를 제외하고는 중개업 및 다음 각 호에 규정된 업무와 제2항에 규정된 업무 외에 다른 업무를 함께 할 수 없다. 1. 상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행 2. 부동산의 이용ㆍ개발 및 거래에 관한 상담 3. 개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공 4. 상업용 건축물 및 주택의 분양대행 5. 그 밖에 중개업에 부수되는 업무로서 대통령령으로 정하는 업무"},{"법령":"공인중개사법 시행령","조문":"제17조제2항","원문":"법 제14조제1항제5호에서 \"대통령령이 정하는 업무\"라 함은 중개의뢰인의 의뢰에 따른 도배ㆍ이사업체의 소개 등 주거이전에 부수되는 용역의 알선을 말한다."}],"선지":[{"번호":1,"판정":"-","설명":"임대업은 열거 업무가 아니라 겸업할 수 없다. 열거된 것은 임대관리 등 관리대행이다(법 제14조제1항제1호)."},{"번호":2,"판정":"-","설명":"분양대행은 겸업할 수 있다(법 제14조제1항제4호)."},{"번호":3,"판정":"-","설명":"이용·개발 및 거래에 관한 상담은 겸업할 수 있다(법 제14조제1항제2호)."},{"번호":4,"판정":"-","설명":"도배·이사업체 소개는 영 제17조제2항에 따라 겸업할 수 있다(법 제14조제1항제5호)."},{"번호":5,"판정":"-","설명":"개업공인중개사 대상 경영기법·경영정보 제공은 겸업할 수 있다(법 제14조제1항제3호)."}],"개념":[{"종류":"표","제목":"법인인 개업공인중개사가 중개업과 함께 할 수 있는 업무","머리":["구분","업무","근거"],"행":[["1호","상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행","법 제14조제1항제1호"],["2호","부동산의 이용·개발 및 거래에 관한 상담","법 제14조제1항제2호"],["3호","개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공","법 제14조제1항제3호"],["4호","상업용 건축물 및 주택의 분양대행","법 제14조제1항제4호"],["5호","중개업에 부수되는 업무: 도배·이사업체 소개 등 주거이전에 부수되는 용역의 알선","법 제14조제1항제5호, 영 제17조제2항"],["제2항","경매·공매 대상 부동산의 권리분석·취득 알선, 매수신청·입찰신청 대리","법 제14조제2항"]]},{"종류":"비교","제목":"겸업 제한과 위반 효과","왼쪽":{"이름":"겸업 제한 대상","항목":["법인인 개업공인중개사만 해당(법 제14조제1항)","개인인 개업공인중개사는 이 조항의 겸업 제한이 없음","경매 매수신청 대리는 법원에 등록하고 감독을 받음(법 제14조제3항)"]},"오른쪽":{"이름":"위반 시","항목":["개설등록 취소 가능(법 제38조제2항제4호)","6개월 범위 업무정지 가능(법 제39조제1항제11호)","청문 대상(법 제38조제3항)"]}}],"함정":"임대'관리'(관리대행)와 임대'업'은 다르다. 관리대행은 남의 부동산을 맡아 관리하는 일이라 열거 업무이고, 자기 주택을 임대하는 임대업은 열거에 없다."},"35회-2차-014":{"한줄":"거짓이나 그 밖의 부정한 방법으로 개설등록을 한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.","근거":[{"법령":"공인중개사법","조문":"제48조","원문":"다음 각 호의 어느 하나에 해당하는 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.\n2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 자"},{"법령":"공인중개사법","조문":"제49조","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n4. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자\n5. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자"}],"선지":[{"번호":1,"판정":"옳음","설명":"제48조제2호에 따라 3년 이하의 징역 또는 3천만원 이하의 벌금이다."},{"번호":2,"판정":"틀림","설명":"자기 성명으로 중개업무를 하게 하는 행위(제7조제1항 위반)는 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제1호)."},{"번호":3,"판정":"틀림","설명":"둘 이상의 중개사무소를 두면 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제4호)."},{"번호":4,"판정":"틀림","설명":"임시 중개시설물 설치는 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제5호)."},{"번호":5,"판정":"틀림","설명":"공인중개사 유사명칭 사용(제8조 위반)은 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제2호)."}],"개념":[{"종류":"표","제목":"3년 이하 징역·3천만원 이하 벌금 - 법 제48조","머리":["호","사유"],"행":[["1","무등록 중개업"],["2","거짓이나 그 밖의 부정한 방법으로 개설등록"],["3","금지행위 제33조제1항 제5~9호 위반"],["4","시세 부당 영향 목적의 업무방해(제33조제2항)"]]},{"종류":"표","제목":"1년 이하 징역·1천만원 이하 벌금 - 법 제49조제1항(주요 사유)","머리":["호","사유"],"행":[["1","자격증 양도·대여, 성명 사용하게 함, 양수·대여받음"],["2","공인중개사 유사명칭 사용"],["3","이중등록, 둘 이상의 중개사무소 소속"],["4","둘 이상의 중개사무소"],["5","임시 중개시설물"],["5의2","중개보조원 고용 한도 초과"],["7","등록증 대여·양도, 타인 성명·상호 사용"],["8","부동산거래정보망 정보 공개 위반(제24조제4항)"],["9","업무상 비밀 누설(피해자 명시 의사에 반하여 벌하지 않음)"],["10","금지행위 제33조제1항 제1~4호"]]}],"함정":"이중등록·이중 사무소·임시 시설물·명칭 사용은 등록취소 사유라서 무거워 보이지만 형사처벌은 1년 이하이다. 3년 이하는 무등록 중개업, 부정 등록, 금지행위 5~9호로 외운다."},"35회-2차-026":{"한줄":"신축으로 취득하는 것은 계약 외의 원인이라 취득한 날부터 6개월 이내에 신고한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제2조","원문":"2. 정부간 기구"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제8조","원문":"① 외국인등이 대한민국 안의 부동산등을 취득하는 계약(제3조제1항 각 호에 따른 계약은 제외한다)을 체결하였을 때에는 계약체결일부터 60일 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다.\n② 외국인등이 상속ㆍ경매, 그 밖에 대통령령으로 정하는 계약 외의 원인으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다.\n③ 대한민국 안의 부동산등을 가지고 있는 대한민국국민이나 대한민국의 법령에 따라 설립된 법인 또는 단체가 외국인등으로 변경된 경우 그 외국인등이 해당 부동산등을 계속보유하려는 경우에는 외국인등으로 변경된 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제5조","원문":"② 법 제8조제2항에서 \"대통령령으로 정하는 계약 외의 원인\"이란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.\n4. 건축물의 신축ㆍ증축ㆍ개축ㆍ재축"}],"선지":[{"번호":1,"판정":"옳음","설명":"정부간 기구는 외국인등에 해당하는 국제기구이다(시행령 제2조제2호, 법 제2조제4호사목)."},{"번호":2,"판정":"틀림","설명":"건축물의 신축은 계약 외의 원인이므로 취득한 날부터 6개월 이내에 신고한다(법 제8조제2항, 시행령 제5조제2항제4호). 60일은 계약으로 취득할 때의 기한이다."},{"번호":3,"판정":"옳음","설명":"교환계약은 거래신고 대상 계약(법 제3조제1항 각 호)이 아니므로 계약으로 취득하는 경우로서 계약체결일부터 60일 이내에 취득신고한다(법 제8조제1항)."},{"번호":4,"판정":"옳음","설명":"외국인등도 거래당사자에 포함되므로 매매계약은 법 제3조에 따른 부동산 거래신고 대상이다(법 제2조제3호)."},{"번호":5,"판정":"옳음","설명":"국민이 외국인등으로 변경된 경우 변경된 날부터 6개월 이내에 계속보유신고를 한다(법 제8조제3항)."}],"개념":[{"종류":"표","제목":"외국인등의 부동산 취득·보유 신고","머리":["취득 원인","기한","근거"],"행":[["거래신고 대상 계약(매매 등)","계약체결일부터 30일 이내 부동산 거래신고","법 제3조"],["그 외 계약(교환·증여 등)","계약체결일부터 60일 이내 취득신고","법 제8조제1항"],["상속·경매","취득한 날부터 6개월 이내","같은 조 제2항"],["환매권 행사, 법원의 확정판결, 법인의 합병, 건축물의 신축·증축·개축·재축","취득한 날부터 6개월 이내","시행령 제5조제2항"],["국민·내국법인이 외국인등으로 변경","변경된 날부터 6개월 이내 계속보유신고","법 제8조제3항"]]},{"종류":"표","제목":"외국인등 해당 유형","머리":["유형","내용"],"행":[["개인","대한민국 국적이 없는 개인"],["법인·단체","외국 법령에 따라 설립, 사원·임원 1/2 이상이 외국인, 외국인·외국법인이 자본금·의결권 1/2 이상 보유"],["정부","외국 정부"],["국제기구","국제연합과 그 산하기구·전문기구, 정부간 기구, 준정부간 기구, 비정부간 국제기구"]]}],"함정":"신고기한 60일과 6개월을 취득 원인으로 가르는 문제다. 매매는 거래신고 30일, 교환·증여는 취득신고 60일, 상속·경매·신축 등은 6개월이다."},"35회-2차-032":{"한줄":"구분소유자는 전유부분이나 공용부분을 보존하거나 개량하기 위해 필요한 범위에서 다른 구분소유자의 전유부분의 사용을 청구할 수 있고, 손해가 생기면 보상한다.","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제5조","원문":"③ 구분소유자는 그 전유부분이나 공용부분을 보존하거나 개량하기 위하여 필요한 범위에서 다른 구분소유자의 전유부분 또는 자기의 공유(共有)에 속하지 아니하는 공용부분의 사용을 청구할 수 있다. 이 경우 다른 구분소유자가 손해를 입었을 때에는 보상하여야 한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제6조","원문":"전유부분이 속하는 1동의 건물의 설치 또는 보존의 흠으로 인하여 다른 자에게 손해를 입힌 경우에는 그 흠은 공용부분에 존재하는 것으로 추정한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제7조","원문":"대지사용권을 가지지 아니한 구분소유자가 있을 때에는 그 전유부분의 철거를 청구할 권리를 가진 자는 그 구분소유자에 대하여 구분소유권을 시가(時價)로 매도할 것을 청구할 수 있다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제8조","원문":"대지 위에 구분소유권의 목적인 건물이 속하는 1동의 건물이 있을 때에는 그 대지의 공유자는 그 건물 사용에 필요한 범위의 대지에 대하여는 분할을 청구하지 못한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제10조","원문":"① 공용부분은 구분소유자 전원의 공유에 속한다. 다만, 일부의 구분소유자만이 공용하도록 제공되는 것임이 명백한 공용부분(이하 \"일부공용부분\"이라 한다)은 그들 구분소유자의 공유에 속한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"일부공용부분은 그들 일부 구분소유자의 공유에 속한다(제10조제1항 단서)."},{"번호":2,"판정":"틀림","설명":"대지 위에 구분소유권의 목적인 건물이 있으면 건물 사용에 필요한 범위의 대지에 대한 분할을 청구하지 못한다(제8조)."},{"번호":3,"판정":"옳음","설명":"보존·개량을 위해 필요한 범위에서 다른 구분소유자의 전유부분 사용을 청구할 수 있고, 손해를 입은 구분소유자에게는 보상한다(제5조제3항)."},{"번호":4,"판정":"틀림","설명":"흠은 공용부분에 존재하는 것으로 추정한다(제6조)."},{"번호":5,"판정":"틀림","설명":"매도청구의 내용은 대지사용권 매도가 아니라 전유부분의 철거를 청구할 권리를 가진 자가 대지사용권 없는 구분소유자에게 구분소유권을 시가로 매도하라고 청구하는 것이다(제7조)."}],"개념":[{"종류":"표","제목":"집합건물법 조문별 핵심","머리":["조문","내용"],"행":[["제5조제3항","보존·개량에 필요한 범위에서 다른 구분소유자의 전유부분 사용 청구, 손해 보상"],["제6조","설치·보존상의 흠은 공용부분에 있는 것으로 추정"],["제7조","전유부분 철거청구권자가 대지사용권 없는 구분소유자에게 구분소유권을 시가로 매도 청구"],["제8조","대지공유자의 건물 사용에 필요한 범위 분할청구 금지"],["제10조제1항","공용부분은 전원 공유, 일부공용부분은 그들 구분소유자 공유"]]},{"종류":"비교","제목":"매도청구의 방향","왼쪽":{"이름":"제7조 구분소유권 매도청구","항목":["청구하는 사람: 전유부분의 철거를 청구할 권리를 가진 자","청구 상대방: 대지사용권 없는 구분소유자","목적물: 구분소유권, 가격은 시가"]},"오른쪽":{"이름":"오답 방향","항목":["대지사용권 없는 구분소유자가 대지사용권자에게 대지사용권 매도 청구(제7조는 그 반대)"]}}],"함정":"제6조는 \"공용부분\"에 흠이 있는 것으로 추정하고, 제7조는 대지사용권 없는 쪽에서 청구하지 않고 그 상대방이 청구한다. 제8조는 분할청구 금지, 제10조는 일부공용부분의 귀속이다."},"35회-2차-030":{"한줄":"제3자가 권리를 취득할 때 경매신청이나 압류가 있다는 것을 알았다면 압류에 대항하지 못한다.","근거":[{"법령":"민사집행법","조문":"제83조","원문":"①경매절차를 개시하는 결정에는 동시에 그 부동산의 압류를 명하여야 한다.\n②압류는 부동산에 대한 채무자의 관리ㆍ이용에 영향을 미치지 아니한다."},{"법령":"민사집행법","조문":"제92조","원문":"①제3자는 권리를 취득할 때에 경매신청 또는 압류가 있다는 것을 알았을 경우에는 압류에 대항하지 못한다."},{"법령":"민사집행법","조문":"제88조","원문":"①집행력 있는 정본을 가진 채권자, 경매개시결정이 등기된 뒤에 가압류를 한 채권자, 민법ㆍ상법, 그 밖의 법률에 의하여 우선변제청구권이 있는 채권자는 배당요구를 할 수 있다."},{"법령":"민사집행법","조문":"제86조","원문":"①이해관계인은 매각대금이 모두 지급될 때까지 법원에 경매개시결정에 대한 이의신청을 할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"경매개시결정에는 동시에 압류를 명한다(제83조제1항)."},{"번호":2,"판정":"옳음","설명":"압류는 채무자의 관리·이용에 영향을 미치지 않는다(제83조제2항)."},{"번호":3,"판정":"틀림","설명":"알았을 경우에는 압류에 대항하지 못한다(제92조제1항)."},{"번호":4,"판정":"옳음","설명":"경매개시결정이 등기된 뒤에 가압류를 한 채권자는 배당요구를 할 수 있다(제88조제1항)."},{"번호":5,"판정":"옳음","설명":"이해관계인은 매각대금이 모두 지급될 때까지 경매개시결정에 대한 이의신청을 할 수 있다(제86조제1항)."}],"개념":[{"종류":"흐름","제목":"강제경매 절차","단계":[{"이름":"개시결정","설명":"경매개시결정과 동시에 압류 명령. 법원사무관등이 즉시 등기 촉탁(제83조·제94조)"},{"이름":"배당요구의 종기","설명":"압류 효력 발생 때부터 1주 이내 결정·공고. 종기는 첫 매각기일 이전(제84조)"},{"이름":"매각기일","설명":"매각물건명세서 작성(제105조). 호가경매, 기일입찰, 기간입찰 중 법원이 정한 방법(제103조)"},{"이름":"매각결정기일","설명":"매각기일부터 1주 이내(제109조). 허가·불허가 결정 선고, 확정되어야 효력(제126조)"},{"이름":"대금 납부","설명":"매각허가결정 확정 후 대금지급기한 통지, 대금을 다 낸 때 권리 취득(제142조·제135조)"},{"이름":"배당","설명":"배당받을 채권자는 제148조 각 호의 채권자"}]},{"종류":"표","제목":"배당받을 채권자(제148조)·배당요구 가능 채권자(제88조)","머리":["구분","내용"],"행":[["제148조제1호","배당요구의 종기까지 경매신청한 압류채권자"],["제148조제2호","배당요구의 종기까지 배당요구한 채권자"],["제148조제3호","첫 경매개시결정등기 전에 등기된 가압류채권자"],["제148조제4호","첫 경매개시결정등기 전에 등기되고 매각으로 소멸하는 저당권·전세권 등 우선변제청구권자"],["제88조제1항","집행력 있는 정본을 가진 채권자, 개시결정 등기 후 가압류채권자, 법률상 우선변제청구권자는 배당요구 가능"]]}],"함정":"제92조제1항은 \"알았을 경우 대항하지 못한다\"는 문장이다. 알지 못했을 때를 뒤집어 외우면 3번을 맞다고 본다. 가압류채권자는 등기 시점에 따라 당연 배당(제148조제3호)과 배당요구(제88조)로 갈린다."},"35회-2차-042":{"한줄":"농림지역에서 상수원보호구역을 지정하는 경우는 법이 국토교통부장관의 승인 대상에서 빼 두었다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제8조제2항","원문":"② 중앙행정기관의 장이나 지방자치단체의 장은 다른 법률에 따라 지정되는 구역등 중 대통령령으로 정하는 면적 이상의 구역등을 지정하거나 변경하려면 중앙행정기관의 장은 국토교통부장관과 협의하여야 하며 지방자치단체의 장은 국토교통부장관의 승인을 받아야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제8조제4항","원문":"④ 제2항 및 제3항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부장관과의 협의를 거치지 아니하거나 국토교통부장관 또는 시ㆍ도지사의 승인을 받지 아니한다.\n1. 다른 법률에 따라 지정하거나 변경하려는 구역등이 도시ㆍ군기본계획에 반영된 경우\n2. 제36조에 따른 보전관리지역ㆍ생산관리지역ㆍ농림지역 또는 자연환경보전지역에서 다음 각 목의 지역을 지정하려는 경우\n다. 「수도법」 제7조에 따른 상수원보호구역"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"시행령 제5조제1항·제5항","원문":"①법 제8조제2항에서 \"대통령령으로 정하는 면적\"이란 1제곱킬로미터(「도시개발법」에 의한 도시개발구역의 경우에는 5제곱킬로미터)를 말한다.\n⑤법 제8조제4항제4호에서 \"대통령령으로 정하는 범위에서 변경하려는 경우\"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.\n1. 협의 또는 승인을 얻은 지역ㆍ지구ㆍ구역 또는 구획 등(이하 \"구역등\"이라 한다)의 면적의 10퍼센트의 범위안에서 면적을 증감시키는 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"국토교통부장관의 협의·승인 대상은 1제곱킬로미터(도시개발구역은 5제곱킬로미터) 이상이다. 1제곱킬로미터 미만이면 승인이 필요 없다(법 제8조제2항, 영 제5조제1항)."},{"번호":2,"판정":"틀림","설명":"보전관리지역·생산관리지역·농림지역·자연환경보전지역에서 「수도법」 상수원보호구역을 지정하는 경우는 승인을 받지 않는다(법 제8조제4항제2호다목)."},{"번호":3,"판정":"옳음","설명":"구역이 도시·군기본계획에 반영된 경우는 협의·승인 대상이 아니다(법 제8조제4항제1호)."},{"번호":4,"판정":"옳음","설명":"승인받은 구역 면적의 10퍼센트 범위에서 증감하는 변경은 다시 승인받지 않는다(법 제8조제4항제4호, 영 제5조제5항제1호)."},{"번호":5,"판정":"옳음","설명":"구역을 변경하거나 해제하려면 도시·군관리계획 입안권자의 의견을 듣는다(법 제8조제6항)."}],"개념":[{"종류":"표","제목":"다른 법률에 따른 구역 지정의 협의·승인(법 제8조)","머리":["구분","내용"],"행":[["대상 면적","1㎢ 이상(도시개발구역은 5㎢ 이상). 중앙행정기관은 국토교통부장관과 협의, 지방자치단체는 승인(제8조②, 영 제5조①)"],["승인권자","5㎢ 미만은 시·도지사가 시·도도시계획위원회 심의를 거쳐 지정하면 국토교통부장관 승인이 없고, 시장·군수·구청장은 시·도지사 승인(제8조③, 영 제5조③)"],["심의","국토교통부장관 또는 시·도지사가 협의·승인할 때 도시계획위원회 심의(제8조⑤)"],["변경·해제","도시·군관리계획 입안권자의 의견을 듣는다(제8조⑥)"]]},{"종류":"표","제목":"협의·승인이 필요 없는 경우(법 제8조제4항)","머리":["호","내용"],"행":[["1호","구역이 도시·군기본계획에 반영된 경우"],["2호","보전관리·생산관리·농림·자연환경보전지역에서 농업진흥지역, 수변구역, 상수원보호구역, 생태·경관보전지역, 야생생물 특별보호구역, 해양보호구역을 지정하는 경우"],["3호","군사상 기밀을 지켜야 할 구역"],["4호","협의·승인받은 구역을 영 제5조제5항 범위에서 변경(면적 10% 범위의 증감, 면적산정 착오 정정)"]]}],"함정":"1제곱킬로미터 기준과 농림지역의 상수원보호구역 예외가 같이 나온다. 상수원보호구역이라는 이름만 보고 승인 대상으로 생각하기 쉽다."},"35회-2차-052":{"한줄":"건폐율을 30퍼센트 이하까지 완화할 수 있는 지역은 생산관리지역, 농림지역, 생산녹지지역, 자연녹지지역이다. 보전녹지지역은 해당하지 않는다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제75조의3제2항·제3항","원문":"② 성장관리계획구역에서는 제77조제1항에도 불구하고 다음 각 호의 구분에 따른 범위에서 성장관리계획으로 정하는 바에 따라 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 조례로 정하는 비율까지 건폐율을 완화하여 적용할 수 있다.\n1. 계획관리지역: 50퍼센트 이하\n2. 생산관리지역ㆍ농림지역 및 대통령령으로 정하는 녹지지역: 30퍼센트 이하\n③ 성장관리계획구역 내 계획관리지역에서는 제78조제1항에도 불구하고 125퍼센트 이하의 범위에서 성장관리계획으로 정하는 바에 따라 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 조례로 정하는 비율까지 용적률을 완화하여 적용할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"영 제70조의14제2항","원문":"② 법 제75조의3제2항제2호에서 \"대통령령으로 정하는 녹지지역\"이란 자연녹지지역과 생산녹지지역을 말한다."}],"선지":[{"번호":1,"판정":"-","설명":"생산관리지역은 30퍼센트 이하로 완화할 수 있는 지역이다(법 제75조의3제2항제2호)."},{"번호":2,"판정":"-","설명":"생산녹지지역은 영 제70조의14제2항이 정한 녹지지역이어서 30퍼센트 이하 완화가 가능하다."},{"번호":3,"판정":"-","설명":"보전녹지지역은 완화 대상 녹지지역(자연녹지·생산녹지)에 들지 않는다. 정답이다."},{"번호":4,"판정":"-","설명":"자연녹지지역은 영 제70조의14제2항의 대상 녹지지역이다."},{"번호":5,"판정":"-","설명":"농림지역은 30퍼센트 이하 완화 지역이다(법 제75조의3제2항제2호)."}],"개념":[{"종류":"표","제목":"성장관리계획구역의 건폐율·용적률 완화(법 제75조의3)","머리":["용도지역","건폐율 완화 한도","용적률"],"행":[["계획관리지역","50% 이하","125% 이하까지 완화 가능(제75조의3③)"],["생산관리지역","30% 이하","해당 없음"],["농림지역","30% 이하","해당 없음"],["자연녹지지역·생산녹지지역","30% 이하(영 제70조의14②)","해당 없음"],["보전녹지지역","완화 대상 아님","해당 없음"]]},{"종류":"흐름","제목":"성장관리계획구역 지정 절차","단계":[{"이름":"지정 대상","설명":"녹지지역, 관리지역, 농림지역, 자연환경보전지역 중 개발수요가 많은 지역 등(법 제75조의2①)"},{"이름":"주민·의회 의견","설명":"공고 후 14일 이상 열람, 지방의회 의견은 60일 이내(영 제70조의13, 법 제75조의2③)"},{"이름":"협의·심의","설명":"관계 행정기관 협의(30일 이내 의견) 및 지방도시계획위원회 심의(법 제75조의2②④)"},{"이름":"고시·열람","설명":"고시하고 관계 행정기관에 서류 송부(법 제75조의2⑤)"},{"이름":"재검토","설명":"수립된 성장관리계획을 5년마다 재검토(법 제75조의3⑤)"}]}],"함정":"녹지지역이면 모두 포함된다고 생각하기 쉽다. 대통령령이 자연녹지와 생산녹지만 지정했고 보전녹지는 빠져 있다."},"35회-2차-053":{"한줄":"1인이 둘 이상 필지의 토지를 단독으로 소유한 경우에는 필지 수와 관계없이 토지 소유자를 1인으로 본다.","근거":[{"법령":"도시개발법 시행령","조문":"영 제6조제4항","원문":"④ 법 제4조제4항에 따른 동의자의 수를 산정하는 방법은 다음 각 호와 같다.\n1. 도시개발구역의 토지면적을 산정하는 경우: 국공유지를 포함하여 산정할 것\n2. 1필지의 토지 소유권을 여럿이 공유하는 경우: 다른 공유자의 동의를 받은 대표 공유자 1인을 해당 토지 소유자로 볼 것. 다만, 「집합건물의 소유 및 관리에 관한 법률」 제2조제2호에 따른 구분소유자는 각각을 토지 소유자 1인으로 본다.\n2의2. 1인이 둘 이상 필지의 토지를 단독으로 소유한 경우: 필지의 수에 관계없이 토지 소유자를 1인으로 볼 것\n2의3. 둘 이상 필지의 토지를 소유한 공유자가 동일한 경우: 공유자 여럿을 대표하는 1인을 토지 소유자로 볼 것\n5. 법 제11조제5항에 따라 도시개발구역의 지정이 제안된 후부터 법 제4조에 따라 개발계획이 수립되기 전까지의 사이에 토지 소유자가 변경된 경우 또는 법 제4조제2항에 따라 개발계획의 변경을 요청받은 후부터 개발계획이 변경되기 전까지의 사이에 토지 소유자가 변경된 경우: 기존 토지 소유자의 동의서를 기준으로 할 것"}],"선지":[{"번호":1,"판정":"틀림","설명":"토지면적을 산정할 때 국공유지를 포함한다(영 제6조제4항제1호)."},{"번호":2,"판정":"옳음","설명":"1인이 둘 이상 필지를 단독 소유하면 필지 수와 관계없이 1인으로 본다(영 제6조제4항제2호의2)."},{"번호":3,"판정":"틀림","설명":"둘 이상 필지를 소유한 공유자가 동일하면 공유자 여럿을 대표하는 1인을 토지 소유자로 본다. 공유자 각각이 아니다(영 제6조제4항제2호의3)."},{"번호":4,"판정":"틀림","설명":"1필지를 여럿이 공유하면 다른 공유자의 동의를 받은 대표공유자 1인을 소유자로 보되, 「집합건물의 소유 및 관리에 관한 법률」상 구분소유자는 각각 1인으로 본다(영 제6조제4항제2호)."},{"번호":5,"판정":"틀림","설명":"지정 제안 후 개발계획 수립 전에 소유자가 바뀌면 기존 토지 소유자의 동의서를 기준으로 한다(영 제6조제4항제5호)."}],"개념":[{"종류":"표","제목":"동의자 수 산정 방법(영 제6조제4항)","머리":["경우","산정"],"행":[["도시개발구역 토지면적","국공유지를 포함하여 산정"],["1필지를 여럿이 공유","다른 공유자 동의를 받은 대표공유자 1인. 구분소유자는 각각 1인"],["1인이 둘 이상 필지 단독 소유","필지 수와 관계없이 1인"],["동일한 공유자가 둘 이상 필지 소유","공유자 여럿을 대표하는 1인"],["공람·공고일 뒤 구분소유권 분할로 소유자 증가","공람·공고일 전 소유자 수 기준, 증가분은 총수에 넣지 않음"],["제안 전 동의 철회","동의자 수에서 제외"],["제안 후 개발계획 수립 전 소유자 변경","기존 토지 소유자의 동의서 기준"]]},{"종류":"표","제목":"동의 비율 모음","머리":["대상","비율"],"행":[["환지방식 개발계획 수립(법 제4조④)","토지면적 3분의 2 이상 + 토지 소유자 총수 2분의 1 이상"],["조합 설립인가(법 제13조③)","토지면적 3분의 2 이상 + 토지 소유자 총수 2분의 1 이상"],["구역 지정 제안(법 제11조⑥)","대상 구역 토지면적의 3분의 2 이상 토지 소유자 동의"],["지방자치단체등을 시행자로 지정(법 제11조②3호)","국공유지 제외 토지면적 2분의 1 이상 + 소유자 총수 2분의 1 이상"]]}],"함정":"동의자 수 산정은 선지마다 규칙 하나씩을 뒤집는다. 국공유지는 포함, 동일 공유자와 구분소유자는 각각의 규칙이 다르다."},"35회-2차-063":{"한줄":"시장·군수등은 특별한 사유가 없으면 통합심의 결과를 반영해 사업시행계획을 인가해야 한다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제50조의2제4항","원문":"④ 시장ㆍ군수등은 특별한 사유가 없으면 통합심의 결과를 반영하여 사업시행계획을 인가하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제50조의2제5항","원문":"⑤ 통합심의를 거친 경우에는 제1항 각 호의 사항에 대한 검토ㆍ심의ㆍ조사ㆍ협의ㆍ조정 또는 재정을 거친 것으로 본다."},{"법령":"도시 및 주거환경정비법","조문":"제50조의2제1항","원문":"① 정비구역의 지정권자는 사업시행계획인가와 관련된 다음 각 호 중 둘 이상의 심의가 필요한 경우에는 이를 통합하여 검토 및 심의(이하 \"통합심의\"라 한다)하여야 한다.\n2. 「경관법」에 따른 경관 심의에 관한 사항"},{"법령":"도시 및 주거환경정비법","조문":"제50조의2제2항","원문":"② 사업시행자가 통합심의를 신청하는 경우에는 제1항 각 호와 관련된 서류를 첨부하여야 한다. 이 경우 정비구역의 지정권자는 통합심의를 효율적으로 처리하기 위하여 필요한 경우 제출기한을 정하여 제출하도록 할 수 있다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제46조의2제3항","원문":"③ 통합심의위원회 위원장과 부위원장은 제2항에 따른 통합심의위원회의 위원(이하 \"위원\"이라 한다) 중에서 정비구역지정권자가 임명하거나 위촉한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"경관법에 따른 경관 심의는 통합심의 대상 제2호에 들어간다(법 제50조의2제1항제2호)."},{"번호":2,"판정":"옳음","설명":"법 제50조의2제4항에 있는 내용이다."},{"번호":3,"판정":"틀림","설명":"통합심의를 거치면 제1항 각 호 사항의 검토·심의·조사·협의·조정 또는 재정을 거친 것으로 본다(법 제50조의2제5항)."},{"번호":4,"판정":"틀림","설명":"통합심의위원회의 위원장과 부위원장은 정비구역지정권자가 위원 중에서 임명하거나 위촉한다(영 제46조의2제3항)."},{"번호":5,"판정":"틀림","설명":"사업시행자가 통합심의를 신청하는 경우 제1항 각 호와 관련된 서류를 첨부하도록 되어 있어 신청할 수 있다(법 제50조의2제2항)."}],"개념":[{"종류":"표","제목":"통합심의 대상과 소집되는 위원회(법 제50조의2제1항·제3항)","머리":["호","심의 사항","위원회"],"행":[["1","건축법에 따른 건축물의 건축 및 특별건축구역의 지정 등","건축위원회"],["2","경관법에 따른 경관 심의","경관위원회"],["3","교육환경 보호에 관한 법률에 따른 교육환경평가","교육환경보호위원회"],["4","국토계획법에 따른 도시·군관리계획","지방도시계획위원회"],["5","도시교통정비 촉진법에 따른 교통영향평가","교통영향평가심의위원회"],["5의2","소방시설법에 따른 성능위주설계의 평가","성능위주설계평가단 또는 중앙소방기술심의위원회"],["5의3","자연재해대책법에 따른 재해영향평가","재해영향평가심의위원회"],["6","환경영향평가법에 따른 환경영향평가 등","환경영향평가협의회"],["7","그 밖에 국토교통부장관, 시·도지사 또는 시장·군수등이 통합심의에 부치는 사항","그 사항에 심의권한이 있는 위원회"]]},{"종류":"흐름","제목":"사업시행계획인가 절차(법 제50조)","단계":[{"이름":"총회 의결","설명":"시장·군수등과 토지주택공사등을 제외한 사업시행자는 인가 신청 전에 총회 의결을 거친다(제5항)."},{"이름":"인가 신청","설명":"사업시행계획서에 정관등과 국토교통부령 서류를 첨부해 시장·군수등에게 제출한다(제1항)."},{"이름":"통합심의","설명":"제1항 각 호 중 둘 이상의 심의가 필요하면 정비구역 지정권자가 통합심의한다(법 제50조의2)."},{"이름":"인가 여부 통보","설명":"특별한 사유가 없으면 제출일부터 60일 이내에 인가 여부를 결정해 통보한다(제4항)."},{"이름":"고시","설명":"인가하면 국토교통부령으로 정하는 방법과 절차로 지방자치단체 공보에 고시한다(제9항)."},{"이름":"경미한 변경","설명":"신고 대상이며 시장·군수등은 신고를 받은 날부터 20일 이내에 수리 여부를 통지한다(제1항 단서, 제2항)."}]}],"함정":"통합심의 결과의 반영은 시장·군수등의 의무(특별한 사유가 있으면 예외)이고, 통합심의를 거치면 개별 법률상 심의 등을 거친 것으로 본다. 위원장은 호선하지 않고 지정권자가 임명·위촉한다.","개정":"법 제50조의2제1항·제3항은 2025.1.31 개정된 조문이다. 현행 통합심의 대상에는 소방 성능위주설계의 평가(제5호의2)와 재해영향평가(제5호의3)가 포함되어 있다."},"35회-2차-074":{"한줄":"공개공지등을 설치할 때는 긴 의자 또는 조경시설 등 건축조례로 정하는 시설을 설치해야 한다.","근거":[{"법령":"건축법 시행령","조문":"제27조의2제3항","원문":"③ 제1항에 따라 공개공지등을 설치할 때에는 모든 사람들이 환경친화적으로 편리하게 이용할 수 있도록 긴 의자 또는 조경시설 등 건축조례로 정하는 시설을 설치해야 한다."},{"법령":"건축법","조문":"제43조제1항제4호","원문":"① 다음 각 호의 어느 하나에 해당하는 지역의 환경을 쾌적하게 조성하기 위하여 대통령령으로 정하는 용도와 규모의 건축물은 일반이 사용할 수 있도록 대통령령으로 정하는 기준에 따라 소규모 휴식시설 등의 공개 공지(空地: 공터) 또는 공개 공간(이하 \"공개공지등\"이라 한다)을 설치하여야 한다.\n4. 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장이 도시화의 가능성이 크거나 노후 산업단지의 정비가 필요하다고 인정하여 지정ㆍ공고하는 지역"},{"법령":"건축법 시행령","조문":"제27조의2제1항","원문":"① 법 제43조제1항에 따라 다음 각 호의 어느 하나에 해당하는 건축물의 대지에는 공개 공지 또는 공개 공간(이하 이 조에서 \"공개공지등\"이라 한다)을 설치해야 한다. 이 경우 공개 공지는 필로티의 구조로 설치할 수 있다."},{"법령":"건축법 시행령","조문":"제27조의2제6항","원문":"⑥ 공개공지등에는 연간 60일 이내의 기간 동안 건축조례로 정하는 바에 따라 주민들을 위한 문화행사를 열거나 판촉활동을 할 수 있다. 다만, 울타리를 설치하는 등 공중이 해당 공개공지등을 이용하는데 지장을 주는 행위를 해서는 아니 된다."},{"법령":"건축법","조문":"제43조제4항","원문":"④ 누구든지 공개공지등에 물건을 쌓아놓거나 출입을 차단하는 시설을 설치하는 등 공개공지등의 활용을 저해하는 행위를 하여서는 아니 된다."},{"법령":"건축법 시행령","조문":"제27조의2제7항","원문":"⑦ 법 제43조제4항에 따라 제한되는 행위는 다음 각 호와 같다.\n3. 울타리나 담장 등의 시설을 설치하거나 출입구를 폐쇄하는 등 공개공지등의 출입을 차단하는 행위"}],"선지":[{"번호":1,"판정":"틀림","설명":"특별자치시장·시장·군수·구청장이 도시화 가능성이 크거나 노후 산업단지의 정비가 필요하다고 인정해 지정·공고한 지역도 설치 대상 지역이다(법 제43조제1항제4호)."},{"번호":2,"판정":"틀림","설명":"공개 공지는 필로티의 구조로 설치할 수 있다(영 제27조의2제1항 후단)."},{"번호":3,"판정":"옳음","설명":"영 제27조의2제3항에 있는 내용이다."},{"번호":4,"판정":"틀림","설명":"문화행사나 판촉활동은 연간 60일 이내의 기간 동안 할 수 있다(영 제27조의2제6항). 90일이 아니다."},{"번호":5,"판정":"틀림","설명":"울타리나 담장을 설치하거나 출입구를 폐쇄해 출입을 차단하는 행위는 신고 대상이 아니라 제한되는 행위다(법 제43조제4항, 영 제27조의2제7항제3호)."}],"개념":[{"종류":"표","제목":"공개공지등 설치 대상(법 제43조제1항, 영 제27조의2제1항·제2항)","머리":["구분","내용"],"행":[["대상 지역","일반주거지역·준주거지역, 상업지역, 준공업지역, 시장·군수·구청장이 도시화 가능성이 크거나 노후 산업단지 정비가 필요하다고 인정해 지정·공고하는 지역"],["대상 건축물","문화 및 집회시설, 종교시설, 판매시설(농수산물유통시설 제외), 운수시설(여객용 시설만), 업무시설, 숙박시설로서 해당 용도 바닥면적 합계 5천제곱미터 이상"],["그 밖의 건축물","그 밖에 다중이 이용하는 시설로서 건축조례로 정하는 건축물"],["면적","대지면적의 100분의 10 이하의 범위에서 건축조례로 정함"],["설치 방식","공개 공지는 필로티 구조로 설치 가능"]]},{"종류":"표","제목":"공개공지등의 이용·완화·제한(영 제27조의2제3항·제4항·제6항·제7항)","머리":["구분","내용"],"행":[["설치 시설","긴 의자 또는 조경시설 등 건축조례로 정하는 시설"],["건축기준 완화","용적률은 해당 지역 용적률의 1.2배 이하, 높이 제한은 해당 건축물 높이기준의 1.2배 이하"],["문화행사·판촉활동","연간 60일 이내, 건축조례로 정하는 바에 따름. 울타리 설치 등 공중의 이용에 지장을 주는 행위 금지"],["제한되는 행위","일정 공간을 점유한 영업, 시설 외 물건·시설물 설치, 물건 적치, 울타리·담장 설치나 출입구 폐쇄로 출입 차단, 시설 훼손 등"]]}],"함정":"문화행사·판촉활동은 연간 60일 이내다. 출입 차단은 신고하면 되는 행위가 아니라 금지되는 행위다. 필로티 설치는 허용되고, 노후 산업단지 정비가 필요해 지정·공고한 지역도 설치 대상 지역이다."},"35회-2차-078":{"한줄":"국가적 문화유산 건축물은 국토교통부령으로 정하는 것이 대상이어서 문화체육관광부령으로 정한다는 5번은 해당하지 않는다.","근거":[{"법령":"건축법","조문":"제48조의3제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 건축물을 건축하고자 하는 자는 제22조에 따른 사용승인을 받는 즉시 건축물이 지진 발생 시에 견딜 수 있는 능력(이하 \"내진능력\"이라 한다)을 공개하여야 한다. 다만, 제48조제2항에 따른 구조안전 확인 대상 건축물이 아니거나 내진능력 산정이 곤란한 건축물로서 대통령령으로 정하는 건축물은 공개하지 아니한다.\n1. 층수가 2층[주요구조부인 기둥과 보를 설치하는 건축물로서 그 기둥과 보가 목재인 목구조 건축물(이하 \"목구조 건축물\"이라 한다)의 경우에는 3층] 이상인 건축물\n2. 연면적이 200제곱미터(목구조 건축물의 경우에는 500제곱미터) 이상인 건축물\n3. 그 밖에 건축물의 규모와 중요도를 고려하여 대통령령으로 정하는 건축물"},{"법령":"건축법 시행령","조문":"제32조의2","원문":"제32조의2(건축물의 내진능력 공개)\n① 법 제48조의3제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 건축물\"이란 다음 각 호의 어느 하나에 해당하는 건축물을 말한다.\n1. 창고, 축사, 작물 재배사 및 표준설계도서에 따라 건축하는 건축물로서 제32조제2항제1호 및 제3호부터 제9호까지의 어느 하나에도 해당하지 아니하는 건축물\n2. 제32조제1항에 따른 구조기준 중 국토교통부령으로 정하는 소규모건축구조기준을 적용한 건축물\n② 법 제48조의3제1항제3호에서 \"대통령령으로 정하는 건축물\"이란 제32조제2항제3호부터 제9호까지의 어느 하나에 해당하는 건축물을 말한다."},{"법령":"건축법 시행령","조문":"제32조제2항","원문":"② 제1항에 따라 구조 안전을 확인한 건축물 중 다음 각 호의 어느 하나에 해당하는 건축물의 건축주는 해당 건축물의 설계자로부터 구조 안전의 확인 서류를 받아 법 제21조에 따른 착공신고를 하는 때에 그 확인 서류를 허가권자에게 제출하여야 한다. 다만, 표준설계도서에 따라 건축하는 건축물은 제외한다.\n1. 층수가 2층[주요구조부인 기둥과 보를 설치하는 건축물로서 그 기둥과 보가 목재인 목구조 건축물(이하 \"목구조 건축물\"이라 한다)의 경우에는 3층] 이상인 건축물\n2. 연면적이 200제곱미터(목구조 건축물의 경우에는 500제곱미터) 이상인 건축물. 다만, 창고, 축사, 작물 재배사는 제외한다.\n3. 높이가 13미터 이상인 건축물\n4. 처마높이가 9미터 이상인 건축물\n5. 기둥과 기둥 사이의 거리가 10미터 이상인 건축물\n6. 건축물의 용도 및 규모를 고려한 중요도가 높은 건축물로서 국토교통부령으로 정하는 건축물\n7. 국가적 문화유산으로 보존할 가치가 있는 건축물로서 국토교통부령으로 정하는 것\n8. 제2조제18호가목, 다목 및 라목의 건축물\n9. 별표 1 제1호의 단독주택 및 같은 표 제2호의 공동주택"}],"선지":[{"번호":1,"판정":"옳음","설명":"높이 13미터 이상은 영 제32조제2항제3호로 내진능력 공개 대상이다(영 제32조의2제2항)."},{"번호":2,"판정":"옳음","설명":"처마높이 9미터 이상은 제4호로 공개 대상이다."},{"번호":3,"판정":"옳음","설명":"기둥과 기둥 사이의 거리 10미터 이상은 제5호로 공개 대상이다."},{"번호":4,"판정":"옳음","설명":"중요도가 높은 건축물로서 국토교통부령으로 정하는 건축물은 제6호로 공개 대상이다."},{"번호":5,"판정":"틀림","설명":"제7호의 국가적 문화유산 건축물은 국토교통부령으로 정하는 것이다. 문화체육관광부령으로 정하는 건축물은 대상이 아니다."}],"개념":[{"종류":"표","제목":"구조 안전 확인 서류 제출 대상(영 제32조제2항)","머리":["호","건축물"],"행":[["1","층수 2층(목구조 건축물은 3층) 이상"],["2","연면적 200제곱미터(목구조 500제곱미터) 이상. 창고, 축사, 작물 재배사 제외"],["3","높이 13미터 이상"],["4","처마높이 9미터 이상"],["5","기둥과 기둥 사이의 거리 10미터 이상"],["6","중요도가 높은 건축물로서 국토교통부령으로 정하는 건축물"],["7","국가적 문화유산으로 보존할 가치가 있는 건축물로서 국토교통부령으로 정하는 것"],["8","영 제2조제18호가목·다목·라목의 건축물"],["9","단독주택, 공동주택"]]},{"종류":"표","제목":"내진능력 공개(법 제48조의3, 영 제32조의2)","머리":["구분","내용"],"행":[["공개 시기","사용승인을 받는 즉시"],["법에서 정한 대상","층수 2층(목구조 3층) 이상, 연면적 200제곱미터(목구조 500제곱미터) 이상"],["영으로 정한 대상(법 제48조의3제1항제3호)","영 제32조제2항제3호부터 제9호까지의 건축물"],["공개하지 않는 건축물","구조안전 확인 대상이 아닌 건축물, 내진능력 산정이 곤란한 건축물로서 영 제32조의2제1항에서 정한 것(창고·축사·작물 재배사·표준설계도서 건축물 중 제32조제2항 해당 호가 없는 것, 소규모건축구조기준 적용 건축물)"],["산정 기준·공개 방법","국토교통부령"]]}],"함정":"공개 대상은 법의 층수·연면적 기준에 영 제32조제2항제3호~제9호가 더해진다. 선지 문장의 수치(13미터, 9미터, 10미터)는 모두 맞고 5번만 위임 주체가 국토교통부령에서 문화체육관광부령으로 바뀌어 있다."},"35회-2차-079":{"한줄":"태양에너지 발전설비를 설치하는 용도는 일시사용허가 대상이어서 신고할 수 있는 용도에 해당하지 않는다.","근거":[{"법령":"농지법","조문":"제36조의2제1항","원문":"① 농지를 다음 각 호의 어느 하나에 해당하는 용도로 일시사용하려는 자는 대통령령으로 정하는 바에 따라 지력을 훼손하지 아니하는 범위에서 일정 기간 사용한 후 농지로 원상복구한다는 조건으로 시장ㆍ군수 또는 자치구구청장에게 신고하여야 한다. 신고한 사항을 변경하려는 경우에도 또한 같다. 다만, 국가나 지방자치단체의 경우에는 시장ㆍ군수 또는 자치구구청장과 협의하여야 한다.\n1. 썰매장, 지역축제장 등으로 일시적으로 사용하는 경우\n2. 제36조제1항제1호 또는 제2호에 해당하는 시설을 일시적으로 설치하는 경우"},{"법령":"농지법","조문":"제36조제1항제2호","원문":"2. 주(主)목적사업(해당 농지에서 허용되는 사업만 해당한다)을 위하여 현장 사무소나 부대시설, 그 밖에 이에 준하는 시설을 설치하거나 물건을 적치(積置)하거나 매설(埋設)하는 경우"},{"법령":"농지법","조문":"제36조제1항제4호","원문":"①농지를 다음 각 호의 어느 하나에 해당하는 용도로 일시 사용하려는 자는 대통령령으로 정하는 바에 따라 일정 기간 사용한 후 농지로 복구한다는 조건으로 시장ㆍ군수 또는 자치구구청장의 허가를 받아야 한다. 허가받은 사항을 변경하려는 경우에도 또한 같다. 다만, 국가나 지방자치단체의 경우에는 시장ㆍ군수 또는 자치구구청장과 협의하여야 한다.\n4. 「전기사업법」 제2조제1호의 전기사업을 영위하기 위한 목적으로 설치하는 「재생에너지 개발ㆍ이용ㆍ보급 촉진법」 제2조제2호가목에 따른 태양에너지 발전설비(이하 \"태양에너지 발전설비\"라 한다)로서 다음 각 목의 요건을 모두 갖춘 경우"},{"법령":"농지법 시행령","조문":"제38조제1항제3호","원문":"① 법 제36조제1항에 따른 허가ㆍ협의, 같은 조 제2항에 따른 협의, 법 제36조의2제1항에 따른 신고ㆍ협의 및 같은 조 제2항에 따른 협의의 경우 농지의 타용도 일시사용기간은 다음 각 호와 같다.\n3. 법 제36조의2제1항에 따른 신고ㆍ협의 및 같은 조 제2항에 따른 협의: 6개월 이내"}],"선지":[{"번호":1,"판정":"옳음","설명":"썰매장은 법 제36조의2제1항제1호의 신고 용도다."},{"번호":2,"판정":"옳음","설명":"지역축제장도 같은 호의 신고 용도다."},{"번호":3,"판정":"옳음","설명":"주목적사업을 위해 물건을 적치하거나 매설하는 경우는 제36조제1항제2호 시설로서 제36조의2제1항제2호에 따라 신고할 수 있다."},{"번호":4,"판정":"옳음","설명":"주목적사업을 위한 현장 사무소 설치도 제36조제1항제2호이므로 신고할 수 있다."},{"번호":5,"판정":"틀림","설명":"태양에너지 발전설비는 제36조제1항제4호의 허가 대상이다. 제36조의2제1항의 신고 용도에 들어 있지 않다."}],"개념":[{"종류":"비교","제목":"농지 타용도 일시사용 허가와 신고","왼쪽":{"이름":"허가(법 제36조제1항)","항목":["간이 농수축산업용 시설, 농수산물의 간이 처리 시설 설치","주목적사업을 위한 현장 사무소·부대시설 설치, 물건 적치·매설","대통령령으로 정하는 토석·광물 채굴","전기사업을 위한 태양에너지 발전설비(간척지 등 요건 충족 시)","정보통신기술을 결합한 작물재배사 설치","기간: 제1호 용도 5년 이내, 제2호 용도 주목적사업 시행에 필요한 기간, 제5호 용도 7년 이내, 그 밖 5년 이내(영 제38조제1항제1호)"]},"오른쪽":{"이름":"신고(법 제36조의2제1항)","항목":["썰매장, 지역축제장 등 일시적 사용","제36조제1항제1호·제2호 시설을 일시적으로 설치","지력을 훼손하지 않는 범위에서 일정 기간 사용 후 원상복구","수리 여부는 신고를 받은 날부터 10일 이내 통지","기간 내 통지가 없으면 그 기간이 끝난 날의 다음 날 수리한 것으로 봄","기간: 6개월 이내(영 제38조제1항제3호)"]}},{"종류":"흐름","제목":"일시사용신고 절차(법 제36조의2)","단계":[{"이름":"신고","설명":"지력을 훼손하지 않는 범위에서 일정 기간 사용한 후 농지로 원상복구한다는 조건으로 시장·군수·자치구구청장에게 신고한다. 국가나 지방자치단체는 협의한다(제1항)."},{"이름":"복구계획·비용","설명":"수리하거나 협의할 때 농지로의 복구계획을 제출하게 하고 복구비용을 예치하게 할 수 있다(제3항)."},{"이름":"수리 통지","설명":"신고를 받은 날부터 10일 이내에 수리 여부를 통지한다(제4항)."},{"이름":"수리 간주","설명":"기간 내 통지하지 않으면 기간이 끝난 날의 다음 날 수리한 것으로 본다(제5항)."},{"이름":"사용기간","설명":"신고·협의의 일시사용기간은 6개월 이내이며, 영 제38조제2항의 기간 연장 규정에서 제외된다(영 제38조제1항제3호, 제2항)."}]}],"함정":"신고 용도는 썰매장·지역축제장 등과 제36조제1항 제1호·제2호 시설로 한정된다. 같은 제36조제1항이라도 토석 채굴(제3호), 태양에너지 발전설비(제4호), 작물재배사(제5호)는 허가 대상이다.","개정":"법 제36조제1항은 2026.3.17 개정되었고, 제4호는 「전기사업법」 제2조제1호의 전기사업을 위한 「재생에너지 개발ㆍ이용ㆍ보급 촉진법」 제2조제2호가목의 태양에너지 발전설비로서 간척지 등 요건을 갖춘 경우를 허가 대상으로 정한다."},"35회-2차-106":{"한줄":"경정해서 납세고지한 세액은 그 납세고지서에 따른 납부기한의 다음 날부터 징수권을 행사할 수 있으므로 시효도 그날부터 진행한다.","근거":[{"법령":"국세기본법","조문":"제27조제1항","원문":"① 국세의 징수를 목적으로 하는 국가의 권리(이하 이 조에서 \"국세징수권\"이라 한다)는 이를 행사할 수 있는 때부터 다음 각 호의 구분에 따른 기간 동안 행사하지 아니하면 소멸시효가 완성된다. 이 경우 다음 각 호의 국세의 금액은 가산세를 제외한 금액으로 한다.\n  1. 5억원 이상의 국세: 10년\n  2. 제1호 외의 국세: 5년"},{"법령":"국세기본법","조문":"제27조제3항","원문":"③ 제1항에 따른 국세징수권을 행사할 수 있는 때는 다음 각 호의 날을 말한다.\n  1. 과세표준과 세액의 신고에 의하여 납세의무가 확정되는 국세의 경우 신고한 세액에 대해서는 그 법정 신고납부기한의 다음 날\n  2. 과세표준과 세액을 정부가 결정, 경정 또는 수시부과결정하는 경우 납부고지한 세액에 대해서는 그 고지에 따른 납부기한의 다음 날"},{"법령":"지방세기본법","조문":"제39조제1항","원문":"① 지방자치단체의 징수금의 징수를 목적으로 하는 지방자치단체의 권리(이하 \"지방세징수권\"이라 한다)는 이를 행사할 수 있는 때부터 다음 각 호의 구분에 따른 기간 동안 행사하지 아니하면 소멸시효가 완성된다.\n  1. 가산세를 제외한 지방세의 금액이 5천만원 이상인 경우: 10년\n  2. 가산세를 제외한 지방세의 금액이 5천만원 미만인 경우: 5년"},{"법령":"지방세기본법","조문":"제39조제3항","원문":"③ 지방세징수권을 행사할 수 있는 때는 다음 각 호의 날로 한다.\n  1. 과세표준과 세액의 신고로 납세의무가 확정되는 지방세의 경우 신고한 세액에 대해서는 그 법정납부기한의 다음 날\n  2. 과세표준과 세액을 지방자치단체의 장이 결정 또는 경정하는 경우 납세고지한 세액에 대해서는 그 납세고지서에 따른 납부기한의 다음 날"}],"선지":[{"번호":1,"판정":"틀림","설명":"국세는 가산세를 뺀 금액이 5억원 이상이면 10년이다. 10억원이면 10년이다(국세기본법 제27조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"지방세는 5천만원 이상이면 10년이다. 1억원이면 10년이고, 7년이라는 시효 기간은 없다(지방세기본법 제39조제1항제1호)."},{"번호":3,"판정":"틀림","설명":"5천만원은 '5천만원 이상'에 해당해 10년이다. 5년은 5천만원 미만일 때다(같은 항 제1호·제2호)."},{"번호":4,"판정":"틀림","설명":"확정신고한 세액 부분만 법정 신고납부기한의 다음 날이다. 정부가 경정하여 납부고지한 세액은 그 고지에 따른 납부기한의 다음 날이다(국세기본법 제27조제3항제1호·제2호)."},{"번호":5,"판정":"옳음","설명":"경정으로 납세고지한 세액은 납세고지서에 따른 납부기한의 다음 날이 징수권을 행사할 수 있는 때다(지방세기본법 제39조제3항제2호)."}],"개념":[{"종류":"표","제목":"징수권 소멸시효 기간과 기산일","머리":["구분","10년","5년","신고 세액의 기산일","경정·결정 고지 세액의 기산일"],"행":[["국세","5억원 이상","5억원 미만","법정 신고납부기한의 다음 날","납부고지에 따른 납부기한의 다음 날"],["지방세","5천만원 이상","5천만원 미만","법정납부기한의 다음 날","납세고지서에 따른 납부기한의 다음 날"],["근거 조문","국세기본법 제27조제1항","지방세기본법 제39조제1항","국세기본법 제27조제3항제1호 / 지방세기본법 제39조제3항제1호","국세기본법 제27조제3항제2호 / 지방세기본법 제39조제3항제2호"],["기산일 예외","-","-","법정 신고납부기한이 연장되면 연장된 기한의 다음 날(국세기본법 제27조제4항제3호, 지방세기본법 제39조제4항제2호)","원천징수·특별징수세액을 납부고지한 경우는 그 고지에 따른 납부기한의 다음 날(국세기본법 제27조제4항제1호, 지방세기본법 제39조제4항제1호)"]]},{"종류":"표","제목":"지방세징수권 시효의 중단과 정지(지방세기본법 제40조)","머리":["구분","사유"],"행":[["중단","납세고지, 독촉 또는 납부최고, 교부청구, 압류"],["다시 진행하는 때","고지한 납부기간·독촉 납부기간·교부청구 중의 기간·압류해제까지의 기간이 지난 때부터"],["정지","지방세법에 따른 분할납부기간·연부기간, 지방세징수법에 따른 징수유예기간·체납처분유예기간"],["정지(소송)","사해행위 취소의 소 또는 채권자대위 소송이 진행 중인 기간(각하·기각·취하되면 효력 없음)"],["정지(국외)","체납자가 국외에 6개월 이상 계속 체류하는 경우 그 체류기간"]]}],"함정":"신고한 세액과 경정으로 고지한 세액은 기산일이 다르다. ④는 두 경우를 섞었다. 금액 구간은 국세 5억원, 지방세 5천만원이고 '이상'이 10년이다."},"35회-2차-118":{"한줄":"토지(제94조제1항제1호)와 전세권(같은 항 제2호)은 양도소득금액을 같은 호로 묶어 계산하므로 한쪽의 양도차손을 다른 쪽 양도소득금액에서 공제한다.","근거":[{"법령":"소득세법","조문":"제102조제1항","원문":"① 양도소득금액은 다음 각 호의 소득별로 구분하여 계산한다. 이 경우 소득금액을 계산할 때 발생하는 결손금은 다른 호의 소득금액과 합산하지 아니한다.\n  1. 제94조제1항제1호ㆍ제2호 및 제4호에 따른 소득\n  2. 제94조제1항제3호에 따른 소득\n  3. 제94조제1항제5호에 따른 소득\n  4. 제94조제1항제6호에 따른 소득"},{"법령":"소득세법","조문":"제102조제2항","원문":"② 제1항에 따라 양도소득금액을 계산할 때 양도차손이 발생한 자산이 있는 경우에는 제1항 각 호별로 해당 자산 외의 다른 자산에서 발생한 양도소득금액에서 그 양도차손을 공제한다. 이 경우 공제방법은 양도소득금액의 세율 등을 고려하여 대통령령으로 정한다."},{"법령":"소득세법","조문":"제105조제1항","원문":"① 제94조제1항 각 호(같은 항 제3호다목 및 같은 항 제5호는 제외한다)에서 규정하는 자산을 양도한 거주자는 제92조제2항에 따라 계산한 양도소득과세표준을 다음 각 호의 구분에 따른 기간에 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 한다.\n  1. 제94조제1항제1호ㆍ제2호ㆍ제4호 및 제6호에 따른 자산을 양도한 경우에는 그 양도일이 속하는 달의 말일부터 2개월. 다만, 「부동산 거래신고 등에 관한 법률」 제10조제1항에 따른 토지거래계약에 관한 허가구역에 있는 토지를 양도할 때 토지거래계약허가를 받기 전에 대금을 청산한 경우에는 그 허가일(토지거래계약허가를 받기 전에 허가구역의 지정이 해제된 경우에는 그 해제일을 말한다)이 속하는 달의 말일부터 2개월로 한다.\n  3. 제1호 및 제2호에도 불구하고 제88조제1호 각 목 외의 부분 후단에 따른 부담부증여의 채무액에 해당하는 부분으로서 양도로 보는 경우에는 그 양도일이 속하는 달의 말일부터 3개월"},{"법령":"소득세법","조문":"제91조제2항","원문":"② 제94조제1항제1호 및 제2호의 자산을 매매하는 거래당사자가 매매계약서의 거래가액을 실지거래가액과 다르게 적은 경우에는 해당 자산에 대하여 이 법 또는 이 법 외의 법률에 따른 양도소득세의 비과세 또는 감면에 관한 규정을 적용할 때 비과세 또는 감면받았거나 받을 세액에서 다음 각 호의 구분에 따른 금액을 뺀다.\n  1. 이 법 또는 이 법 외의 법률에 따라 양도소득세의 비과세에 관한 규정을 적용받을 경우: 비과세에 관한 규정을 적용하지 아니하였을 경우의 제104조제1항에 따른 양도소득 산출세액과 매매계약서의 거래가액과 실지거래가액과의 차액 중 적은 금액"},{"법령":"소득세법 시행령","조문":"제154조제1항제3호","원문":"①법 제89조제1항제3호가목에서 \"대통령령으로 정하는 요건\"이란 1세대가 양도일(주택의 매매계약을 체결한 후 해당 계약에 따라 주택을 주택 외의 용도로 용도변경하여 양도하는 경우에는 해당 주택의 매매계약일을 말한다. 이하 이 항에서 같다) 현재 국내에 1주택을 보유하고 있는 경우로서 해당 주택의 보유기간이 2년(제8항제2호에 해당하는 거주자의 주택인 경우는 3년) 이상인 것[취득 당시에 「주택법」 제63조의2제1항제1호에 따른 조정대상지역(이하 \"조정대상지역\"이라 한다)에 있는 주택의 경우에는 해당 주택의 보유기간이 2년(제8항제2호에 해당하는 거주자의 주택인 경우에는 3년) 이상이고 그 보유기간 중 거주기간이 2년 이상인 것]을 말한다. 다만, 1세대가 양도일 현재 국내에 1주택을 보유하고 있는 경우로서 제1호부터 제3호까지의 어느 하나에 해당하는 경우에는 그 보유기간 및 거주기간의 제한을 받지 않으며 제5호에 해당하는 경우에는 거주기간의 제한을 받지 않는다.\n  3. 1년이상 거주한 주택을 재정경제부령으로 정하는 취학, 근무상의 형편, 질병의 요양, 그 밖에 부득이한 사유로 양도하는 경우"},{"법령":"소득세법 시행령","조문":"제155조제2항","원문":"②상속받은 주택[조합원입주권 또는 분양권을 상속받아 사업시행 완료 후 취득한 신축주택을 포함하며, 피상속인이 상속개시 당시 2 이상의 주택{상속받은 1주택이 「도시 및 주거환경정비법」에 따른 재개발사업(이하 \"재개발사업\"이라 한다), 재건축사업(이하 \"재건축사업\"이라 한다) 또는 「빈집 및 소규모주택 정비에 관한 특례법」에 따른 소규모재건축사업, 소규모재개발사업, 가로주택정비사업, 자율주택정비사업(이하 \"소규모재건축사업등\"이라 한다)의 시행으로 2 이상의 주택이 된 경우를 포함한다}을 소유한 경우에는 다음 각 호의 순위에 따른 1주택을 말한다]과 그 밖의 주택(상속개시 당시 보유한 주택 또는 상속개시 당시 보유한 조합원입주권이나 분양권에 의하여 사업시행 완료 후 취득한 신축주택만 해당하며, 상속개시일부터 소급하여 2년 이내에 피상속인으로부터 증여받은 주택 또는 증여받은 조합원입주권이나 분양권에 의하여 사업시행 완료 후 취득한 신축주택은 제외한다. 이하 이 항에서 \"일반주택\"이라 한다)을 국내에 각각 1개씩 소유하고 있는 1세대가 일반주택을 양도하는 경우에는 국내에 1개의 주택을 소유하고 있는 것으로 보아 제154조제1항을 적용한다. 다만, 상속인과 피상속인이 상속개시 당시 1세대인 경우에는 1주택을 보유하고 1세대를 구성하는 자가 직계존속(배우자의 직계존속을 포함하며, 세대를 합친 날 현재 직계존속 중 어느 한 사람 또는 모두가 60세 이상으로서 1주택을 보유하고 있는 경우만 해당한다)을 동거봉양하기 위하여 세대를 합침에 따라 2주택을 보유하게 되는 경우로서 합치기 이전부터 보유하고 있었던 주택만 상속받은 주택으로 본다(이하 제3항, 제7항제1호, 제156조의2제7항제1호 및 제156조의3제5항제1호에서 같다)."}],"선지":[{"번호":1,"판정":"틀림","설명":"부담부증여의 채무액 부분은 양도일이 속하는 달의 말일부터 3개월 이내에 예정신고한다. 2개월은 토지·건물 등 일반 양도의 기한이다(소득세법 제105조제1항제1호·제3호)."},{"번호":2,"판정":"틀림","설명":"비과세 규정을 적용하지 않았을 때의 양도소득 산출세액과 매매계약서 거래가액·실지거래가액의 차액 중 적은 금액을 뺀다. 큰 금액이 아니다(제91조제2항제1호)."},{"번호":3,"판정":"틀림","설명":"부득이한 사유로 보유·거주 제한을 받지 않으려면 1년 이상 거주한 주택이어야 한다. 6개월 거주로는 해당하지 않는다(시행령 제154조제1항제3호)."},{"번호":4,"판정":"옳음","설명":"토지(제94조제1항제1호)와 전세권(제2호다목)은 양도소득금액을 같은 호로 묶어 계산하므로 양도차손을 다른 자산의 양도소득금액에서 공제한다(제102조제1항제1호·제2항)."},{"번호":5,"판정":"틀림","설명":"상속주택 특례는 일반주택을 양도할 때 적용한다. 상속받은 주택을 양도할 때는 적용하지 않는다(시행령 제155조제2항)."}],"개념":[{"종류":"표","제목":"양도소득금액의 구분 계산과 양도차손 공제(소득세법 제102조)","머리":["구분","자산(제94조제1항)","양도차손 공제"],"행":[["제1호 소득","토지·건물(제1호), 부동산에 관한 권리(제2호), 기타자산(제4호)","같은 호 안의 다른 자산 양도소득금액에서 공제"],["제2호 소득","주식등(제3호)","같은 호 안에서만 공제"],["제3호 소득","파생상품등(제5호)","같은 호 안에서만 공제"],["제4호 소득","신탁 수익권(제6호)","같은 호 안에서만 공제"],["다른 호와의 관계","소득금액을 계산할 때 생긴 결손금은 다른 호의 소득금액과 합산하지 않음","제102조제1항 후단"]]},{"종류":"표","제목":"1세대 1주택 특례: 2주택이어도 1주택으로 보는 경우(소득세법 시행령 제155조)","머리":["사유","양도하는 주택","기한"],"행":[["일시적 2주택(종전 주택 취득 후 1년 이상 지나 신규 주택 취득)","종전 주택","신규 주택 취득일부터 3년. 종전·신규 주택이 모두 조정대상지역이면 2년(제1항)"],["상속주택 + 일반주택","일반주택(상속주택 양도는 해당 없음)","기한 없음(제2항)"],["60세 이상 직계존속 동거봉양 합가","먼저 양도하는 주택","합친 날부터 10년 이내(제4항)"],["혼인 합가","먼저 양도하는 주택","혼인한 날부터 10년 이내(제5항)"],["지정문화유산·등록문화유산·천연기념물등 주택 + 일반주택","일반주택","기한 없음(제6항)"],["농어촌주택(상속·이농·귀농) + 일반주택","일반주택","귀농주택은 취득한 날부터 5년 이내(제7항)"],["부득이한 사유로 취득한 수도권 밖 주택 + 일반주택","일반주택","사유가 해소된 날부터 3년 이내(제8항)"]]}],"함정":"①은 부담부증여를 일반 양도의 2개월로 적었다. ③은 거주 요건이 6개월이 아니라 1년 이상이다. ⑤는 상속받은 주택을 팔 때가 아니라 일반주택을 팔 때만 특례를 받는다. ②는 두 금액 중 적은 금액을 뺀다.","개정":"일시적 2주택 특례의 기간이 시행령 제155조제1항에서 바뀌었다(<개정 2026.9.30> 표시). 종전 주택과 신규 주택이 모두 조정대상지역이면 신규 주택 취득일부터 2년(조정대상지역 공고일 이전 취득 또는 계약금 지급 확인 시 제외), 그 밖은 3년이다. 시행령 파일의 시행일은 2026.10.1이다."},"35회-1차-020":{"한줄":"총부채원리금상환비율(DSR) 강화는 대출 한도를 줄여 수요를 억제하는 금융규제다.","근거":[{"이론":"부동산정책 수단의 분류","내용":"금융규제는 담보인정비율(LTV)·총부채상환비율(DTI)·총부채원리금상환비율(DSR) 등으로 대출 한도와 요건을 조정하는 정책이다. 토지거래 허가·분양가 제한은 거래·가격에 대한 직접규제, 개발부담금은 개발이익 환수, 택지개발지구 지정은 토지 공급과 이용에 관한 정책이다."}],"선지":[{"번호":1,"판정":"-","설명":"택지개발지구 지정은 주택용 택지를 계획적으로 개발·공급하는 공급정책이다."},{"번호":2,"판정":"-","설명":"토지거래허가제는 허가구역 안에서 토지거래계약을 허가받게 하는 거래규제다(부동산 거래신고 등에 관한 법률 제10조)."},{"번호":3,"판정":"-","설명":"개발부담금은 개발이익 중 법에 따라 부과·징수하는 금액으로 개발이익 환수 수단이다(개발이익 환수에 관한 법률 제2조제4호)."},{"번호":4,"판정":"-","설명":"분양가상한제는 일정 지역의 공동주택 분양가격을 제한하는 가격규제다(주택법 제57조제1항)."},{"번호":5,"판정":"-","설명":"DSR 강화는 연간 원리금 상환액의 소득 대비 비율 한도를 낮추는 대출 규제로 금융규제에 해당한다."}],"개념":[{"종류":"표","제목":"부동산정책 수단 분류","머리":["분류","수단 예","내용"],"행":[["금융규제","LTV·DTI·DSR 조정, 대출 총량 관리","대출 한도와 상환 능력을 기준으로 수요 조절"],["거래규제","토지거래허가제, 부동산 거래신고","거래 자체를 허가·신고 대상으로 관리"],["가격규제","분양가상한제, 임대료 규제","가격 상한을 정해 시장가격에 개입"],["개발이익 환수","개발부담금, 재건축부담금","개발로 생긴 이익의 일부를 환수"],["공급정책","택지개발지구 지정, 공공주택 공급","토지·주택 공급량 확대"],["이용규제","용도지역·지구제, 개발제한구역","토지이용을 제한해 개발 조절"]]}],"함정":"토지거래허가제와 분양가상한제도 부동산시장을 누르는 정책이라 금융규제로 오해하기 쉽다. 금융규제는 대출과 관련된 정책(LTV·DTI·DSR)만 가리킨다."},"35회-1차-035":{"한줄":"기준시점을 미리 정했더라도 그 날짜에 가격조사가 가능한 경우에만 기준시점으로 할 수 있다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제9조제2항","원문":"기준시점은 대상물건의 가격조사를 완료한 날짜로 한다. 다만, 기준시점을 미리 정하였을 때에는 그 날짜에 가격조사가 가능한 경우에만 기준시점으로 할 수 있다."},{"법령":"감정평가에 관한 규칙","조문":"제6조제2항","원문":"감정평가법인등은 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 기준시점의 가치형성요인 등을 실제와 다르게 가정하거나 특수한 경우로 한정하는 조건(이하 \"감정평가조건\"이라 한다)을 붙여 감정평가할 수 있다. 1. 법령에 다른 규정이 있는 경우"},{"법령":"감정평가에 관한 규칙","조문":"제7조제2항~제4항","원문":"둘 이상의 대상물건이 일체로 거래되거나 대상물건 상호 간에 용도상 불가분의 관계가 있는 경우에는 일괄하여 감정평가할 수 있다. 하나의 대상물건이라도 가치를 달리하는 부분은 이를 구분하여 감정평가할 수 있다. 일체로 이용되고 있는 대상물건의 일부분에 대하여 감정평가하여야 할 특수한 목적이나 합리적인 이유가 있는 경우에는 그 부분에 대하여 감정평가할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"미리 정한 기준시점은 ‘그 날짜에 가격조사가 가능한 경우에만’ 기준시점이 된다(제9조제2항 단서). ‘그 날짜로 하여야 한다’는 규정이 아니다."},{"번호":2,"판정":"옳음","설명":"감정평가조건을 붙일 수 있는 경우 중 하나가 법령에 다른 규정이 있는 경우다(제6조제2항제1호)."},{"번호":3,"판정":"옳음","설명":"일괄평가의 요건이다(제7조제2항)."},{"번호":4,"판정":"옳음","설명":"구분평가다(제7조제3항)."},{"번호":5,"판정":"옳음","설명":"일부분 평가다(제7조제4항)."}],"개념":[{"종류":"흐름","제목":"감정평가 절차 (규칙 제8조)","단계":[{"이름":"기본적 사항의 확정","설명":"의뢰인·대상물건·목적·기준시점·감정평가조건·기준가치·자문등·수수료 확정 (제9조제1항)"},{"이름":"처리계획 수립","설명":"평가 계획"},{"이름":"대상물건 확인","설명":"현장 확인"},{"이름":"자료수집 및 정리","설명":"사례·자료 수집"},{"이름":"자료검토 및 가치형성요인의 분석","설명":"일반요인·지역요인·개별요인 분석"},{"이름":"감정평가방법의 선정 및 적용","설명":"주된 방법과 다른 방식의 시산가액 비교"},{"이름":"감정평가액의 결정 및 표시","설명":"감정평가서 작성"}]},{"종류":"표","제목":"기준시점과 일괄·구분·일부 평가 (규칙 제7조·제9조)","머리":["항목","내용","조문"],"행":[["기준시점 원칙","가격조사를 완료한 날짜","제9조제2항"],["기준시점을 미리 정한 경우","그 날짜에 가격조사가 가능한 경우에만 기준시점으로 할 수 있다","제9조제2항 단서"],["일괄평가","일체 거래이거나 용도상 불가분 관계인 둘 이상의 물건","제7조제2항"],["구분평가","하나의 물건이라도 가치를 달리하는 부분","제7조제3항"],["일부분 평가","일체 이용 물건의 일부를 평가할 특수한 목적·합리적 이유","제7조제4항"]]}],"함정":"‘미리 정한 날짜로 한다’는 단정형과 ‘가격조사가 가능한 경우에만’이라는 조건형의 차이를 묻는다. 나머지 네 선지는 조문 문장 그대로다."},"35회-1차-057":{"한줄":"토지 소유자는 건물 임차인에게 건물에서의 퇴거를 청구할 수 있다.","근거":[{"법령":"민법","조문":"제213조","원문":"소유자는 그 소유에 속한 물건을 점유한 자에 대하여 반환을 청구할 수 있다. 그러나 점유자가 그 물건을 점유할 권리가 있는 때에는 반환을 거부할 수 있다."},{"법령":"민법","조문":"제214조","원문":"소유자는 소유권을 방해하는 자에 대하여 방해의 제거를 청구할 수 있고 소유권을 방해할 염려있는 행위를 하는 자에 대하여 그 예방이나 손해배상의 담보를 청구할 수 있다."},{"법령":"민법","조문":"제741조","원문":"법률상 원인없이 타인의 재산 또는 노무로 인하여 이익을 얻고 이로 인하여 타인에게 손해를 가한 자는 그 이익을 반환하여야 한다."},{"판례":"대법원 판례(건물 점유자에 대한 퇴거 청구)","요지":"건물을 점유하는 임차인은 그 건물의 점유로 토지 소유자의 소유권 행사를 방해하므로, 토지 소유자는 임차인에게 건물에서의 퇴거를 청구할 수 있다. 건물 소유자가 직접 점유하는 경우에는 철거와 토지 인도를 구하면 되고 퇴거를 따로 청구할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"甲은 건물 임차인 丙에게 퇴거를 청구할 수 있다. 丙의 점유가 甲의 소유권 행사를 방해하기 때문이다(제214조)."},{"번호":2,"판정":"옳음","설명":"甲은 건물 소유자 乙에게 건물 철거와 토지 인도를 청구할 수 있다(제213조, 제214조)."},{"번호":3,"판정":"옳음","설명":"권원 없이 토지를 사용한 乙은 차임 상당의 이익을 부당이득으로 반환해야 한다(제741조)."},{"번호":4,"판정":"옳음","설명":"건물 소유자 乙이 직접 점유하는 경우 철거와 토지 인도를 구하면 되므로 퇴거를 따로 청구할 수 없다."},{"번호":5,"판정":"옳음","설명":"소유자 乙은 권원 없이 건물을 점유한 丙에게 소유물반환청구권으로 인도를 청구할 수 있다(제213조)."}],"개념":[{"종류":"표","제목":"물권적 청구권 정리","머리":["청구권","근거","내용","상대방·요건"],"행":[["소유물반환청구권","제213조","점유를 빼앗긴 소유자가 물건의 반환을 청구","점유자, 점유할 권리가 있으면 거부 가능"],["소유물방해제거청구권","제214조 전단","방해 상태를 없애 달라고 청구","방해자, 상대방의 귀책사유 불필요"],["소유물방해예방청구권","제214조 후단","방해할 염려가 있을 때 예방·담보를 청구","방해할 염려가 있는 행위자"],["점유권에 기한 청구권","제204조~제206조","점유 회수(1년), 보유(방해 종료 후 1년), 보전","점유자, 제척기간 있음"]]},{"종류":"표","제목":"무단 건물에 대한 소유자의 청구 상대방","머리":["상대방","청구","비고"],"행":[["건물 소유자","건물 철거 + 토지 인도","직접 점유하는 소유자에게 퇴거 청구는 따로 하지 않음"],["건물 임차인 등 점유자","건물에서의 퇴거","철거 집행을 위해 점유자 퇴거 필요"],["건물 소유자","차임 상당 부당이득 반환","토지 무단 사용 기간 동안의 이익(제741조)"],["건물을 무단 점유하는 자","건물 소유자(乙)의 건물 인도 청구","제213조, 소유물반환청구"]]}],"함정":"선지 1은 건물 임차인에 대한 퇴거 청구가 가능하다는 점과 반대여서 틀린 문장이다. 선지 4처럼 건물 소유자가 직접 점유하면 퇴거는 청구하지 않고 철거와 토지 인도를 구한다."},"35회-1차-063":{"한줄":"정상이자 1년분 500만원과 변제기 이후 지연배상 1년분 500만원만 담보되어 원금 1억원을 더한 1억 1,000만원을 배당받는다.","근거":[{"법령":"민법","조문":"제360조","원문":"제360조(피담보채권의 범위) 저당권은 원본, 이자, 위약금, 채무불이행으로 인한 손해배상 및 저당권의 실행비용을 담보한다. 그러나 지연배상에 대하여는 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"원금 1억원에 이자 500만원(1년분)만 더한 금액이다. 변제기 이후 지연배상 1년분 500만원이 빠졌다."},{"번호":2,"판정":"-","설명":"원금 1억원 + 약정기간 이자 500만원 + 지연배상 1년분 500만원 = 1억 1,000만원(제360조 단서)."},{"번호":3,"판정":"-","설명":"원금에 이자 3년분(1,500만원)을 더한 값이다. 지연배상은 3년이 아니라 1년분만 담보된다."},{"번호":4,"판정":"-","설명":"원금에 이자 3.5년분(1,750만원)을 더한 값이다. 경매신청일(2023.7.1)까지 이자를 모두 센 결과이며 제360조 단서에 어긋난다."},{"번호":5,"판정":"-","설명":"원금에 이자 4년분(2,000만원)을 더한 값으로 채권신고액과 같다. 신고액이 커도 담보 범위는 제360조로 정해진다."}],"개념":[{"종류":"계산","제목":"저당권 피담보채권 범위 계산","단계":[{"설명":"원본","식":"대여금","값":"1억원"},{"설명":"약정기간(2020.1.1~12.31) 이자는 전부 담보","식":"1억원 × 5% × 1년","값":"500만원"},{"설명":"변제기(2020.12.31) 후 지연배상은 1년분만 저당권으로 담보","식":"1억원 × 5% × 1년","값":"500만원"},{"설명":"배당액","식":"1억원 + 500만원 + 500만원","값":"1억 1,000만원"}]},{"종류":"표","제목":"저당권 피담보채권의 범위(제360조)","머리":["항목","담보 여부","비고"],"행":[["원본","담보","-"],["약정 이자","담보","변제기까지의 이자 전부"],["위약금","담보","-"],["채무불이행 손해배상","담보","-"],["저당권 실행비용","담보","-"],["지연배상","원본 이행기일 경과 후 1년분만","그 이상은 저당권 행사 불가"]]}],"함정":"경매신청일(2023.7.1)이나 배당일(2023.12.31)까지의 이자를 모두 더하기 쉽다. 지연배상은 이행기 경과 후 1년분에 한하므로 3년이 넘게 지났어도 1년분만 가산한다. 후순위저당권자가 있어 초과분은 후순위자 몫이 된다."},"35회-1차-080":{"한줄":"임대차가 끝나도 보증금을 돌려받을 때까지는 임대차 관계가 존속하는 것으로 보므로 임대인은 종전 계약에서 정한 차임을 청구할 수 있다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제9조","원문":"제9조(임대차기간 등) ① 기간을 정하지 아니하거나 기간을 1년 미만으로 정한 임대차는 그 기간을 1년으로 본다. 다만, 임차인은 1년 미만으로 정한 기간이 유효함을 주장할 수 있다. ② 임대차가 종료한 경우에도 임차인이 보증금을 돌려받을 때까지는 임대차 관계는 존속하는 것으로 본다."},{"법령":"상가건물 임대차보호법","조문":"제2조제1항","원문":"제2조(적용범위) ① 이 법은 상가건물(제3조제1항에 따른 사업자등록의 대상이 되는 건물을 말한다)의 임대차(임대차 목적물의 주된 부분을 영업용으로 사용하는 경우를 포함한다)에 대하여 적용한다. 다만, 제14조의2에 따른 상가건물임대차위원회의 심의를 거쳐 대통령령으로 정하는 보증금액을 초과하는 임대차에 대하여는 그러하지 아니하다."},{"판례":"대법원 판례(임대차 종료 후 동시이행 항변권에 의한 점유)","요지":"보증금을 반환받지 못한 임차인이 동시이행의 항변권에 기해 목적물을 계속 점유하는 것은 불법점유가 아니어서 불법행위나 채무불이행 책임이 생기지 않는다."},{"판례":"대법원 판례(보증금반환채권과 유치권)","요지":"임차보증금반환채권은 임차목적물 자체에서 생긴 채권이 아니어서 견련성이 없으므로 이를 담보하는 유치권은 성립하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"보증금을 받을 때까지 동시이행 항변권에 따라 점유하는 것은 불법점유가 아니어서 불법행위가 성립하지 않는다."},{"번호":2,"판정":"틀림","설명":"같은 이유로 동시이행 항변권에 기한 점유에는 이행지체 책임이 없다. 채무불이행 손해배상의무가 생기지 않는다."},{"번호":3,"판정":"틀림","설명":"임대차 관계가 존속하는 것으로 보는 이상(제9조 제2항) 부당이득이 아니라 임대차 관계에 따른 차임이 문제된다."},{"번호":4,"판정":"옳음","설명":"제9조 제2항에 따라 임대차 관계가 존속하는 것으로 보므로 종전 계약에서 정한 차임을 청구할 수 있다."},{"번호":5,"판정":"틀림","설명":"보증금반환채권은 목적물에 관하여 생긴 채권이 아니어서 견련성이 없고, 유치권은 성립하지 않는다(제320조 제1항)."}],"개념":[{"종류":"표","제목":"상가건물임대차보호법 주요 기간·요건","머리":["구분","내용","근거"],"행":[["적용범위","보증금이 시행령 환산보증금 한도 이하(서울 9억원 등). 월차임은 100을 곱해 환산","법 제2조, 시행령 제2조"],["대항력","건물 인도 + 사업자등록 신청 → 다음 날부터","법 제3조 제1항"],["우선변제","대항요건 + 관할 세무서장의 확정일자","법 제5조 제2항"],["최단 존속기간","1년 미만은 1년으로 간주(임차인은 유효 주장 가능)","법 제9조 제1항"],["갱신요구권","6개월~1개월 전, 전체 10년 이내","법 제10조 제1항·제2항"],["묵시적 갱신","존속기간 1년, 임차인은 언제든 해지(3개월 후 효력)","법 제10조 제4항·제5항"],["차임연체 해지","3기의 차임액","법 제10조의8"],["권리금 회수기회","임대차 종료 6개월 전~종료 시, 손해배상 시효 3년","법 제10조의4"]]},{"종류":"계산","제목":"환산보증금 계산","단계":[{"설명":"환산보증금 = 보증금 + 월차임 × 100","식":"3억원 + 60만원 × 100","값":"3억 6천만원"},{"설명":"한도(서울특별시)와 비교","식":"3억 6천만원 ≤ 9억원","값":"법 적용 가능"}]}],"함정":"임대차 종료 후 임차인의 점유를 불법점유로 보아 불법행위·채무불이행·부당이득을 고르기 쉽다. 제9조 제2항 때문에 임대차 관계가 존속하는 것으로 보아 종전 차임을 청구하는 구조이다. 유치권은 견련성이 없어 성립하지 않는다."},"35회-2차-015":{"한줄":"주택 소재지와 사무소 소재지가 다르면 중개사무소 소재지를 관할하는 시·도의 조례를 따른다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제20조제3항","원문":"제1항 및 제2항의 경우에 중개대상물의 소재지와 중개사무소의 소재지가 다른 경우에는 개업공인중개사는 중개사무소의 소재지를 관할하는 시ㆍ도의 조례에서 정한 기준에 따라 중개보수 및 실비를 받아야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제1항","원문":"법 제32조제4항에 따른 주택의 중개에 대한 보수는 중개의뢰인 쌍방으로부터 각각 받되, 그 일방으로부터 받을 수 있는 한도는 별표 1과 같으며, 그 금액은 법 제32조제4항에 따라 시ㆍ도의 조례로 정하는 요율한도 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다."},{"법령":"공인중개사법 시행령","조문":"제27조의2","원문":"법 제32조제3항에 따른 중개보수의 지급시기는 개업공인중개사와 중개의뢰인간의 약정에 따르되, 약정이 없을 때에는 중개대상물의 거래대금 지급이 완료된 날로 한다."},{"법령":"공인중개사법","조문":"제32조제2항","원문":"개업공인중개사는 중개의뢰인으로부터 제25조제1항에 따른 중개대상물의 권리관계 등의 확인 또는 제31조에 따른 계약금등의 반환채무이행 보장에 소요되는 실비를 받을 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사의 과실로 거래행위가 무효가 되면 보수를 받지 못한다(법 제32조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"주택 보수는 쌍방에게 각각 받고 조례의 요율한도 안에서 협의한다(규칙 제20조제1항)."},{"번호":3,"판정":"옳음","설명":"약정이 없으면 거래대금 지급이 완료된 날이다(영 제27조의2)."},{"번호":4,"판정":"틀림","설명":"중개사무소 소재지 시·도의 조례를 따른다(규칙 제20조제3항)."},{"번호":5,"판정":"옳음","설명":"권리관계 확인 실비는 받을 수 있다(법 제32조제2항)."}],"개념":[{"종류":"표","제목":"주택 중개보수 상한요율(규칙 별표 1)","머리":["거래내용","거래금액","상한요율","한도액"],"행":[["매매·교환","5천만원 미만","1천분의 6","25만원"],["매매·교환","5천만원 이상 2억원 미만","1천분의 5","80만원"],["매매·교환","2억원 이상 9억원 미만","1천분의 4","-"],["매매·교환","9억원 이상 12억원 미만","1천분의 5","-"],["매매·교환","12억원 이상 15억원 미만","1천분의 6","-"],["매매·교환","15억원 이상","1천분의 7","-"],["임대차 등","5천만원 미만","1천분의 5","20만원"],["임대차 등","5천만원 이상 1억원 미만","1천분의 4","30만원"],["임대차 등","1억원 이상 6억원 미만","1천분의 3","-"],["임대차 등","6억원 이상 12억원 미만","1천분의 4","-"],["임대차 등","12억원 이상 15억원 미만","1천분의 5","-"],["임대차 등","15억원 이상","1천분의 6","-"]]},{"종류":"표","제목":"중개대상물별 보수 규정","머리":["구분","정하는 법령","상한"],"행":[["주택(부속토지 포함)","국토교통부령 범위 안에서 시·도 조례. 사무소 소재지 시·도 조례 적용","규칙 별표 1의 요율·한도액"],["요건을 갖춘 오피스텔","국토교통부령(규칙 별표 2)","매매·교환 1천분의 5, 임대차 등 1천분의 4"],["그 밖의 주택 외 중개대상물","국토교통부령","거래금액의 1천분의 9 이내에서 협의, 사무소 요율표에 자기 상한 명시"],["실비","주택의 실비 한도는 조례(법 제32조제4항). 권리관계 확인 실비는 권리를 넘기는 쪽, 반환채무이행 보장 실비는 권리를 얻는 쪽에 청구","영수증 첨부"]]}],"함정":"선지 4는 주택 소재지를 기준으로 삼았다. 주택 보수와 실비는 중개사무소 소재지 시·도 조례가 기준이고, 주택 외 물건의 보수는 조례가 아니라 국토교통부령이다.","개정":"주택 중개보수는 규칙 제20조제1항·별표 1(신설 2021.10.19)의 상한요율과 한도액 안에서 시·도 조례가 정한다. 임대차 등을 1천분의 8 이내에서 조례로 정한다고 본 옛 기출 해설은 현행과 다르다."},"35회-2차-017":{"한줄":"확인·설명서 미교부는 개설등록 취소 사유가 아니라 업무정지 사유다(법 제39조제1항제6호).","근거":[{"법령":"공인중개사법","조문":"제38조제1항제1호·제2호·제5호·제7호","원문":"①등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소하여야 한다.\n1. 개인인 개업공인중개사가 사망하거나 개업공인중개사인 법인이 해산한 경우\n2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 경우\n5. 제12조제2항의 규정을 위반하여 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 된 경우\n7. 업무정지기간 중에 중개업무를 하거나 자격정지처분을 받은 소속공인중개사로 하여금 자격정지기간 중에 중개업무를 하게 한 경우"},{"법령":"공인중개사법","조문":"제39조제1항제6호","원문":"①등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 업무의 정지를 명할 수 있다. 이 경우 법인인 개업공인중개사에 대하여는 법인 또는 분사무소별로 업무의 정지를 명할 수 있다.\n6. 제25조제3항의 규정을 위반하여 중개대상물확인ㆍ설명서를 교부하지 아니하거나 보존하지 아니한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"취소 사유가 아니다. 확인·설명서를 교부하지 않거나 보존하지 않으면 업무정지를 할 수 있다(법 제39조제1항제6호)."},{"번호":2,"판정":"옳음","설명":"거짓이나 부정한 방법의 등록은 필요적 취소 사유다(법 제38조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"업무정지기간 중 중개업무는 필요적 취소 사유다(법 제38조제1항제7호)."},{"번호":4,"판정":"옳음","설명":"다른 개업공인중개사의 소속이 되거나 법인의 사원·임원이 되면 필요적 취소다(법 제38조제1항제5호, 제12조제2항)."},{"번호":5,"판정":"옳음","설명":"개인인 개업공인중개사의 사망은 필요적 취소 사유다(법 제38조제1항제1호)."}],"개념":[{"종류":"표","제목":"등록취소와 업무정지의 구분","머리":["위반행위","처분","근거"],"행":[["거짓·부정한 방법의 등록","등록취소(필요적)","법 제38조제1항제2호"],["업무정지기간 중 중개업무","등록취소(필요적)","법 제38조제1항제7호"],["다른 사무소의 소속 또는 법인의 사원·임원이 됨","등록취소(필요적)","법 제38조제1항제5호"],["개인 사망·법인 해산","등록취소(필요적)","법 제38조제1항제1호"],["확인·설명서 미교부·미보존","업무정지(임의)","법 제39조제1항제6호"],["확인·설명서 서명·날인 누락","업무정지(임의)","법 제39조제1항제7호"],["거래계약서 서명·날인 누락","업무정지(임의)","법 제39조제1항제9호"]]},{"종류":"비교","제목":"필요적 취소와 임의적 취소","왼쪽":{"이름":"필요적 취소(법 제38조제1항)","항목":["등록관청이 반드시 취소","사망·해산, 거짓 등록, 결격사유, 이중등록, 이중소속, 중개보조원 수 초과, 성명·상호 대여, 업무정지 중 업무, 1년 안 업무정지 2회 후 재위반","제1호를 뺀 나머지는 청문 후 취소"]},"오른쪽":{"이름":"임의적 취소(법 제38조제2항)","항목":["등록관청이 취소할 수 있다","등록기준 미달, 둘 이상 사무소, 임시 중개시설물, 겸업, 6개월 초과 휴업, 거래계약서 거짓 기재, 보증 없이 업무 개시, 금지행위 등","모두 청문 후 취소"]}}],"함정":"확인·설명서와 관련된 위반은 중한 처분으로 이어질 것 같지만 업무정지에 그친다. 선지 4는 개업공인중개사가 다른 법인의 사원·임원이 되는 것이라 이중소속에 해당해 필요적 취소다."},"35회-2차-024":{"한줄":"보증금과 차임의 증감 없이 기간만 연장하는 갱신계약은 신고 대상에서 제외된다(영 제4조의3제1항 괄호).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제4조의3제1항·제2항","원문":"① 법 제6조의2제1항 본문에서 \"대통령령으로 정하는 금액을 초과하는 임대차 계약\"이란 보증금이 6천만원을 초과하거나 월 차임이 30만원을 초과하는 주택 임대차 계약(계약을 갱신하는 경우로서 보증금 및 차임의 증감 없이 임대차 기간만 연장하는 계약은 제외한다)을 말한다.\n② 법 제6조의2제2항에서 \"대통령령으로 정하는 지역\"이란 특별자치시ㆍ특별자치도ㆍ시ㆍ군(광역시 및 경기도의 관할구역에 있는 군으로 한정한다)ㆍ구(자치구를 말한다)를 말한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제6조의2제1항","원문":"① 임대차계약당사자는 주택(「주택임대차보호법」 제2조에 따른 주택을 말하며, 주택을 취득할 수 있는 권리를 포함한다. 이하 같다)에 대하여 대통령령으로 정하는 금액을 초과하는 임대차 계약을 체결한 경우 그 보증금 또는 차임 등 국토교통부령으로 정하는 사항을 임대차 계약의 체결일부터 30일 이내에 주택 소재지를 관할하는 신고관청에 공동으로 신고하여야 한다. 다만, 임대차계약당사자 중 일방이 국가등인 경우에는 국가등이 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제3조제2항","원문":"② 법 제3조제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 자\"란 다음 각 호의 기관을 말한다.\n1. 「공공기관의 운영에 관한 법률」에 따른 공공기관\n2. 「지방공기업법」에 따른 지방직영기업ㆍ지방공사 또는 지방공단"}],"선지":[{"번호":1,"판정":"틀림","설명":"보증금 6천만원은 ‘초과’가 아니고 월 차임 30만원도 ‘초과’가 아니라서 신고 대상이 아니다."},{"번호":2,"판정":"틀림","설명":"월 차임 40만원은 30만원을 초과하므로 보증금이 5천만원이어도 신고 대상이다."},{"번호":3,"판정":"틀림","설명":"일방이 국가등(지방공사 포함)이면 국가등이 신고한다. 공동신고가 아니다(법 제6조의2제1항 단서)."},{"번호":4,"판정":"옳음","설명":"군은 광역시와 경기도에 속한 군만 지역 요건에 들고(영 제4조의3제2항), 금액 증감 없는 갱신계약은 제외된다(제1항)."},{"번호":5,"판정":"틀림","설명":"주택 임대차 신고의무자는 임대차계약당사자다. 중개한 개업공인중개사에게 신고의무가 없다(법 제6조의2제1항)."}],"개념":[{"종류":"표","제목":"주택 임대차 신고 요건","머리":["항목","내용","근거"],"행":[["금액","보증금 6천만원 초과 또는 월 차임 30만원 초과(하나만 넘어도 대상)","영 제4조의3제1항"],["지역","특별자치시·특별자치도·시·구, 군은 광역시·경기도 소속 군만","영 제4조의3제2항"],["갱신계약","보증금·차임 증감 없이 기간만 연장하면 제외","영 제4조의3제1항"],["기한","계약 체결일부터 30일 이내","법 제6조의2제1항"],["신고의무자","임대차계약당사자 공동, 일방이 국가등이면 국가등 단독","법 제6조의2제1항"],["일방이 거부","국토교통부령에 따라 단독 신고","법 제6조의2제3항"],["신고 효과","전입신고로 신고 의제, 임대차계약서를 낸 신고는 확정일자 의제","법 제6조의5"],["과태료","신고·변경·해제 신고를 하지 않거나 거짓으로 하면 100만원 이하","법 제28조제5항제3호"]]},{"종류":"비교","제목":"부동산 거래신고와 주택 임대차 신고","왼쪽":{"이름":"부동산 거래신고(제3조)","항목":["대상: 매매, 공급계약, 분양권·입주권 매매","계약서를 쓴 개업공인중개사가 신고","신고필증 발급 시 검인 의제","미신고 과태료 500만원 이하"]},"오른쪽":{"이름":"주택 임대차 신고(제6조의2)","항목":["대상: 보증금 6천만원 초과 또는 월 차임 30만원 초과 주택 임대차(지역 한정)","임대차계약당사자가 신고, 개업공인중개사 신고의무 없음","계약서를 낸 신고는 확정일자 의제","미신고 과태료 100만원 이하"]}}],"함정":"6천만원과 30만원은 기준선 그 자체라서 대상이 아니다. 보증금이 기준 이하여도 월 차임이 30만원을 넘으면 대상이다. 매매 신고와 달리 개업공인중개사에게 신고의무가 없고, 일방이 국가등이면 공동신고가 아니라 국가등 단독 신고다."},"35회-2차-038":{"한줄":"임차인은 건물을 양수인에게 인도하지 않으면 우선변제 보증금을 받을 수 없다(상가법 제5조제3항).","근거":[{"법령":"상가건물 임대차보호법","조문":"제3조제1항","원문":"① 임대차는 그 등기가 없는 경우에도 임차인이 건물의 인도와 「부가가치세법」 제8조, 「소득세법」 제168조 또는 「법인세법」 제111조에 따른 사업자등록을 신청하면 그 다음 날부터 제3자에 대하여 효력이 생긴다."},{"법령":"상가건물 임대차보호법","조문":"제4조제1항·제4항","원문":"① 제5조제2항의 확정일자는 상가건물의 소재지 관할 세무서장이 부여한다.\n④ 임대차계약을 체결하려는 자는 임대인의 동의를 받아 관할 세무서장에게 제3항에 따른 정보제공을 요청할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제10조제1항제2호","원문":"① 임대인은 임차인이 임대차기간이 만료되기 6개월 전부터 1개월 전까지 사이에 계약갱신을 요구할 경우 정당한 사유 없이 거절하지 못한다. 다만, 다음 각 호의 어느 하나의 경우에는 그러하지 아니하다.\n2. 임차인이 거짓이나 그 밖의 부정한 방법으로 임차한 경우"},{"법령":"상가건물 임대차보호법","조문":"제5조제2항·제3항","원문":"② 제3조제1항의 대항요건을 갖추고 관할 세무서장으로부터 임대차계약서상의 확정일자를 받은 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매 시 임차건물(임대인 소유의 대지를 포함한다)의 환가대금에서 후순위권리자나 그 밖의 채권자보다 우선하여 보증금을 변제받을 권리가 있다.\n③ 임차인은 임차건물을 양수인에게 인도하지 아니하면 제2항에 따른 보증금을 받을 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"건물의 인도와 사업자등록 신청을 하면 그 다음 날부터 제3자에 대하여 효력이 생긴다(제3조제1항)."},{"번호":2,"판정":"옳음","설명":"확정일자는 상가건물 소재지 관할 세무서장이 부여한다(제4조제1항)."},{"번호":3,"판정":"옳음","설명":"임대차계약을 체결하려는 자는 임대인의 동의를 받아 관할 세무서장에게 정보제공을 요청할 수 있다(제4조제4항)."},{"번호":4,"판정":"옳음","설명":"거짓이나 부정한 방법으로 임차한 경우는 갱신요구 거절 사유다(제10조제1항제2호)."},{"번호":5,"판정":"틀림","설명":"순서가 반대다. 건물을 양수인에게 인도해야 우선변제 보증금을 받을 수 있다(제5조제3항)."}],"개념":[{"종류":"비교","제목":"주택임대차와 상가임대차","왼쪽":{"이름":"주택임대차보호법","항목":["대항요건: 주택의 인도 + 주민등록(전입신고)","확정일자: 읍·면사무소, 동 주민센터, 법원·등기소, 공증인 등","최단 기간 2년","갱신요구: 만료 6개월~2개월 전, 1회, 2년","차임 연체 2기: 갱신 거절·갱신요구 거절 사유","묵시적 갱신: 임대인이 6개월~2개월 전 통지 안 하면 2년"]},"오른쪽":{"이름":"상가건물 임대차보호법","항목":["대항요건: 건물의 인도 + 사업자등록 신청","확정일자: 관할 세무서장","최단 기간 1년","갱신요구: 만료 6개월~1개월 전, 전체 임대차기간 10년 이내","차임 연체 3기: 갱신요구 거절·해지 사유","묵시적 갱신: 임대인이 6개월~1개월 전 통지 안 하면 1년"]}},{"종류":"표","제목":"우선변제와 소멸","머리":["항목","상가건물 임대차보호법"],"행":[["우선변제권 요건","대항요건 + 관할 세무서장의 확정일자(제5조제2항)"],["보증금을 받을 때","건물을 양수인에게 인도해야 함(제5조제3항)"],["경매 시 임차권","매각되면 소멸, 보증금이 전액 변제되지 않은 대항력 있는 임차권은 제외(제8조)"],["임차권등기명령","임대차 종료 후 보증금 미반환 시 신청, 등기 후 대항력·우선변제권 유지(제6조)"],["소액보증금 보호","경매신청 등기 전에 대항요건을 갖추면 보증금 중 일정액을 우선변제(제14조)"]]}],"함정":"우선변제를 받는 순서가 인도 → 보증금 수령이다. 경매 환가대금을 먼저 받고 나중에 인도해도 된다는 문장은 제5조제3항과 반대다. 갱신거절 사유(거짓 임차, 3기 연체)와 숫자는 주택법과 맞바꿔 내기 쉽다."},"35회-2차-031":{"한줄":"법인은 4억원 이상이고 분사무소마다 2억원 이상을 추가하므로, 분사무소 1개면 6억원 이상이다(규칙 제13조제1항제1호).","근거":[{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제13조제1항","원문":"①개업공인중개사가 제11조제2항의 규정에 따른 손해배상책임을 보장하기 위한 보증을 설정하여야 하는 금액은 다음 각 호와 같다.\n1. 법인인 개업공인중개사 : 4억 원 이상. 다만, 분사무소를 두는 경우에는 분사무소마다 2억 원 이상을 추가로 설정하여야 한다.\n2. 법인이 아닌 개업공인중개사 : 2억 원 이상"},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제15조제1항","원문":"①개업공인중개사는 매수신청대리 사건카드를 비치하고, 사건을 위임받은 때에는 사건카드에 위임받은 순서에 따라 일련번호, 경매사건번호, 위임받은 연월일, 보수액과 위임인의 주소ㆍ성명 기타 필요한 사항을 기재하고, 서명날인 한 후 5년간 이를 보존하여야 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제16조제1항·제2항","원문":"①개업공인중개사가 매수신청대리를 위임받은 경우 매수신청대리 대상물의 권리관계, 경제적 가치, 매수인이 부담하여야 할 사항 등에 대하여 위임인에게 성실ㆍ정확하게 설명하고 등기사항증명서 등 설명의 근거자료를 제시하여야 한다.\n②개업공인중개사는 위임계약을 체결한 경우 제1항의 확인ㆍ설명 사항을 서면으로 작성하여 서명날인한 후 위임인에게 교부하고, 그 사본을 사건카드에 철하여 5년간 보존하여야 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제18조제4항제1호","원문":"④개업공인중개사는 다음 각 호의 어느 하나에 해당하는 경우에는 그 사유가 발생한 날로부터 10일 이내에 지방법원장에게 그 사실을 신고하여야 한다.\n1. 중개사무소를 이전한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"법인 4억원 + 분사무소 1개 2억원 = 6억원 이상이다(규칙 제13조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"사건카드의 보존기간은 5년이다(규칙 제15조제1항)."},{"번호":3,"판정":"틀림","설명":"확인·설명 사항은 서면으로 작성해 위임인에게 교부하고, 사본을 사건카드에 철해 5년간 보존한다(규칙 제16조제2항)."},{"번호":4,"판정":"틀림","설명":"등기사항증명서는 설명의 근거자료로 예시된 자료다(규칙 제16조제1항)."},{"번호":5,"판정":"틀림","설명":"사무소를 이전하면 10일 이내에 지방법원장에게 신고한다. 위임인에게 통지하라는 규정은 없다(규칙 제18조제4항제1호)."}],"개념":[{"종류":"계산","제목":"매수신청대리 보증금액","단계":[{"설명":"법인이 아닌 개업공인중개사","식":"기본 2억원 이상","값":"2억원 이상"},{"설명":"법인인 개업공인중개사","식":"기본 4억원 이상","값":"4억원 이상"},{"설명":"법인에 분사무소를 두는 경우","식":"4억원 + 2억원 × 분사무소 수","값":"분사무소 1개: 6억원 이상, 2개: 8억원 이상"}]},{"종류":"표","제목":"매수신청대리 규칙의 숫자","머리":["사항","내용","근거"],"행":[["사건카드 보존","서명날인 후 5년","규칙 제15조제1항"],["확인·설명서 사본","사건카드에 철하여 5년 보존, 위임인에게 교부","규칙 제16조제2항"],["신고 기한","사무소 이전·휴업·폐업·자격취소·정지 등은 사유 발생일부터 10일 이내 지방법원장에게","규칙 제18조제4항"],["실무교육","등록신청일 전 1년 이내에 이수","규칙 제10조제1항"],["공탁금 회수","폐업, 사망, 해산한 날부터 3년 이내 회수 불가","규칙 제11조제3항"],["업무정지 기간","1월 이상 2년 이하","규칙 제22조제3항"]]}],"함정":"숫자 선지가 섞여 있다. 사건카드와 확인·설명서 사본은 5년(일반 중개의 확인·설명서 보존기간 3년과 혼동하기 쉽다), 신고는 10일에 지방법원장이다. 설명의 근거자료에 등기사항증명서가 빠진다는 문장도 틀리다."},"35회-2차-048":{"한줄":"관리지역의 농업진흥지역은 농림지역으로 결정·고시된 것으로 본다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제42조제2항","원문":"② 관리지역에서 「농지법」에 따른 농업진흥지역으로 지정ㆍ고시된 지역은 이 법에 따른 농림지역으로, 관리지역의 산림 중 「산지관리법」에 따라 보전산지로 지정ㆍ고시된 지역은 그 고시에서 구분하는 바에 따라 이 법에 따른 농림지역 또는 자연환경보전지역으로 결정ㆍ고시된 것으로 본다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제15호","원문":"15. \"용도지역\"이란 토지의 이용 및 건축물의 용도, 건폐율(「건축법」 제55조의 건폐율을 말한다. 이하 같다), 용적률(「건축법」 제56조의 용적률을 말한다. 이하 같다), 높이 등을 제한함으로써 토지를 경제적ㆍ효율적으로 이용하고 공공복리의 증진을 도모하기 위하여 서로 중복되지 아니하게 도시ㆍ군관리계획으로 결정하는 지역을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제36조제1항","원문":"① 국토교통부장관, 시ㆍ도지사 또는 대도시 시장은 다음 각 호의 어느 하나에 해당하는 용도지역의 지정 또는 변경을 도시ㆍ군관리계획으로 결정한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제41조제2항","원문":"② 공유수면의 매립 목적이 그 매립구역과 이웃하고 있는 용도지역의 내용과 다른 경우 및 그 매립구역이 둘 이상의 용도지역에 걸쳐 있거나 이웃하고 있는 경우 그 매립구역이 속할 용도지역은 도시ㆍ군관리계획결정으로 지정하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제19조의2제3항제2호","원문":"2. 지정 대상 지역이 자연녹지지역ㆍ계획관리지역 또는 생산관리지역일 것. 다만, 계획관리지역에 있는 기존 공장의 증축이 필요한 경우로서 해당 공장이 도로ㆍ철도ㆍ하천ㆍ건축물ㆍ바다 등으로 둘러싸여 있어 증축을 위해서는 불가피하게 보전관리지역 또는 농림지역을 포함해야 하는 경우에는 전체 면적의 20퍼센트 이하의 범위에서 보전관리지역 또는 농림지역을 포함하되, 다음 각 목의 어느 하나에 해당하는 경우에는 20퍼센트 이상으로 할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"용도지역은 서로 중복되지 않게 도시·군관리계획으로 결정하는 지역이다(법 제2조제15호). 용도지구는 용도지역과 겹쳐 지정한다."},{"번호":2,"판정":"틀림","설명":"용도지역의 지정·변경은 도시·군관리계획으로 결정한다(법 제36조제1항). 도시·군기본계획으로 결정하지 않는다."},{"번호":3,"판정":"틀림","설명":"산업·유통개발진흥지구의 지정을 제안할 수 있는 지역은 자연녹지지역·계획관리지역·생산관리지역이다. 상업지역은 대상이 아니다(영 제19조의2제3항제2호)."},{"번호":4,"판정":"틀림","설명":"매립구역이 둘 이상의 용도지역에 걸치거나 이웃하는 경우에는 도시·군관리계획결정으로 지정한다. 가장 큰 용도지역으로 보는 규정은 없다(법 제41조제2항)."},{"번호":5,"판정":"옳음","설명":"관리지역 안의 농업진흥지역은 농림지역으로 결정·고시된 것으로 본다(법 제42조제2항)."}],"개념":[{"종류":"표","제목":"다른 법률에 따라 용도지역으로 의제되는 지역","머리":["구분","지정된 지역","의제되는 용도지역","근거"],"행":[["도시지역","항만구역(도시지역 연접 공유수면), 어항구역(도시지역 연접 공유수면)","도시지역","제42조제1항제1호·제2호"],["도시지역","국가산업단지·일반산업단지·도시첨단산업단지","도시지역","제42조제1항제3호"],["도시지역","택지개발촉진법상 택지개발지구","도시지역","제42조제1항제4호"],["도시지역","전원개발사업구역·예정구역(수력발전소·송변전설비만 설치하는 구역 제외)","도시지역","제42조제1항제5호"],["농림지역","관리지역 안의 농업진흥지역","농림지역","제42조제2항"],["농림지역 또는 자연환경보전지역","관리지역 안의 보전산지","고시에서 구분하는 바에 따라","제42조제2항"]]},{"종류":"표","제목":"공유수면(바다) 매립지의 용도지역","머리":["경우","용도지역 결정","근거"],"행":[["매립 목적이 이웃 용도지역의 내용과 같음","도시·군관리계획 절차 없이 준공인가일부터 이웃 용도지역으로 지정된 것으로 봄","제41조제1항"],["매립 목적이 이웃 용도지역과 다름","도시·군관리계획결정으로 지정","제41조제2항"],["매립구역이 둘 이상의 용도지역에 걸치거나 이웃함","도시·군관리계획결정으로 지정","제41조제2항"]]}],"함정":"용도지역은 서로 겹치지 않고 도시·군관리계획으로 결정한다. 공유수면 매립구역이 둘 이상의 용도지역과 이웃하면 가장 큰 용도지역으로 보지 않고 관리계획결정으로 지정한다. 산업·유통개발진흥지구 제안 대상은 자연녹지지역·계획관리지역·생산관리지역이다."},"35회-2차-094":{"한줄":"근저당권설정등기의 말소등기는 법률에 단독신청 규정이 없으므로 등기권리자와 등기의무자가 공동으로 신청한다.","근거":[{"법령":"부동산등기법","조문":"제23조제1항","원문":"① 등기는 법률에 다른 규정이 없는 경우에는 등기권리자(登記權利者)와 등기의무자(登記義務者)가 공동으로 신청한다."},{"법령":"부동산등기법","조문":"제23조제2항ㆍ제3항ㆍ제6항","원문":"② 소유권보존등기(所有權保存登記) 또는 소유권보존등기의 말소등기(抹消登記)는 등기명의인으로 될 자 또는 등기명의인이 단독으로 신청한다.\n③ 상속, 법인의 합병, 그 밖에 대법원규칙으로 정하는 포괄승계에 따른 등기는 등기권리자가 단독으로 신청한다.\n⑥ 등기명의인표시의 변경이나 경정의 등기는 해당 권리의 등기명의인이 단독으로 신청한다."},{"법령":"부동산등기법","조문":"제99조제1항","원문":"① 수용으로 인한 소유권이전등기는 제23조제1항에도 불구하고 등기권리자가 단독으로 신청할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"소유권보존등기의 말소등기는 등기명의인이 단독으로 신청한다(법 제23조제2항)."},{"번호":2,"판정":"-","설명":"법인의 합병에 따른 포괄승계 등기는 등기권리자가 단독으로 신청한다(법 제23조제3항)."},{"번호":3,"판정":"-","설명":"등기명의인표시의 변경이나 경정의 등기는 해당 권리의 등기명의인이 단독으로 신청한다(법 제23조제6항)."},{"번호":4,"판정":"-","설명":"수용으로 인한 소유권이전등기는 사업시행자(등기권리자)가 단독으로 신청한다(법 제99조제1항)."},{"번호":5,"판정":"-","설명":"근저당권 말소는 소유자(등기권리자)와 근저당권자(등기의무자)의 공동신청이 원칙이다(법 제23조제1항)."}],"개념":[{"종류":"표","제목":"단독신청이 허용되는 등기","머리":["등기","단독 신청인","근거"],"행":[["소유권보존등기, 그 말소등기","등기명의인으로 될 자 또는 등기명의인","법 제23조제2항"],["상속, 법인의 합병 등 포괄승계에 따른 등기","등기권리자","법 제23조제3항"],["등기절차의 이행 또는 인수를 명하는 판결에 의한 등기","승소한 등기권리자 또는 등기의무자","법 제23조제4항"],["부동산표시의 변경이나 경정의 등기","소유권의 등기명의인","법 제23조제5항"],["등기명의인표시의 변경이나 경정의 등기","해당 권리의 등기명의인","법 제23조제6항"],["신탁등기","수탁자","법 제23조제7항"],["신탁등기의 말소등기","수탁자","법 제87조제3항"],["수용으로 인한 소유권이전등기","등기권리자(사업시행자)","법 제99조제1항"],["가등기","가등기권리자(가등기의무자의 승낙이나 가처분명령이 있을 때)","법 제89조"]]},{"종류":"비교","제목":"공동신청과 단독신청","왼쪽":{"이름":"공동신청 (원칙)","항목":["등기권리자와 등기의무자가 함께 신청","매매 등으로 인한 소유권이전등기","저당권ㆍ근저당권 등 설정등기","변제 또는 해지로 인한 근저당권 말소등기","해제ㆍ무효 등으로 인한 소유권이전등기의 말소등기"]},"오른쪽":{"이름":"단독신청 (법률에 규정이 있는 경우)","항목":["보존등기와 그 말소등기","상속ㆍ합병 등 포괄승계","판결에 의한 등기","표시 변경ㆍ경정, 등기명의인표시 변경ㆍ경정","신탁등기, 수용으로 인한 이전등기"]}}],"함정":"‘말소등기’라는 말에 끌려 단독신청으로 읽기 쉽다. 단독으로 신청하는 말소는 소유권보존등기의 말소와 신탁등기의 말소처럼 법에 규정이 있는 것뿐이다. 변제로 소멸한 근저당권의 말소는 설정자와 근저당권자가 공동으로 신청한다."},"35회-2차-110":{"한줄":"국가에 귀속시키는 조건으로 취득하더라도 그 반대급부로 국가 소유 부동산을 무상으로 양여받는 부분에는 취득세를 부과한다.","근거":[{"법령":"지방세법","조문":"제9조제2항제2호","원문":"국가등에 귀속등의 반대급부로 국가등이 소유하고 있는 부동산 및 사회기반시설을 무상으로 양여받거나 기부채납 대상물의 무상사용권을 제공받는 경우"},{"법령":"지방세법","조문":"제9조제1항 단서","원문":"다만, 대한민국 정부기관의 취득에 대하여 과세하는 외국정부의 취득에 대해서는 취득세를 부과한다."},{"법령":"지방세법","조문":"제7조제4항","원문":"선박, 차량과 기계장비의 종류를 변경하거나 토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다."},{"법령":"지방세법","조문":"제9조제5항","원문":"임시흥행장, 공사현장사무소 등(제13조제5항에 따른 과세대상은 제외한다) 임시건축물의 취득에 대하여는 취득세를 부과하지 아니한다. 다만, 존속기간이 1년을 초과하는 경우에는 취득세를 부과한다."},{"법령":"지방세법","조문":"제9조제3항 단서","원문":"다만, 신탁재산의 취득 중 주택조합등과 조합원 간의 부동산 취득 및 주택조합등의 비조합원용 부동산 취득은 제외한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"외국정부의 취득은 비과세가 원칙이다. 대한민국 정부기관의 취득에 과세하는 외국정부의 취득은 과세한다(지방세법 제9조 제1항 단서)."},{"번호":2,"판정":"옳음","설명":"토지의 지목을 사실상 변경해 가액이 증가하면 취득으로 본다. 가액이 줄어든 변경은 취득이 아니다(지방세법 제7조 제4항)."},{"번호":3,"판정":"틀림","설명":"귀속·기부채납을 조건으로 한 취득은 비과세이나, 그 반대급부로 국가 소유 부동산을 무상 양여받는 부분은 취득세를 부과한다(지방세법 제9조 제2항 제2호)."},{"번호":4,"판정":"옳음","설명":"임시건축물은 비과세이나 존속기간이 1년을 초과하면 취득세를 부과한다(지방세법 제9조 제5항 단서)."},{"번호":5,"판정":"옳음","설명":"신탁등기가 병행되는 신탁의 취득은 비과세 유형이 있으나, 주택조합등과 조합원 간 부동산 취득은 제외되어 과세한다(지방세법 제9조 제3항 단서)."}],"개념":[{"종류":"표","제목":"취득세 비과세와 그 예외(제9조)","머리":["비과세 대상","비과세 범위","과세되는 예외"],"행":[["국가·지방자치단체·지방자치단체조합·외국정부·주한국제기구","취득 전부","대한민국 정부기관의 취득에 과세하는 외국정부"],["국가등에 귀속·기부채납을 조건으로 취득하는 부동산","취득 전부","조건 불이행 후 매각·증여, 반대급부로 국가 소유 부동산을 무상 양여받거나 기부채납 대상물의 무상사용권을 제공받는 부분"],["신탁등기가 병행되는 신탁","위탁자→수탁자 이전, 신탁 종료로 수탁자→위탁자 이전, 수탁자 변경에 따른 이전","주택조합등과 조합원 간 취득, 주택조합등의 비조합원용 부동산 취득"],["임시흥행장·공사현장사무소 등 임시건축물","존속기간 1년 이하","존속기간 1년 초과"],["공동주택 개수(대수선 제외)","개수 취득 당시 시가표준액 9억원 이하 주택","시가표준액 9억원 초과 주택"]]},{"종류":"표","제목":"취득으로 보는 경우(간주취득)","머리":["유형","취득으로 보는 내용","누가 취득하나"],"행":[["지목변경","토지 지목을 사실상 변경해 가액이 증가한 경우","토지 소유자"],["과점주주","법인 주식·지분을 취득해 과점주주가 된 경우(법인 설립 시 발행 주식 취득은 제외)","과점주주"],["배우자·직계존비속 취득","배우자 또는 직계존비속의 부동산등을 취득하면 증여로 봄(공매·교환·대가 지급 입증은 유상)","취득자"],["부담부증여","증여자의 채무를 인수한 부분은 유상, 나머지는 무상","수증자"],["신탁 위탁자 지위 이전","새로운 위탁자가 신탁재산을 취득한 것으로 봄","새로운 위탁자"],["주택조합 조합원용 부동산","조합원이 취득한 것으로 봄","조합원"]]}],"함정":"③은 귀속 조건 취득의 비과세 원칙과 반대급부 무상 양여 과세 단서가 한 조항에 함께 있다. 단서를 놓치면 옳은 문장으로 읽힌다. ⑤는 신탁 비과세 유형 가운데 주택조합등과 조합원 간 취득이 단서로 빠져 과세된다."}};